INSERT INTO `import_item` VALUES (160334347876958213, 160334344701870080, '默认题集', 40, '{\"stem\": \"求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。\", \"title\": \"单调区间与极值\", \"answer\": \"递增区间：$(-\\\\infty,0)\\\\cup(2,+\\\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。\", \"options\": [], \"solution\": \"$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\\\infty,0)$ 与 $(2,+\\\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.58, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958214, 160334344701870080, '默认题集', 41, '{\"stem\": \"不定积分 $\\\\displaystyle \\\\int x^2 \\\\, dx=$（  ）\", \"title\": \"幂函数积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"B\", \"content\": \"$x^3+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^2}{2}+C$\"}, {\"key\": \"D\", \"content\": \"$(3)x^2+C$\"}], \"solution\": \"用幂函数积分公式，结果为 $\\\\dfrac{x^3}{3}+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958215, 160334344701870080, '默认题集', 42, '{\"stem\": \"下列不定积分结果正确的是哪些？（多选）\", \"title\": \"基本积分公式\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}], \"solution\": \"A、B、D 正确；C 不严谨，应为 $\\\\ln|x|+C$；E 错，应为 $\\\\arctan x+C$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958216, 160334344701870080, '默认题集', 43, '{\"stem\": \"填空：$\\\\displaystyle \\\\int 2x e^{x^2}\\\\,dx=$ ____。\", \"title\": \"换元积分\", \"answer\": \"$e^{x^2}+C$\", \"options\": [], \"solution\": \"令 $u=x^2$，则 $du=2x\\\\,dx$，原式变为 $\\\\int e^u du=e^u+C=e^{x^2}+C$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.43, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958217, 160334344701870080, '默认题集', 44, '{\"stem\": \"求不定积分：$\\\\displaystyle \\\\int x\\\\ln x\\\\,dx$。\", \"title\": \"分部积分\", \"answer\": \"$\\\\dfrac{x^2}{2}\\\\ln x-\\\\dfrac{x^2}{4}+C$\", \"options\": [], \"solution\": \"分部积分，取 $u=\\\\ln x,\\\\ dv=x\\\\,dx$，则 $du=\\\\fracx dx,\\\\ v=\\\\frac{x^2}{2}$。故原式 $=\\\\frac{x^2}{2}\\\\ln x-\\\\int \\\\frac{x}{2}dx=\\\\frac{x^2}{2}\\\\ln x-\\\\frac{x^2}{4}+C$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958218, 160334344701870080, '默认题集', 45, '{\"stem\": \"不定积分 $\\\\displaystyle \\\\int x^3 \\\\, dx=$（  ）\", \"title\": \"幂函数积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^4}{4}+C$\"}, {\"key\": \"B\", \"content\": \"$x^4+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"D\", \"content\": \"$(4)x^3+C$\"}], \"solution\": \"用幂函数积分公式，结果为 $\\\\dfrac{x^4}{4}+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958219, 160334344701870080, '默认题集', 46, '{\"stem\": \"下列不定积分结果正确的是哪些？（多选）\", \"title\": \"基本积分公式\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}], \"solution\": \"A、B、D 正确；C 不严谨，应为 $\\\\ln|x|+C$；E 错，应为 $\\\\arctan x+C$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958220, 160334344701870080, '默认题集', 47, '{\"stem\": \"填空：$\\\\displaystyle \\\\int 2x e^{x^2}\\\\,dx=$ ____。\", \"title\": \"换元积分\", \"answer\": \"$e^{x^2}+C$\", \"options\": [], \"solution\": \"令 $u=x^2$，则 $du=2x\\\\,dx$，原式变为 $\\\\int e^u du=e^u+C=e^{x^2}+C$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.43, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958221, 160334344701870080, '默认题集', 48, '{\"stem\": \"求不定积分：$\\\\displaystyle \\\\int x\\\\ln x\\\\,dx$。\", \"title\": \"分部积分\", \"answer\": \"$\\\\dfrac{x^2}{2}\\\\ln x-\\\\dfrac{x^2}{4}+C$\", \"options\": [], \"solution\": \"分部积分，取 $u=\\\\ln x,\\\\ dv=x\\\\,dx$，则 $du=\\\\fracx dx,\\\\ v=\\\\frac{x^2}{2}$。故原式 $=\\\\frac{x^2}{2}\\\\ln x-\\\\int \\\\frac{x}{2}dx=\\\\frac{x^2}{2}\\\\ln x-\\\\frac{x^2}{4}+C$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958222, 160334344701870080, '默认题集', 49, '{\"stem\": \"计算定积分：$\\\\displaystyle \\\\int_0^1 2x\\\\,dx=$（  ）\", \"title\": \"定积分计算\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}], \"solution\": \"$\\\\int_0^1 2x\\\\,dx=[x^2]_0^1=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958223, 160334344701870080, '默认题集', 50, '{\"stem\": \"下列关于定积分的说法正确的是哪些？（多选）\", \"title\": \"定积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}], \"solution\": \"A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\\\int_0^a fxdx$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958224, 160334344701870080, '默认题集', 51, '{\"stem\": \"由定积分定义可得：$\\\\displaystyle \\\\int_0^2 (x+1)\\\\,dx=$ ____。\", \"title\": \"定积分求值\", \"answer\": \"$4$\", \"options\": [], \"solution\": \"$\\\\int_0^2 (x+1)dx=\\\\left[\\\\frac{x^2}{2}+x\\\\right]_0^2=2+2=4$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958225, 160334344701870080, '默认题集', 52, '{\"stem\": \"求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。\", \"title\": \"平面图形面积\", \"answer\": \"$\\\\dfrac{1}{6}$\", \"options\": [], \"solution\": \"交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\\\int_0^1 (x-x^2)dx=\\\\left[\\\\frac{x^2}{2}-\\\\frac{x^3}{3}\\\\right]_0^1=\\\\frac16$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
