INSERT INTO `import_item` VALUES (160334347876958227, 160334344701870080, '默认题集', 54, '{\"stem\": \"下列关于定积分的说法正确的是哪些？（多选）\", \"title\": \"定积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}], \"solution\": \"A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\\\int_0^a fxdx$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958228, 160334344701870080, '默认题集', 55, '{\"stem\": \"由定积分定义可得：$\\\\displaystyle \\\\int_0^2 (x+1)\\\\,dx=$ ____。\", \"title\": \"定积分求值\", \"answer\": \"$4$\", \"options\": [], \"solution\": \"$\\\\int_0^2 (x+1)dx=\\\\left[\\\\frac{x^2}{2}+x\\\\right]_0^2=2+2=4$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
