INSERT INTO `import_item` VALUES (160334347876958260, 160334344701870080, '默认题集', 87, '{\"stem\": \"求初值问题 $y\'=3x^2,\\\\ y(0)=1$ 的解：$y=$ ____。\", \"title\": \"初值问题\", \"answer\": \"$x^3+1$\", \"options\": [], \"solution\": \"积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958261, 160334344701870080, '默认题集', 88, '{\"stem\": \"求解微分方程：$y\'\'-3y\'+2y=0$。\", \"title\": \"二阶常系数方程\", \"answer\": \"$y=C_1e^x+C_2e^{2x}$\", \"options\": [], \"solution\": \"特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958262, 160334344701870080, '默认题集', 89, '{\"stem\": \"微分方程 $y\'=2x$ 的通解为（  ）\", \"title\": \"通解求法\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}], \"solution\": \"两边积分得 $y=\\\\int 2x\\\\,dx=x^2+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958263, 160334344701870080, '默认题集', 90, '{\"stem\": \"下列关于常微分方程的说法正确的是哪些？（多选）\", \"title\": \"微分方程基础\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}], \"solution\": \"A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
