INSERT INTO `import_item` VALUES (160334347876958268, 160334344701870080, '默认题集', 95, '{\"stem\": \"填空：$\\\\displaystyle \\\\sum_{n=0}^{\\\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。\", \"title\": \"几何级数求和\", \"answer\": \"$\\\\dfrac{1}{1-x}$\", \"options\": [], \"solution\": \"这是公比为 $x$ 的几何级数，和公式为 $\\\\frac{1}{1-x}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958269, 160334344701870080, '默认题集', 96, '{\"stem\": \"写出函数 $\\\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。\", \"title\": \"幂级数展开\", \"answer\": \"$\\\\ln(1+x)=x-\\\\dfrac{x^2}{2}+\\\\dfrac{x^3}{3}-\\\\cdots=\\\\sum_{n=1}^{\\\\infty}(-1)^{n-1}\\\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。\", \"options\": [], \"solution\": \"这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\\\sum \\\\frac1n$ 发散。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.62, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958270, 160334344701870080, '默认题集', 97, '{\"stem\": \"级数 $\\\\displaystyle \\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$ 的敛散性为（  ）\", \"title\": \"级数敛散性\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958271, 160334344701870080, '默认题集', 98, '{\"stem\": \"下列关于无穷级数的说法正确的是哪些？（多选）\", \"title\": \"级数基本结论\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}], \"solution\": \"A、B、D、E 正确；C 错，交错调和级数只是条件收敛。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958272, 160334344701870080, '默认题集', 99, '{\"stem\": \"填空：$\\\\displaystyle \\\\sum_{n=0}^{\\\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。\", \"title\": \"几何级数求和\", \"answer\": \"$\\\\dfrac{1}{1-x}$\", \"options\": [], \"solution\": \"这是公比为 $x$ 的几何级数，和公式为 $\\\\frac{1}{1-x}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
