INSERT INTO `import_item` VALUES (160334347876958274, 160334344701870080, '默认题集', 101, '{\"stem\": \"级数 $\\\\displaystyle \\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$ 的敛散性为（  ）\", \"title\": \"级数敛散性\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958275, 160334344701870080, '默认题集', 102, '{\"stem\": \"下列关于无穷级数的说法正确的是哪些？（多选）\", \"title\": \"级数基本结论\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}], \"solution\": \"A、B、D、E 正确；C 错，交错调和级数只是条件收敛。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958276, 160334344701870080, '默认题集', 103, '{\"stem\": \"填空：$\\\\displaystyle \\\\sum_{n=0}^{\\\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。\", \"title\": \"几何级数求和\", \"answer\": \"$\\\\dfrac{1}{1-x}$\", \"options\": [], \"solution\": \"这是公比为 $x$ 的几何级数，和公式为 $\\\\frac{1}{1-x}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958277, 160334344701870080, '默认题集', 104, '{\"stem\": \"写出函数 $\\\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。\", \"title\": \"幂级数展开\", \"answer\": \"$\\\\ln(1+x)=x-\\\\dfrac{x^2}{2}+\\\\dfrac{x^3}{3}-\\\\cdots=\\\\sum_{n=1}^{\\\\infty}(-1)^{n-1}\\\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。\", \"options\": [], \"solution\": \"这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\\\sum \\\\frac1n$ 发散。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.62, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958278, 160334344701870080, '默认题集', 105, '{\"stem\": \"计算行列式 $\\\\begin{vmatrix}1&2\\\\\\\\3&4\\\\end{vmatrix}=$（  ）\", \"title\": \"二阶行列式\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}], \"solution\": \"$1\\\\cdot4-2\\\\cdot3=-2$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958279, 160334344701870080, '默认题集', 106, '{\"stem\": \"下列关于行列式的说法正确的是哪些？（多选）\", \"title\": \"行列式性质\", \"answer\": \"ABE\", \"options\": [{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}], \"solution\": \"A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958280, 160334344701870080, '默认题集', 107, '{\"stem\": \"填空：$\\\\begin{vmatrix}2&0&0\\\\\\\\1&3&0\\\\\\\\4&5&6\\\\end{vmatrix}=$ ____。\", \"title\": \"三角行列式\", \"answer\": \"$36$\", \"options\": [], \"solution\": \"下三角行列式等于主对角线元素之积，故为 $2\\\\cdot3\\\\cdot6=36$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958281, 160334344701870080, '默认题集', 108, '{\"stem\": \"计算行列式：$\\\\begin{vmatrix}1&1&1\\\\\\\\1&2&3\\\\\\\\1&3&6\\\\end{vmatrix}$。\", \"title\": \"三阶行列式计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"可作行变换：$R_2\\\\leftarrow R_2-R_1,\\\\ R_3\\\\leftarrow R_3-R_1$，得 $\\\\begin{vmatrix}1&1&1\\\\\\\\0&1&2\\\\\\\\0&2&5\\\\end{vmatrix}$，再按第一列展开得 $\\\\begin{vmatrix}1&2\\\\\\\\2&5\\\\end{vmatrix}=1$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958282, 160334344701870080, '默认题集', 109, '{\"stem\": \"计算行列式 $\\\\begin{vmatrix}1&2\\\\\\\\3&4\\\\end{vmatrix}=$（  ）\", \"title\": \"二阶行列式\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}], \"solution\": \"$1\\\\cdot4-2\\\\cdot3=-2$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
