INSERT INTO `import_item` VALUES (160334347876958294, 160334344701870080, '默认题集', 121, '{\"stem\": \"向量组 $\\\\alpha_1=(1,0),\\\\ \\\\alpha_2=(0,1)$ 在 $\\\\mathbb{R}^2$ 中（  ）\", \"title\": \"线性相关判断\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"这两个向量是标准基，互不成比例，线性无关。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347876958295, 160334344701870080, '默认题集', 122, '{\"stem\": \"下列说法正确的是哪些？（多选）\", \"title\": \"线性相关与秩\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}], \"solution\": \"A、B、C、E 正确；D 错，不平行反而线性无关。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
