INSERT INTO `import_item` VALUES (160334347876958301, 160334344701870080, '默认题集', 128, '{\"stem\": \"判断向量组 $\\\\alpha_1=(1,1,0),\\\\ \\\\alpha_2=(1,0,1),\\\\ \\\\alpha_3=(0,1,1)$ 是否线性无关。\", \"title\": \"向量组线性无关\", \"answer\": \"线性无关。\", \"options\": [], \"solution\": \"以这三个向量为列组成矩阵 $A=\\\\begin{pmatrix}1&1&0\\\\\\\\1&0&1\\\\\\\\0&1&1\\\\end{pmatrix}$，其行列式为 $-2\\\\ne0$，故三向量线性无关。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.54, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
