INSERT INTO `import_item` VALUES (160334347939872777, 160334344701870080, '默认题集', 151, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872778, 160334344701870080, '默认题集', 152, '{\"stem\": \"设事件 $A,B$ 满足 $P(B)=0.6,\\\\ P(A|B)=0.5,\\\\ P(A|\\\\bar B)=0.2$，求 $P(A)$。\", \"title\": \"全概率公式\", \"answer\": \"$0.38$\", \"options\": [], \"solution\": \"由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\\\bar B)P(\\\\bar B)=0.5\\\\times0.6+0.2\\\\times0.4=0.38$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872779, 160334344701870080, '默认题集', 153, '{\"stem\": \"设 $P(A)=0.4,\\\\ P(B)=0.5,\\\\ P(A\\\\cap B)=0.2$，则 $P(A\\\\cup B)=$（  ）\", \"title\": \"事件并概率\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}], \"solution\": \"用加法公式：$P(A\\\\cup B)=P(A)+P(B)-P(A\\\\cap B)=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872780, 160334344701870080, '默认题集', 154, '{\"stem\": \"下列关于概率论基础的说法正确的是哪些？（多选）\", \"title\": \"概率基础公式\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}], \"solution\": \"A、B、D、E 正确；C 错，互斥且概率都非零时不独立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872781, 160334344701870080, '默认题集', 155, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872782, 160334344701870080, '默认题集', 156, '{\"stem\": \"设事件 $A,B$ 满足 $P(B)=0.6,\\\\ P(A|B)=0.5,\\\\ P(A|\\\\bar B)=0.2$，求 $P(A)$。\", \"title\": \"全概率公式\", \"answer\": \"$0.38$\", \"options\": [], \"solution\": \"由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\\\bar B)P(\\\\bar B)=0.5\\\\times0.6+0.2\\\\times0.4=0.38$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872783, 160334344701870080, '默认题集', 157, '{\"stem\": \"设 $P(A)=0.4,\\\\ P(B)=0.5,\\\\ P(A\\\\cap B)=0.2$，则 $P(A\\\\cup B)=$（  ）\", \"title\": \"事件并概率\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}], \"solution\": \"用加法公式：$P(A\\\\cup B)=P(A)+P(B)-P(A\\\\cap B)=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872784, 160334344701870080, '默认题集', 158, '{\"stem\": \"下列关于概率论基础的说法正确的是哪些？（多选）\", \"title\": \"概率基础公式\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}], \"solution\": \"A、B、D、E 正确；C 错，互斥且概率都非零时不独立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872785, 160334344701870080, '默认题集', 159, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872786, 160334344701870080, '默认题集', 160, '{\"stem\": \"设事件 $A,B$ 满足 $P(B)=0.6,\\\\ P(A|B)=0.5,\\\\ P(A|\\\\bar B)=0.2$，求 $P(A)$。\", \"title\": \"全概率公式\", \"answer\": \"$0.38$\", \"options\": [], \"solution\": \"由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\\\bar B)P(\\\\bar B)=0.5\\\\times0.6+0.2\\\\times0.4=0.38$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872787, 160334344701870080, '默认题集', 161, '{\"stem\": \"设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\\\le1)=$（  ）\", \"title\": \"分布列计算\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}], \"solution\": \"$P(X\\\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872788, 160334344701870080, '默认题集', 162, '{\"stem\": \"下列关于随机变量分布的说法正确的是哪些？（多选）\", \"title\": \"分布函数与密度\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}], \"solution\": \"A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872789, 160334344701870080, '默认题集', 163, '{\"stem\": \"设连续型随机变量 $X$ 的密度 $fx=\\\\begin{cases}2x,&0<x<1\\\\\\\\0,&\\\\text{其他}\\\\end{cases}$，则 $P(X<\\\\tfrac12)=$ ____。\", \"title\": \"密度函数求概率\", \"answer\": \"$\\\\dfrac{1}{4}$\", \"options\": [], \"solution\": \"$P(X<\\\\frac12)=\\\\int_0^{1/2}2x\\\\,dx=\\\\left[x^2\\\\right]_0^{1/2}=\\\\frac14$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872790, 160334344701870080, '默认题集', 164, '{\"stem\": \"设随机变量 $X$ 的分布函数为 $Fx=\\\\begin{cases}0,&x<0\\\\\\\\x^2,&0\\\\le x<1\\\\\\\\1,&x\\\\ge1\\\\end{cases}$。求 $P(\\\\tfrac12<X\\\\le1)$。\", \"title\": \"分布函数求概率\", \"answer\": \"$\\\\dfrac{3}{4}$\", \"options\": [], \"solution\": \"$P(\\\\frac12<X\\\\le1)=F(1)-F(\\\\frac12)=1-\\\\frac14=\\\\frac34$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872791, 160334344701870080, '默认题集', 165, '{\"stem\": \"设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\\\le1)=$（  ）\", \"title\": \"分布列计算\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}], \"solution\": \"$P(X\\\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 10:31:27');
