INSERT INTO `import_item` VALUES (160334347939872793, 160334344701870080, '默认题集', 167, '{\"stem\": \"设连续型随机变量 $X$ 的密度 $fx=\\\\begin{cases}2x,&0<x<1\\\\\\\\0,&\\\\text{其他}\\\\end{cases}$，则 $P(X<\\\\tfrac12)=$ ____。\", \"title\": \"密度函数求概率\", \"answer\": \"$\\\\dfrac{1}{4}$\", \"options\": [], \"solution\": \"$P(X<\\\\frac12)=\\\\int_0^{1/2}2x\\\\,dx=\\\\left[x^2\\\\right]_0^{1/2}=\\\\frac14$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
