INSERT INTO `import_item` VALUES (160334347939872795, 160334344701870080, '默认题集', 169, '{\"stem\": \"若 $X\\\\sim B(2,0.5)$，则 $P(X=1)=$（  ）\", \"title\": \"二项分布\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}], \"solution\": \"$P(X=1)=\\\\binom21(0.5)^1(0.5)^1=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872796, 160334344701870080, '默认题集', 170, '{\"stem\": \"下列关于常见分布的说法正确的是哪些？（多选）\", \"title\": \"常见分布性质\", \"answer\": \"ABCD\", \"options\": [{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}], \"solution\": \"A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"D\"]}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872797, 160334344701870080, '默认题集', 171, '{\"stem\": \"设 $X\\\\sim Poisson(\\\\lambda=2)$，则 $P(X=0)=$ ____。\", \"title\": \"泊松分布\", \"answer\": \"$e^{-2}$\", \"options\": [], \"solution\": \"泊松分布概率公式：$P(X=k)=e^{-\\\\lambda}\\\\frac{\\\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872798, 160334344701870080, '默认题集', 172, '{\"stem\": \"设 $X\\\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。\", \"title\": \"正态分布对称性\", \"answer\": \"$P(X>0)=\\\\dfrac12$\", \"options\": [], \"solution\": \"标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\\\frac12$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 10:31:27');
INSERT INTO `import_item` VALUES (160334347939872799, 160334344701870080, '默认题集', 173, '{\"stem\": \"若 $X\\\\sim B(2,0.5)$，则 $P(X=1)=$（  ）\", \"title\": \"二项分布\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}], \"solution\": \"$P(X=1)=\\\\binom21(0.5)^1(0.5)^1=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 10:31:27');
