INSERT INTO `import_item` VALUES (160466528322453558, 160466525063479297, '默认题集', 59, '{\"stem\": \"设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。\", \"title\": \"全微分计算\", \"answer\": \"$3dx+3dy$\", \"options\": [], \"solution\": \"$z_x=2xy+y^2,\\\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453559, 160466525063479297, '默认题集', 60, '{\"stem\": \"设 $z=e^{xy}$，求 $\\\\dfrac{\\\\partial z}{\\\\partial x}$ 与 $\\\\dfrac{\\\\partial z}{\\\\partial y}$。\", \"title\": \"复合函数偏导\", \"answer\": \"$\\\\dfrac{\\\\partial z}{\\\\partial x}=ye^{xy},\\\\quad \\\\dfrac{\\\\partial z}{\\\\partial y}=xe^{xy}$\", \"options\": [], \"solution\": \"对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\\\cdot y$；同理 $z_y=e^{xy}\\\\cdot x$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.44, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453560, 160466525063479297, '默认题集', 61, '{\"stem\": \"设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）\", \"title\": \"求偏导数\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}], \"solution\": \"把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453561, 160466525063479297, '默认题集', 62, '{\"stem\": \"下列关于多元函数求导的说法正确的是哪些？（多选）\", \"title\": \"偏导与全微分性质\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}], \"solution\": \"A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453562, 160466525063479297, '默认题集', 63, '{\"stem\": \"设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。\", \"title\": \"全微分计算\", \"answer\": \"$3dx+3dy$\", \"options\": [], \"solution\": \"$z_x=2xy+y^2,\\\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453563, 160466525063479297, '默认题集', 64, '{\"stem\": \"设 $z=e^{xy}$，求 $\\\\dfrac{\\\\partial z}{\\\\partial x}$ 与 $\\\\dfrac{\\\\partial z}{\\\\partial y}$。\", \"title\": \"复合函数偏导\", \"answer\": \"$\\\\dfrac{\\\\partial z}{\\\\partial x}=ye^{xy},\\\\quad \\\\dfrac{\\\\partial z}{\\\\partial y}=xe^{xy}$\", \"options\": [], \"solution\": \"对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\\\cdot y$；同理 $z_y=e^{xy}\\\\cdot x$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.44, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453564, 160466525063479297, '默认题集', 65, '{\"stem\": \"设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）\", \"title\": \"求偏导数\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}], \"solution\": \"把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453565, 160466525063479297, '默认题集', 66, '{\"stem\": \"下列关于多元函数求导的说法正确的是哪些？（多选）\", \"title\": \"偏导与全微分性质\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}], \"solution\": \"A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453566, 160466525063479297, '默认题集', 67, '{\"stem\": \"求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。\", \"title\": \"极小值计算\", \"answer\": \"$-5$\", \"options\": [], \"solution\": \"配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453567, 160466525063479297, '默认题集', 68, '{\"stem\": \"用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。\", \"title\": \"拉格朗日乘数法\", \"answer\": \"在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\\\infty$）。\", \"options\": [], \"solution\": \"设 $L=xy+\\\\lambda(x+y-2)$。由 $L_x=y+\\\\lambda=0,\\\\ L_y=x+\\\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.62, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453568, 160466525063479297, '默认题集', 69, '{\"stem\": \"函数 $f(x,y)=x^2+y^2$ 在 $(0,0)$ 处取得（  ）\", \"title\": \"二元函数极值\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"极大值\"}, {\"key\": \"B\", \"content\": \"极小值\"}, {\"key\": \"C\", \"content\": \"鞍点\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"$x^2+y^2\\\\ge0$，且仅在 $(0,0)$ 取到 $0$，故为极小值。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528322453569, 160466525063479297, '默认题集', 70, '{\"stem\": \"下列关于多元函数极值的说法正确的是哪些？（多选）\", \"title\": \"多元极值理论\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"求条件极值常用拉格朗日乘数法\"}, {\"key\": \"B\", \"content\": \"驻点是偏导都为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"Hessian 判别法中 $D=f_{xx}f_{yy}-f_{xy}^2$，若 $D>0$ 且 $f_{xx}>0$，则为极小值\"}, {\"key\": \"D\", \"content\": \"条件极值与无条件极值的驻点条件完全相同\"}, {\"key\": \"E\", \"content\": \"鞍点既不是极大值点，也不是极小值点\"}], \"solution\": \"A、B、C、E 正确；D 错，条件极值还要结合约束方程。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.57, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
