INSERT INTO `import_item` VALUES (160466528322453576, 160466525063479297, '默认题集', 77, '{\"stem\": \"计算二重积分：$\\\\displaystyle \\\\iint_{[0,1]\\\\times[0,1]}(x+y)\\\\,dA=$（  ）\", \"title\": \"矩形区域二重积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}], \"solution\": \"$\\\\int_0^1\\\\int_0^1 (x+y)dxdy=\\\\int_0^1(\\\\frac12+y)dy=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562368, 160466525063479297, '默认题集', 78, '{\"stem\": \"下列关于二重积分的说法正确的是哪些？（多选）\", \"title\": \"二重积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}], \"solution\": \"A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562369, 160466525063479297, '默认题集', 79, '{\"stem\": \"填空：$\\\\displaystyle \\\\iint_{x^2+y^2\\\\le 1}1\\\\,dA=$ ____。\", \"title\": \"区域面积\", \"answer\": \"$\\\\pi$\", \"options\": [], \"solution\": \"被积函数为 $1$，积分等于单位圆面积，所以为 $\\\\pi$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562370, 160466525063479297, '默认题集', 80, '{\"stem\": \"用极坐标计算二重积分：$\\\\displaystyle \\\\iint_{x^2+y^2\\\\le 4}(x^2+y^2)\\\\,dA$。\", \"title\": \"极坐标二重积分\", \"answer\": \"$8\\\\pi$\", \"options\": [], \"solution\": \"极坐标下 $x^2+y^2=r^2,\\\\ dA=rdrd\\\\theta$。原式 $=\\\\int_0^{2\\\\pi}\\\\int_0^2 r^3drd\\\\theta=2\\\\pi\\\\cdot\\\\left[\\\\frac{r^4}{4}\\\\right]_0^2=8\\\\pi$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.54, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
