INSERT INTO `import_item` VALUES (160466528389562377, 160466525063479297, '默认题集', 87, '{\"stem\": \"求初值问题 $y\'=3x^2,\\\\ y(0)=1$ 的解：$y=$ ____。\", \"title\": \"初值问题\", \"answer\": \"$x^3+1$\", \"options\": [], \"solution\": \"积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562378, 160466525063479297, '默认题集', 88, '{\"stem\": \"求解微分方程：$y\'\'-3y\'+2y=0$。\", \"title\": \"二阶常系数方程\", \"answer\": \"$y=C_1e^x+C_2e^{2x}$\", \"options\": [], \"solution\": \"特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562379, 160466525063479297, '默认题集', 89, '{\"stem\": \"微分方程 $y\'=2x$ 的通解为（  ）\", \"title\": \"通解求法\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}], \"solution\": \"两边积分得 $y=\\\\int 2x\\\\,dx=x^2+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
