INSERT INTO `import_item` VALUES (160466528389562382, 160466525063479297, '默认题集', 92, '{\"stem\": \"求解微分方程：$y\'\'-3y\'+2y=0$。\", \"title\": \"二阶常系数方程\", \"answer\": \"$y=C_1e^x+C_2e^{2x}$\", \"options\": [], \"solution\": \"特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562383, 160466525063479297, '默认题集', 93, '{\"stem\": \"微分方程 $y\'=2x$ 的通解为（  ）\", \"title\": \"通解求法\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}], \"solution\": \"两边积分得 $y=\\\\int 2x\\\\,dx=x^2+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562384, 160466525063479297, '默认题集', 94, '{\"stem\": \"下列关于常微分方程的说法正确的是哪些？（多选）\", \"title\": \"微分方程基础\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}], \"solution\": \"A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562385, 160466525063479297, '默认题集', 95, '{\"stem\": \"填空：$\\\\displaystyle \\\\sum_{n=0}^{\\\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。\", \"title\": \"几何级数求和\", \"answer\": \"$\\\\dfrac{1}{1-x}$\", \"options\": [], \"solution\": \"这是公比为 $x$ 的几何级数，和公式为 $\\\\frac{1}{1-x}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562386, 160466525063479297, '默认题集', 96, '{\"stem\": \"写出函数 $\\\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。\", \"title\": \"幂级数展开\", \"answer\": \"$\\\\ln(1+x)=x-\\\\dfrac{x^2}{2}+\\\\dfrac{x^3}{3}-\\\\cdots=\\\\sum_{n=1}^{\\\\infty}(-1)^{n-1}\\\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。\", \"options\": [], \"solution\": \"这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\\\sum \\\\frac1n$ 发散。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.62, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562387, 160466525063479297, '默认题集', 97, '{\"stem\": \"级数 $\\\\displaystyle \\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$ 的敛散性为（  ）\", \"title\": \"级数敛散性\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562388, 160466525063479297, '默认题集', 98, '{\"stem\": \"下列关于无穷级数的说法正确的是哪些？（多选）\", \"title\": \"级数基本结论\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}], \"solution\": \"A、B、D、E 正确；C 错，交错调和级数只是条件收敛。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
