INSERT INTO `import_item` VALUES (160466528389562395, 160466525063479297, '默认题集', 105, '{\"stem\": \"计算行列式 $\\\\begin{vmatrix}1&2\\\\\\\\3&4\\\\end{vmatrix}=$（  ）\", \"title\": \"二阶行列式\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}], \"solution\": \"$1\\\\cdot4-2\\\\cdot3=-2$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562396, 160466525063479297, '默认题集', 106, '{\"stem\": \"下列关于行列式的说法正确的是哪些？（多选）\", \"title\": \"行列式性质\", \"answer\": \"ABE\", \"options\": [{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}], \"solution\": \"A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562397, 160466525063479297, '默认题集', 107, '{\"stem\": \"填空：$\\\\begin{vmatrix}2&0&0\\\\\\\\1&3&0\\\\\\\\4&5&6\\\\end{vmatrix}=$ ____。\", \"title\": \"三角行列式\", \"answer\": \"$36$\", \"options\": [], \"solution\": \"下三角行列式等于主对角线元素之积，故为 $2\\\\cdot3\\\\cdot6=36$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562398, 160466525063479297, '默认题集', 108, '{\"stem\": \"计算行列式：$\\\\begin{vmatrix}1&1&1\\\\\\\\1&2&3\\\\\\\\1&3&6\\\\end{vmatrix}$。\", \"title\": \"三阶行列式计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"可作行变换：$R_2\\\\leftarrow R_2-R_1,\\\\ R_3\\\\leftarrow R_3-R_1$，得 $\\\\begin{vmatrix}1&1&1\\\\\\\\0&1&2\\\\\\\\0&2&5\\\\end{vmatrix}$，再按第一列展开得 $\\\\begin{vmatrix}1&2\\\\\\\\2&5\\\\end{vmatrix}=1$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562399, 160466525063479297, '默认题集', 109, '{\"stem\": \"计算行列式 $\\\\begin{vmatrix}1&2\\\\\\\\3&4\\\\end{vmatrix}=$（  ）\", \"title\": \"二阶行列式\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}], \"solution\": \"$1\\\\cdot4-2\\\\cdot3=-2$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562400, 160466525063479297, '默认题集', 110, '{\"stem\": \"下列关于行列式的说法正确的是哪些？（多选）\", \"title\": \"行列式性质\", \"answer\": \"ABE\", \"options\": [{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}], \"solution\": \"A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562401, 160466525063479297, '默认题集', 111, '{\"stem\": \"填空：$\\\\begin{vmatrix}2&0&0\\\\\\\\1&3&0\\\\\\\\4&5&6\\\\end{vmatrix}=$ ____。\", \"title\": \"三角行列式\", \"answer\": \"$36$\", \"options\": [], \"solution\": \"下三角行列式等于主对角线元素之积，故为 $2\\\\cdot3\\\\cdot6=36$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562402, 160466525063479297, '默认题集', 112, '{\"stem\": \"计算行列式：$\\\\begin{vmatrix}1&1&1\\\\\\\\1&2&3\\\\\\\\1&3&6\\\\end{vmatrix}$。\", \"title\": \"三阶行列式计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"可作行变换：$R_2\\\\leftarrow R_2-R_1,\\\\ R_3\\\\leftarrow R_3-R_1$，得 $\\\\begin{vmatrix}1&1&1\\\\\\\\0&1&2\\\\\\\\0&2&5\\\\end{vmatrix}$，再按第一列展开得 $\\\\begin{vmatrix}1&2\\\\\\\\2&5\\\\end{vmatrix}=1$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562403, 160466525063479297, '默认题集', 113, '{\"stem\": \"设 $A=\\\\begin{pmatrix}1&2\\\\\\\\0&1\\\\end{pmatrix},\\\\ B=\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$，则 $AB=$（  ）\", \"title\": \"矩阵乘法\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}], \"solution\": \"按矩阵乘法计算：$AB=\\\\begin{pmatrix}1\\\\cdot2+2\\\\cdot1 & 1\\\\cdot0+2\\\\cdot3\\\\\\\\ 0\\\\cdot2+1\\\\cdot1 & 0\\\\cdot0+1\\\\cdot3\\\\end{pmatrix}=\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562404, 160466525063479297, '默认题集', 114, '{\"stem\": \"下列关于矩阵运算的说法正确的是哪些？（多选）\", \"title\": \"矩阵与逆矩阵性质\", \"answer\": \"ABC\", \"options\": [{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}], \"solution\": \"A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.53, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562405, 160466525063479297, '默认题集', 115, '{\"stem\": \"设 $A=\\\\begin{pmatrix}1&0\\\\\\\\0&2\\\\end{pmatrix}$，则 $A^{-1}=$ ____。\", \"title\": \"逆矩阵\", \"answer\": \"$\\\\begin{pmatrix}1&0\\\\\\\\0&\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"对角矩阵求逆就是对角元分别取倒数。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562406, 160466525063479297, '默认题集', 116, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}1&2\\\\\\\\3&4\\\\end{pmatrix}$ 的逆矩阵。\", \"title\": \"二阶矩阵求逆\", \"answer\": \"$A^{-1}=\\\\begin{pmatrix}-2&1\\\\\\\\ \\\\frac32&-\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"二阶矩阵逆公式：$A^{-1}=\\\\frac{1}{ad-bc}\\\\begin{pmatrix}d&-b\\\\\\\\-c&a\\\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
