INSERT INTO `import_item` VALUES (160466528389562409, 160466525063479297, '默认题集', 119, '{\"stem\": \"设 $A=\\\\begin{pmatrix}1&0\\\\\\\\0&2\\\\end{pmatrix}$，则 $A^{-1}=$ ____。\", \"title\": \"逆矩阵\", \"answer\": \"$\\\\begin{pmatrix}1&0\\\\\\\\0&\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"对角矩阵求逆就是对角元分别取倒数。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562410, 160466525063479297, '默认题集', 120, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}1&2\\\\\\\\3&4\\\\end{pmatrix}$ 的逆矩阵。\", \"title\": \"二阶矩阵求逆\", \"answer\": \"$A^{-1}=\\\\begin{pmatrix}-2&1\\\\\\\\ \\\\frac32&-\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"二阶矩阵逆公式：$A^{-1}=\\\\frac{1}{ad-bc}\\\\begin{pmatrix}d&-b\\\\\\\\-c&a\\\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562411, 160466525063479297, '默认题集', 121, '{\"stem\": \"向量组 $\\\\alpha_1=(1,0),\\\\ \\\\alpha_2=(0,1)$ 在 $\\\\mathbb{R}^2$ 中（  ）\", \"title\": \"线性相关判断\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}], \"solution\": \"这两个向量是标准基，互不成比例，线性无关。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562412, 160466525063479297, '默认题集', 122, '{\"stem\": \"下列说法正确的是哪些？（多选）\", \"title\": \"线性相关与秩\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}], \"solution\": \"A、B、C、E 正确；D 错，不平行反而线性无关。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562413, 160466525063479297, '默认题集', 123, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}1&2\\\\\\\\2&4\\\\end{pmatrix}$ 的秩为 ____。\", \"title\": \"矩阵秩\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"第二行是第一行的 2 倍，因此只有一行线性无关，秩为 1。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562414, 160466525063479297, '默认题集', 124, '{\"stem\": \"判断向量组 $\\\\alpha_1=(1,1,0),\\\\ \\\\alpha_2=(1,0,1),\\\\ \\\\alpha_3=(0,1,1)$ 是否线性无关。\", \"title\": \"向量组线性无关\", \"answer\": \"线性无关。\", \"options\": [], \"solution\": \"以这三个向量为列组成矩阵 $A=\\\\begin{pmatrix}1&1&0\\\\\\\\1&0&1\\\\\\\\0&1&1\\\\end{pmatrix}$，其行列式为 $-2\\\\ne0$，故三向量线性无关。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.54, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
