INSERT INTO `import_item` VALUES (160466528389562431, 160466525063479297, '默认题集', 141, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}2&0\\\\\\\\0&3\\\\end{pmatrix}$ 的特征值为（  ）\", \"title\": \"特征值\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}], \"solution\": \"对角矩阵的特征值就是主对角线元素。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
