INSERT INTO `import_item` VALUES (160466528389562434, 160466525063479297, '默认题集', 144, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}2&1\\\\\\\\0&2\\\\end{pmatrix}$ 的特征值与特征向量。\", \"title\": \"特征向量求解\", \"answer\": \"特征值只有 $\\\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\\\begin{pmatrix}1\\\\\\\\0\\\\end{pmatrix}$ 的任意非零倍。\", \"options\": [], \"solution\": \"特征多项式为 $(2-\\\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\\\begin{pmatrix}0&1\\\\\\\\0&0\\\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
