INSERT INTO `import_item` VALUES (160466528389562437, 160466525063479297, '默认题集', 147, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}1&0\\\\\\\\0&1\\\\end{pmatrix}$ 的唯一特征值为 ____。\", \"title\": \"单位矩阵特征值\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"单位矩阵满足 $Ax=x$，故唯一特征值为 1。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562438, 160466525063479297, '默认题集', 148, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}2&1\\\\\\\\0&2\\\\end{pmatrix}$ 的特征值与特征向量。\", \"title\": \"特征向量求解\", \"answer\": \"特征值只有 $\\\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\\\begin{pmatrix}1\\\\\\\\0\\\\end{pmatrix}$ 的任意非零倍。\", \"options\": [], \"solution\": \"特征多项式为 $(2-\\\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\\\begin{pmatrix}0&1\\\\\\\\0&0\\\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562439, 160466525063479297, '默认题集', 149, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}2&0\\\\\\\\0&3\\\\end{pmatrix}$ 的特征值为（  ）\", \"title\": \"特征值\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}], \"solution\": \"对角矩阵的特征值就是主对角线元素。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562440, 160466525063479297, '默认题集', 150, '{\"stem\": \"下列说法正确的是哪些？（多选）\", \"title\": \"特征值与对角化性质\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}], \"solution\": \"A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.6, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562441, 160466525063479297, '默认题集', 151, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562442, 160466525063479297, '默认题集', 152, '{\"stem\": \"设事件 $A,B$ 满足 $P(B)=0.6,\\\\ P(A|B)=0.5,\\\\ P(A|\\\\bar B)=0.2$，求 $P(A)$。\", \"title\": \"全概率公式\", \"answer\": \"$0.38$\", \"options\": [], \"solution\": \"由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\\\bar B)P(\\\\bar B)=0.5\\\\times0.6+0.2\\\\times0.4=0.38$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562443, 160466525063479297, '默认题集', 153, '{\"stem\": \"设 $P(A)=0.4,\\\\ P(B)=0.5,\\\\ P(A\\\\cap B)=0.2$，则 $P(A\\\\cup B)=$（  ）\", \"title\": \"事件并概率\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}], \"solution\": \"用加法公式：$P(A\\\\cup B)=P(A)+P(B)-P(A\\\\cap B)=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562444, 160466525063479297, '默认题集', 154, '{\"stem\": \"下列关于概率论基础的说法正确的是哪些？（多选）\", \"title\": \"概率基础公式\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}], \"solution\": \"A、B、D、E 正确；C 错，互斥且概率都非零时不独立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528389562445, 160466525063479297, '默认题集', 155, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
