INSERT INTO `import_item` VALUES (160466528452476929, 160466525063479297, '默认题集', 161, '{\"stem\": \"设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\\\le1)=$（  ）\", \"title\": \"分布列计算\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}], \"solution\": \"$P(X\\\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476930, 160466525063479297, '默认题集', 162, '{\"stem\": \"下列关于随机变量分布的说法正确的是哪些？（多选）\", \"title\": \"分布函数与密度\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}], \"solution\": \"A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476931, 160466525063479297, '默认题集', 163, '{\"stem\": \"设连续型随机变量 $X$ 的密度 $fx=\\\\begin{cases}2x,&0<x<1\\\\\\\\0,&\\\\text{其他}\\\\end{cases}$，则 $P(X<\\\\tfrac12)=$ ____。\", \"title\": \"密度函数求概率\", \"answer\": \"$\\\\dfrac{1}{4}$\", \"options\": [], \"solution\": \"$P(X<\\\\frac12)=\\\\int_0^{1/2}2x\\\\,dx=\\\\left[x^2\\\\right]_0^{1/2}=\\\\frac14$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476932, 160466525063479297, '默认题集', 164, '{\"stem\": \"设随机变量 $X$ 的分布函数为 $Fx=\\\\begin{cases}0,&x<0\\\\\\\\x^2,&0\\\\le x<1\\\\\\\\1,&x\\\\ge1\\\\end{cases}$。求 $P(\\\\tfrac12<X\\\\le1)$。\", \"title\": \"分布函数求概率\", \"answer\": \"$\\\\dfrac{3}{4}$\", \"options\": [], \"solution\": \"$P(\\\\frac12<X\\\\le1)=F(1)-F(\\\\frac12)=1-\\\\frac14=\\\\frac34$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476933, 160466525063479297, '默认题集', 165, '{\"stem\": \"设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\\\le1)=$（  ）\", \"title\": \"分布列计算\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}], \"solution\": \"$P(X\\\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.36, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476934, 160466525063479297, '默认题集', 166, '{\"stem\": \"下列关于随机变量分布的说法正确的是哪些？（多选）\", \"title\": \"分布函数与密度\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}], \"solution\": \"A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476935, 160466525063479297, '默认题集', 167, '{\"stem\": \"设连续型随机变量 $X$ 的密度 $fx=\\\\begin{cases}2x,&0<x<1\\\\\\\\0,&\\\\text{其他}\\\\end{cases}$，则 $P(X<\\\\tfrac12)=$ ____。\", \"title\": \"密度函数求概率\", \"answer\": \"$\\\\dfrac{1}{4}$\", \"options\": [], \"solution\": \"$P(X<\\\\frac12)=\\\\int_0^{1/2}2x\\\\,dx=\\\\left[x^2\\\\right]_0^{1/2}=\\\\frac14$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476936, 160466525063479297, '默认题集', 168, '{\"stem\": \"设随机变量 $X$ 的分布函数为 $Fx=\\\\begin{cases}0,&x<0\\\\\\\\x^2,&0\\\\le x<1\\\\\\\\1,&x\\\\ge1\\\\end{cases}$。求 $P(\\\\tfrac12<X\\\\le1)$。\", \"title\": \"分布函数求概率\", \"answer\": \"$\\\\dfrac{3}{4}$\", \"options\": [], \"solution\": \"$P(\\\\frac12<X\\\\le1)=F(1)-F(\\\\frac12)=1-\\\\frac14=\\\\frac34$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476937, 160466525063479297, '默认题集', 169, '{\"stem\": \"若 $X\\\\sim B(2,0.5)$，则 $P(X=1)=$（  ）\", \"title\": \"二项分布\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}], \"solution\": \"$P(X=1)=\\\\binom21(0.5)^1(0.5)^1=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476938, 160466525063479297, '默认题集', 170, '{\"stem\": \"下列关于常见分布的说法正确的是哪些？（多选）\", \"title\": \"常见分布性质\", \"answer\": \"ABCD\", \"options\": [{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}], \"solution\": \"A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"D\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476939, 160466525063479297, '默认题集', 171, '{\"stem\": \"设 $X\\\\sim Poisson(\\\\lambda=2)$，则 $P(X=0)=$ ____。\", \"title\": \"泊松分布\", \"answer\": \"$e^{-2}$\", \"options\": [], \"solution\": \"泊松分布概率公式：$P(X=k)=e^{-\\\\lambda}\\\\frac{\\\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476940, 160466525063479297, '默认题集', 172, '{\"stem\": \"设 $X\\\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。\", \"title\": \"正态分布对称性\", \"answer\": \"$P(X>0)=\\\\dfrac12$\", \"options\": [], \"solution\": \"标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\\\frac12$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
