INSERT INTO `import_item` VALUES (160466528452476943, 160466525063479297, '默认题集', 175, '{\"stem\": \"设 $X\\\\sim Poisson(\\\\lambda=2)$，则 $P(X=0)=$ ____。\", \"title\": \"泊松分布\", \"answer\": \"$e^{-2}$\", \"options\": [], \"solution\": \"泊松分布概率公式：$P(X=k)=e^{-\\\\lambda}\\\\frac{\\\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476944, 160466525063479297, '默认题集', 176, '{\"stem\": \"设 $X\\\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。\", \"title\": \"正态分布对称性\", \"answer\": \"$P(X>0)=\\\\dfrac12$\", \"options\": [], \"solution\": \"标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\\\frac12$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476945, 160466525063479297, '默认题集', 177, '{\"stem\": \"若 $X\\\\sim B(2,0.5)$，则 $P(X=1)=$（  ）\", \"title\": \"二项分布\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}], \"solution\": \"$P(X=1)=\\\\binom21(0.5)^1(0.5)^1=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476946, 160466525063479297, '默认题集', 178, '{\"stem\": \"下列关于常见分布的说法正确的是哪些？（多选）\", \"title\": \"常见分布性质\", \"answer\": \"ABCD\", \"options\": [{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}], \"solution\": \"A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"D\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476947, 160466525063479297, '默认题集', 179, '{\"stem\": \"设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。\", \"title\": \"方差计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476948, 160466525063479297, '默认题集', 180, '{\"stem\": \"设 $X$ 的分布列为 $P(X=1)=0.3,\\\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。\", \"title\": \"期望与方差综合\", \"answer\": \"$E(X)=1.7,\\\\quad Var(X)=0.21$\", \"options\": [], \"solution\": \"$E(X)=1\\\\times0.3+2\\\\times0.7=1.7$。$E(X^2)=1^2\\\\times0.3+2^2\\\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476949, 160466525063479297, '默认题集', 181, '{\"stem\": \"设随机变量 $X$ 的分布列为 $P(X=0)=0.5,\\\\ P(X=1)=0.5$，则 $E(X)=$（  ）\", \"title\": \"数学期望\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$1$\"}, {\"key\": \"D\", \"content\": \"$2$\"}], \"solution\": \"$E(X)=0\\\\times0.5+1\\\\times0.5=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476950, 160466525063479297, '默认题集', 182, '{\"stem\": \"下列关于期望、方差与协方差的说法正确的是哪些？（多选）\", \"title\": \"数字特征性质\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"$E(aX+b)=aE(X)+b$\"}, {\"key\": \"B\", \"content\": \"$Var(X)=E(X^2)-[E(X)]^2$\"}, {\"key\": \"C\", \"content\": \"若 $X,Y$ 独立，则 $Cov(X,Y)=0$\"}, {\"key\": \"D\", \"content\": \"$Var(aX)=aVar(X)$\"}, {\"key\": \"E\", \"content\": \"方差衡量随机变量偏离均值的程度\"}], \"solution\": \"A、B、C、E 正确；D 错，应为 $Var(aX)=a^2Var(X)$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476951, 160466525063479297, '默认题集', 183, '{\"stem\": \"设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。\", \"title\": \"方差计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
