INSERT INTO `import_item` VALUES (160466528452476963, 160466525063479297, '默认题集', 195, '{\"stem\": \"设总体均值为 $\\\\mu$，则依大数定律，样本均值 $\\\\bar X_n$ 当 $n\\\\to\\\\infty$ 时趋向于 ____。\", \"title\": \"样本均值极限\", \"answer\": \"$\\\\mu$\", \"options\": [], \"solution\": \"大数定律的核心结论就是样本均值趋于总体均值。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.32, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (160466528452476964, 160466525063479297, '默认题集', 196, '{\"stem\": \"用一句话说明中心极限定理在统计近似中的作用。\", \"title\": \"中心极限定理作用\", \"answer\": \"它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。\", \"options\": [], \"solution\": \"这是中心极限定理最常见的应用表述。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-03-23 19:16:42');
INSERT INTO `import_item` VALUES (195587387487682562, 195587384367120384, '默认题集', 1, '{\"stem\": \"计算极限：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{\\\\sin x - x}{x^3}=$（  ）\", \"title\": \"极限计算\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}], \"solution\": \"用泰勒展开：$\\\\sin x = x-\\\\frac{x^3}{6}+o(x^3)$，代入得 $\\\\frac{\\\\sin x-x}{x^3}=\\\\frac{-x^3/6+o(x^3)}{x^3}\\\\to -\\\\frac{1}{6}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682563, 195587384367120384, '默认题集', 2, '{\"stem\": \"函数 $e^x$ 在 $x=0$ 处的二阶泰勒展开中，$x^2$ 项系数为（  ）\", \"title\": \"泰勒展开系数\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$\\\\frac{1}{2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$2$\"}], \"solution\": \"$e^x = 1+x+\\\\frac{x^2}{2}+o(x^2)$，所以 $x^2$ 项系数为 $\\\\frac{1}{2}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682564, 195587384367120384, '默认题集', 3, '{\"stem\": \"下列级数中哪些收敛？（多选）\", \"title\": \"级数收敛性判断\", \"answer\": \"BCE\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n}$\"}, {\"key\": \"B\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{(-1)^{n}}{n}$\"}, {\"key\": \"D\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{\\\\sqrt{n}}$\"}, {\"key\": \"E\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^{3/2}}$\"}], \"solution\": \"A 为调和级数发散；B 为 $p=2$ 的 $p$ 级数收敛；C 为交错调和级数收敛；D 为 $p=\\\\frac12$ 的 $p$ 级数发散；E 为 $p=\\\\frac32$ 的 $p$ 级数收敛。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"B\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682565, 195587384367120384, '默认题集', 4, '{\"stem\": \"设 $f(x,y)=x^2y+y^3$。下列说法正确的是哪些？（多选）\", \"title\": \"梯度与方向导数\", \"answer\": \"ABCD\", \"options\": [{\"key\": \"A\", \"content\": \"$f_x=2xy$\"}, {\"key\": \"B\", \"content\": \"$f_y=x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"在点处沿单位向量 $\\\\mathbf{u}$ 的方向导数 $D_{\\\\mathbf{u}}f=\\\\nabla f\\\\cdot \\\\mathbf{u}$\"}, {\"key\": \"D\", \"content\": \"点处方向导数的最大值为 $\\\\|\\\\nabla f\\\\|$\"}, {\"key\": \"E\", \"content\": \"$\\\\nabla f$ 与等值线在该点的切向量同向\"}], \"solution\": \"A、B 为求偏导；C 为方向导数公式；D 为方向导数最大值性质；E 错：$\\\\nabla f$ 与等值线切向量垂直。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.6, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682566, 195587384367120384, '默认题集', 5, '{\"stem\": \"计算定积分：$\\\\displaystyle \\\\int_{0}^{\\\\pi/2}\\\\sin x\\\\,dx=$ ____。\", \"title\": \"定积分计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"$\\\\int \\\\sin x\\\\,dx=-\\\\cos x$，代入 $0$ 到 $\\\\pi/2$：$-\\\\cos(\\\\pi/2)-(-\\\\cos 0)=0-(-1)=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682567, 195587384367120384, '默认题集', 6, '{\"stem\": \"计算二重积分：$\\\\displaystyle \\\\iint_{x^2+y^2\\\\le 1}(x^2+y^2)\\\\,dA=$ ____。\", \"title\": \"二重积分（极坐标）\", \"answer\": \"$\\\\frac{\\\\pi}{2}$\", \"options\": [], \"solution\": \"用极坐标：$x^2+y^2=r^2,\\\\ dA=r\\\\,dr\\\\,d\\\\theta$。$\\\\int_{0}^{2\\\\pi}\\\\int_{0}^{1} r^2\\\\cdot r\\\\,dr\\\\,d\\\\theta=\\\\int_{0}^{2\\\\pi}\\\\left[\\\\frac{r^4}{4}\\\\right]_{0}^{1}d\\\\theta=2\\\\pi\\\\cdot\\\\frac14=\\\\frac{\\\\pi}{2}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682568, 195587384367120384, '默认题集', 7, '{\"stem\": \"判断：若二元函数 $f$ 在 $(0,0)$ 的某邻域内一阶偏导 $f_x,f_y$ 存在且连续，则 $f$ 在 $(0,0)$ 可微。\", \"title\": \"可微充分条件\", \"answer\": \"T\", \"options\": [], \"solution\": \"这是经典充分条件：$f_x,f_y$ 在邻域内连续（即 $f\\\\in C^1$）$\\\\Rightarrow$ 在该点可微。\", \"typeCode\": \"true-false\", \"difficulty\": 0.55, \"judgeAnswer\": \"T\", \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682569, 195587384367120384, '默认题集', 8, '{\"stem\": \"判断：若二元函数 $f$ 在 $(0,0)$ 处沿任意方向的方向导数都存在，则 $f$ 在 $(0,0)$ 可微。\", \"title\": \"方向导数与可微\", \"answer\": \"F\", \"options\": [], \"solution\": \"方向导数全存在并不保证可微（例如 $f(x,y)=\\\\sqrt{|xy|}$ 在原点方向导数都存在但不可微）。\", \"typeCode\": \"true-false\", \"difficulty\": 0.6, \"judgeAnswer\": \"F\", \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682570, 195587384367120384, '默认题集', 9, '{\"stem\": \"求解初值问题：$y\'+y=e^x,\\\\ y(0)=1$。\", \"title\": \"一阶线性微分方程\", \"answer\": \"$y(x)=\\\\frac12 e^x+\\\\frac12 e^{-x}$\", \"options\": [], \"solution\": \"用积分因子 $e^x$：$(ye^x)\'=e^{2x}$。积分得 $ye^x=\\\\frac12 e^{2x}+C$，故 $y=\\\\frac12 e^x+Ce^{-x}$。代入 $y(0)=1$ 得 $C=\\\\frac12$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682571, 195587384367120384, '默认题集', 10, '{\"stem\": \"求曲面 $z=x^2+y^2$ 在点 $(1,2,5)$ 处的切平面方程。\", \"title\": \"切平面方程\", \"answer\": \"$z=2x+4y-5$\", \"options\": [], \"solution\": \"设 $f(x,y)=x^2+y^2$，则 $f_x=2x,\\\\ f_y=2y$。在 $(1,2)$ 处 $f_x=2,\\\\ f_y=4$，$z_0=5$。切平面：$z=z_0+f_x(x-1)+f_y(y-2)=5+2(x-1)+4(y-2)=2x+4y-5$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387487682572, 195587384367120384, '默认题集', 11, '{\"stem\": \"计算极限：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{\\\\sinx-x}{x^3}=$（  ）\", \"title\": \"极限计算\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}], \"solution\": \"用展开 $\\\\sinx=x-\\\\frac{x^3}{6}+o(x^3)$，故极限为 $-\\\\frac{1}{6}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597121, 195587384367120384, '默认题集', 12, '{\"stem\": \"关于函数连续与间断点，下列说法正确的是哪些？（多选）\", \"title\": \"连续与间断\", \"answer\": \"ACE\", \"options\": [{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}], \"solution\": \"A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597122, 195587384367120384, '默认题集', 13, '{\"stem\": \"计算极限：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{\\\\sin(2x)-2x}{x^3}=$（  ）\", \"title\": \"极限计算\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-\\\\frac{4}{3}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{4}{3}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{8}{3}$\"}], \"solution\": \"用展开 $\\\\sin(2x)=2x-\\\\frac{(2x)^3}{6}+o(x^3)$，故极限为 $-\\\\frac{4}{3}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597123, 195587384367120384, '默认题集', 14, '{\"stem\": \"关于函数连续与间断点，下列说法正确的是哪些？（多选）\", \"title\": \"连续与间断\", \"answer\": \"ACE\", \"options\": [{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}], \"solution\": \"A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597124, 195587384367120384, '默认题集', 15, '{\"stem\": \"填空：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{e^{x}-1-x}{x^2}=$ ____。\", \"title\": \"指数函数极限\", \"answer\": \"$\\\\frac{1}{2}$\", \"options\": [], \"solution\": \"由 $e^{x}=1+x+\\\\frac{x^2}{2}+o(x^2)$，极限为 $\\\\frac{1}{2}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597125, 195587384367120384, '默认题集', 16, '{\"stem\": \"设 $fx=\\\\begin{cases}\\\\dfrac{x^2-1}{x-1}, & x\\\\ne 1,\\\\\\\\ a, & x=1.\\\\end{cases}$\\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。\", \"title\": \"连续条件求参\", \"answer\": \"$a=2$\", \"options\": [], \"solution\": \"因为当 $x\\\\ne1$ 时，$fx=x+1$。所以 $\\\\lim_{x\\\\to1}fx=2$。连续要求 $a=f(1)=2$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597126, 195587384367120384, '默认题集', 17, '{\"stem\": \"计算极限：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{\\\\sin(3x)-3x}{x^3}=$（  ）\", \"title\": \"极限计算\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-\\\\frac{9}{2}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{9}{2}$\"}, {\"key\": \"D\", \"content\": \"$-9$\"}], \"solution\": \"用展开 $\\\\sin(3x)=3x-\\\\frac{(3x)^3}{6}+o(x^3)$，故极限为 $-\\\\frac{9}{2}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597127, 195587384367120384, '默认题集', 18, '{\"stem\": \"关于函数连续与间断点，下列说法正确的是哪些？（多选）\", \"title\": \"连续与间断\", \"answer\": \"ACE\", \"options\": [{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}], \"solution\": \"A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597128, 195587384367120384, '默认题集', 19, '{\"stem\": \"填空：$\\\\displaystyle \\\\lim_{x\\\\to 0}\\\\frac{e^{2x}-1-2x}{x^2}=$ ____。\", \"title\": \"指数函数极限\", \"answer\": \"$2$\", \"options\": [], \"solution\": \"由 $e^{2x}=1+2x+\\\\frac{(2x)^2}{2}+o(x^2)$，极限为 $2$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597129, 195587384367120384, '默认题集', 20, '{\"stem\": \"设 $fx=\\\\begin{cases}\\\\dfrac{x^2-1}{x-1}, & x\\\\ne 1,\\\\\\\\ a, & x=1.\\\\end{cases}$\\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。\", \"title\": \"连续条件求参\", \"answer\": \"$a=2$\", \"options\": [], \"solution\": \"因为当 $x\\\\ne1$ 时，$fx=x+1$。所以 $\\\\lim_{x\\\\to1}fx=2$。连续要求 $a=f(1)=2$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597130, 195587384367120384, '默认题集', 21, '{\"stem\": \"求导：$y=\\\\sin(2x^2)$，则 $y\'$ 为（  ）\", \"title\": \"复合函数求导\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$4 x \\\\cos{\\\\left(2 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$2\\\\cos(2x^2)$\"}, {\"key\": \"C\", \"content\": \"$4x\\\\sin(2x^2)$\"}, {\"key\": \"D\", \"content\": \"$4x\\\\cos x$\"}], \"solution\": \"由链式法则，$y\'=4 x \\\\cos{\\\\left(2 x^{2} \\\\right)}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597131, 195587384367120384, '默认题集', 22, '{\"stem\": \"关于求导公式，下列说法正确的是哪些？（多选）\", \"title\": \"导数公式\", \"answer\": \"ACD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}], \"solution\": \"A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597132, 195587384367120384, '默认题集', 23, '{\"stem\": \"设隐函数由 $x^2+y^2=4$ 确定，则 $\\\\dfrac{dy}{dx}=$ ____。\", \"title\": \"隐函数求导\", \"answer\": \"$-\\\\dfrac{x}{y}$\", \"options\": [], \"solution\": \"两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\\\dfrac{x}{y}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597133, 195587384367120384, '默认题集', 24, '{\"stem\": \"求函数 $y=x^{2}e^x$ 的导数。\", \"title\": \"乘积法则求导\", \"answer\": \"$y\'=e^x\\\\left(x^2+2x^1\\\\right)$\", \"options\": [], \"solution\": \"用乘积法则：$y\'=2x^1e^x+x^2e^x=e^x\\\\left(x^2+2x^1\\\\right)$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.44, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597134, 195587384367120384, '默认题集', 25, '{\"stem\": \"求导：$y=\\\\sin(3x^2)$，则 $y\'$ 为（  ）\", \"title\": \"复合函数求导\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$6 x \\\\cos{\\\\left(3 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$3\\\\cos(3x^2)$\"}, {\"key\": \"C\", \"content\": \"$6x\\\\sin(3x^2)$\"}, {\"key\": \"D\", \"content\": \"$6x\\\\cos x$\"}], \"solution\": \"由链式法则，$y\'=6 x \\\\cos{\\\\left(3 x^{2} \\\\right)}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597135, 195587384367120384, '默认题集', 26, '{\"stem\": \"关于求导公式，下列说法正确的是哪些？（多选）\", \"title\": \"导数公式\", \"answer\": \"ACD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}], \"solution\": \"A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597136, 195587384367120384, '默认题集', 27, '{\"stem\": \"设隐函数由 $x^2+y^2=9$ 确定，则 $\\\\dfrac{dy}{dx}=$ ____。\", \"title\": \"隐函数求导\", \"answer\": \"$-\\\\dfrac{x}{y}$\", \"options\": [], \"solution\": \"两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\\\dfrac{x}{y}$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597137, 195587384367120384, '默认题集', 28, '{\"stem\": \"求函数 $y=x^{3}e^x$ 的导数。\", \"title\": \"乘积法则求导\", \"answer\": \"$y\'=e^x\\\\left(x^3+3x^2\\\\right)$\", \"options\": [], \"solution\": \"用乘积法则：$y\'=3x^2e^x+x^3e^x=e^x\\\\left(x^3+3x^2\\\\right)$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.44, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597138, 195587384367120384, '默认题集', 29, '{\"stem\": \"函数 $fx=x^3-3x$ 的极值点个数为（  ）\", \"title\": \"极值点个数\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}], \"solution\": \"$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\\\pm1$，且都发生极值。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597139, 195587384367120384, '默认题集', 30, '{\"stem\": \"下列关于导数应用的说法正确的是哪些？（多选）\", \"title\": \"单调性与最值\", \"answer\": \"ACE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}], \"solution\": \"A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597140, 195587384367120384, '默认题集', 31, '{\"stem\": \"求函数 $fx=x+\\\\dfrac{1}{x}\\\\ (x>0)$ 的最小值：____。\", \"title\": \"最小值计算\", \"answer\": \"$2$\", \"options\": [], \"solution\": \"$f\'x=1-\\\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597141, 195587384367120384, '默认题集', 32, '{\"stem\": \"求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。\", \"title\": \"单调区间与极值\", \"answer\": \"递增区间：$(-\\\\infty,0)\\\\cup(2,+\\\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。\", \"options\": [], \"solution\": \"$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\\\infty,0)$ 与 $(2,+\\\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.58, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597142, 195587384367120384, '默认题集', 33, '{\"stem\": \"函数 $fx=x^3-3x$ 的极值点个数为（  ）\", \"title\": \"极值点个数\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}], \"solution\": \"$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\\\pm1$，且都发生极值。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597143, 195587384367120384, '默认题集', 34, '{\"stem\": \"下列关于导数应用的说法正确的是哪些？（多选）\", \"title\": \"单调性与最值\", \"answer\": \"ACE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}], \"solution\": \"A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597144, 195587384367120384, '默认题集', 35, '{\"stem\": \"求函数 $fx=x+\\\\dfrac{1}{x}\\\\ (x>0)$ 的最小值：____。\", \"title\": \"最小值计算\", \"answer\": \"$2$\", \"options\": [], \"solution\": \"$f\'x=1-\\\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.45, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
