INSERT INTO `import_item` VALUES (195587387550597149, 195587384367120384, '默认题集', 40, '{\"stem\": \"求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。\", \"title\": \"单调区间与极值\", \"answer\": \"递增区间：$(-\\\\infty,0)\\\\cup(2,+\\\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。\", \"options\": [], \"solution\": \"$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\\\infty,0)$ 与 $(2,+\\\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.58, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597150, 195587384367120384, '默认题集', 41, '{\"stem\": \"不定积分 $\\\\displaystyle \\\\int x^2 \\\\, dx=$（  ）\", \"title\": \"幂函数积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"B\", \"content\": \"$x^3+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^2}{2}+C$\"}, {\"key\": \"D\", \"content\": \"$(3)x^2+C$\"}], \"solution\": \"用幂函数积分公式，结果为 $\\\\dfrac{x^3}{3}+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597151, 195587384367120384, '默认题集', 42, '{\"stem\": \"下列不定积分结果正确的是哪些？（多选）\", \"title\": \"基本积分公式\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}], \"solution\": \"A、B、D 正确；C 不严谨，应为 $\\\\ln|x|+C$；E 错，应为 $\\\\arctan x+C$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597152, 195587384367120384, '默认题集', 43, '{\"stem\": \"填空：$\\\\displaystyle \\\\int 2x e^{x^2}\\\\,dx=$ ____。\", \"title\": \"换元积分\", \"answer\": \"$e^{x^2}+C$\", \"options\": [], \"solution\": \"令 $u=x^2$，则 $du=2x\\\\,dx$，原式变为 $\\\\int e^u du=e^u+C=e^{x^2}+C$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.43, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597153, 195587384367120384, '默认题集', 44, '{\"stem\": \"求不定积分：$\\\\displaystyle \\\\int x\\\\ln x\\\\,dx$。\", \"title\": \"分部积分\", \"answer\": \"$\\\\dfrac{x^2}{2}\\\\ln x-\\\\dfrac{x^2}{4}+C$\", \"options\": [], \"solution\": \"分部积分，取 $u=\\\\ln x,\\\\ dv=x\\\\,dx$，则 $du=\\\\fracx dx,\\\\ v=\\\\frac{x^2}{2}$。故原式 $=\\\\frac{x^2}{2}\\\\ln x-\\\\int \\\\frac{x}{2}dx=\\\\frac{x^2}{2}\\\\ln x-\\\\frac{x^2}{4}+C$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597154, 195587384367120384, '默认题集', 45, '{\"stem\": \"不定积分 $\\\\displaystyle \\\\int x^3 \\\\, dx=$（  ）\", \"title\": \"幂函数积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^4}{4}+C$\"}, {\"key\": \"B\", \"content\": \"$x^4+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"D\", \"content\": \"$(4)x^3+C$\"}], \"solution\": \"用幂函数积分公式，结果为 $\\\\dfrac{x^4}{4}+C$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597155, 195587384367120384, '默认题集', 46, '{\"stem\": \"下列不定积分结果正确的是哪些？（多选）\", \"title\": \"基本积分公式\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}], \"solution\": \"A、B、D 正确；C 不严谨，应为 $\\\\ln|x|+C$；E 错，应为 $\\\\arctan x+C$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597156, 195587384367120384, '默认题集', 47, '{\"stem\": \"填空：$\\\\displaystyle \\\\int 2x e^{x^2}\\\\,dx=$ ____。\", \"title\": \"换元积分\", \"answer\": \"$e^{x^2}+C$\", \"options\": [], \"solution\": \"令 $u=x^2$，则 $du=2x\\\\,dx$，原式变为 $\\\\int e^u du=e^u+C=e^{x^2}+C$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.43, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597157, 195587384367120384, '默认题集', 48, '{\"stem\": \"求不定积分：$\\\\displaystyle \\\\int x\\\\ln x\\\\,dx$。\", \"title\": \"分部积分\", \"answer\": \"$\\\\dfrac{x^2}{2}\\\\ln x-\\\\dfrac{x^2}{4}+C$\", \"options\": [], \"solution\": \"分部积分，取 $u=\\\\ln x,\\\\ dv=x\\\\,dx$，则 $du=\\\\fracx dx,\\\\ v=\\\\frac{x^2}{2}$。故原式 $=\\\\frac{x^2}{2}\\\\ln x-\\\\int \\\\frac{x}{2}dx=\\\\frac{x^2}{2}\\\\ln x-\\\\frac{x^2}{4}+C$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597158, 195587384367120384, '默认题集', 49, '{\"stem\": \"计算定积分：$\\\\displaystyle \\\\int_0^1 2x\\\\,dx=$（  ）\", \"title\": \"定积分计算\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}], \"solution\": \"$\\\\int_0^1 2x\\\\,dx=[x^2]_0^1=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597159, 195587384367120384, '默认题集', 50, '{\"stem\": \"下列关于定积分的说法正确的是哪些？（多选）\", \"title\": \"定积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}], \"solution\": \"A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\\\int_0^a fxdx$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597160, 195587384367120384, '默认题集', 51, '{\"stem\": \"由定积分定义可得：$\\\\displaystyle \\\\int_0^2 (x+1)\\\\,dx=$ ____。\", \"title\": \"定积分求值\", \"answer\": \"$4$\", \"options\": [], \"solution\": \"$\\\\int_0^2 (x+1)dx=\\\\left[\\\\frac{x^2}{2}+x\\\\right]_0^2=2+2=4$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597161, 195587384367120384, '默认题集', 52, '{\"stem\": \"求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。\", \"title\": \"平面图形面积\", \"answer\": \"$\\\\dfrac{1}{6}$\", \"options\": [], \"solution\": \"交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\\\int_0^1 (x-x^2)dx=\\\\left[\\\\frac{x^2}{2}-\\\\frac{x^3}{3}\\\\right]_0^1=\\\\frac16$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597162, 195587384367120384, '默认题集', 53, '{\"stem\": \"计算定积分：$\\\\displaystyle \\\\int_0^1 2x\\\\,dx=$（  ）\", \"title\": \"定积分计算\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}], \"solution\": \"$\\\\int_0^1 2x\\\\,dx=[x^2]_0^1=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597163, 195587384367120384, '默认题集', 54, '{\"stem\": \"下列关于定积分的说法正确的是哪些？（多选）\", \"title\": \"定积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}], \"solution\": \"A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\\\int_0^a fxdx$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597164, 195587384367120384, '默认题集', 55, '{\"stem\": \"由定积分定义可得：$\\\\displaystyle \\\\int_0^2 (x+1)\\\\,dx=$ ____。\", \"title\": \"定积分求值\", \"answer\": \"$4$\", \"options\": [], \"solution\": \"$\\\\int_0^2 (x+1)dx=\\\\left[\\\\frac{x^2}{2}+x\\\\right]_0^2=2+2=4$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597165, 195587384367120384, '默认题集', 56, '{\"stem\": \"求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。\", \"title\": \"平面图形面积\", \"answer\": \"$\\\\dfrac{1}{6}$\", \"options\": [], \"solution\": \"交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\\\int_0^1 (x-x^2)dx=\\\\left[\\\\frac{x^2}{2}-\\\\frac{x^3}{3}\\\\right]_0^1=\\\\frac16$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.48, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597166, 195587384367120384, '默认题集', 57, '{\"stem\": \"计算定积分：$\\\\displaystyle \\\\int_0^1 2x\\\\,dx=$（  ）\", \"title\": \"定积分计算\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}], \"solution\": \"$\\\\int_0^1 2x\\\\,dx=[x^2]_0^1=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597167, 195587384367120384, '默认题集', 58, '{\"stem\": \"下列关于定积分的说法正确的是哪些？（多选）\", \"title\": \"定积分性质\", \"answer\": \"ABD\", \"options\": [{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}], \"solution\": \"A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\\\int_0^a fxdx$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597168, 195587384367120384, '默认题集', 59, '{\"stem\": \"设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。\", \"title\": \"全微分计算\", \"answer\": \"$3dx+3dy$\", \"options\": [], \"solution\": \"$z_x=2xy+y^2,\\\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597169, 195587384367120384, '默认题集', 60, '{\"stem\": \"设 $z=e^{xy}$，求 $\\\\dfrac{\\\\partial z}{\\\\partial x}$ 与 $\\\\dfrac{\\\\partial z}{\\\\partial y}$。\", \"title\": \"复合函数偏导\", \"answer\": \"$\\\\dfrac{\\\\partial z}{\\\\partial x}=ye^{xy},\\\\quad \\\\dfrac{\\\\partial z}{\\\\partial y}=xe^{xy}$\", \"options\": [], \"solution\": \"对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\\\cdot y$；同理 $z_y=e^{xy}\\\\cdot x$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.44, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597170, 195587384367120384, '默认题集', 61, '{\"stem\": \"设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）\", \"title\": \"求偏导数\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}], \"solution\": \"把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.4, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597171, 195587384367120384, '默认题集', 62, '{\"stem\": \"下列关于多元函数求导的说法正确的是哪些？（多选）\", \"title\": \"偏导与全微分性质\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}], \"solution\": \"A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387550597172, 195587384367120384, '默认题集', 63, '{\"stem\": \"设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。\", \"title\": \"全微分计算\", \"answer\": \"$3dx+3dy$\", \"options\": [], \"solution\": \"$z_x=2xy+y^2,\\\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.46, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
