INSERT INTO `import_item` VALUES (195587387617705993, 195587384367120384, '默认题集', 85, '{\"stem\": \"计算二重积分：$\\\\displaystyle \\\\iint_{[0,1]\\\\times[0,1]}(x+y)\\\\,dA=$（  ）\", \"title\": \"矩形区域二重积分\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}], \"solution\": \"$\\\\int_0^1\\\\int_0^1 (x+y)dxdy=\\\\int_0^1(\\\\frac12+y)dy=1$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
