INSERT INTO `import_item` VALUES (195587387617706013, 195587384367120384, '默认题集', 105, '{\"stem\": \"计算行列式 $\\\\begin{vmatrix}1&2\\\\\\\\3&4\\\\end{vmatrix}=$（  ）\", \"title\": \"二阶行列式\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}], \"solution\": \"$1\\\\cdot4-2\\\\cdot3=-2$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706014, 195587384367120384, '默认题集', 106, '{\"stem\": \"下列关于行列式的说法正确的是哪些？（多选）\", \"title\": \"行列式性质\", \"answer\": \"ABE\", \"options\": [{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}], \"solution\": \"A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.47, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706015, 195587384367120384, '默认题集', 107, '{\"stem\": \"填空：$\\\\begin{vmatrix}2&0&0\\\\\\\\1&3&0\\\\\\\\4&5&6\\\\end{vmatrix}=$ ____。\", \"title\": \"三角行列式\", \"answer\": \"$36$\", \"options\": [], \"solution\": \"下三角行列式等于主对角线元素之积，故为 $2\\\\cdot3\\\\cdot6=36$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.35, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
