INSERT INTO `import_item` VALUES (195587387617706020, 195587384367120384, '默认题集', 112, '{\"stem\": \"计算行列式：$\\\\begin{vmatrix}1&1&1\\\\\\\\1&2&3\\\\\\\\1&3&6\\\\end{vmatrix}$。\", \"title\": \"三阶行列式计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"可作行变换：$R_2\\\\leftarrow R_2-R_1,\\\\ R_3\\\\leftarrow R_3-R_1$，得 $\\\\begin{vmatrix}1&1&1\\\\\\\\0&1&2\\\\\\\\0&2&5\\\\end{vmatrix}$，再按第一列展开得 $\\\\begin{vmatrix}1&2\\\\\\\\2&5\\\\end{vmatrix}=1$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706021, 195587384367120384, '默认题集', 113, '{\"stem\": \"设 $A=\\\\begin{pmatrix}1&2\\\\\\\\0&1\\\\end{pmatrix},\\\\ B=\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$，则 $AB=$（  ）\", \"title\": \"矩阵乘法\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}], \"solution\": \"按矩阵乘法计算：$AB=\\\\begin{pmatrix}1\\\\cdot2+2\\\\cdot1 & 1\\\\cdot0+2\\\\cdot3\\\\\\\\ 0\\\\cdot2+1\\\\cdot1 & 0\\\\cdot0+1\\\\cdot3\\\\end{pmatrix}=\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706022, 195587384367120384, '默认题集', 114, '{\"stem\": \"下列关于矩阵运算的说法正确的是哪些？（多选）\", \"title\": \"矩阵与逆矩阵性质\", \"answer\": \"ABC\", \"options\": [{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}], \"solution\": \"A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.53, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706023, 195587384367120384, '默认题集', 115, '{\"stem\": \"设 $A=\\\\begin{pmatrix}1&0\\\\\\\\0&2\\\\end{pmatrix}$，则 $A^{-1}=$ ____。\", \"title\": \"逆矩阵\", \"answer\": \"$\\\\begin{pmatrix}1&0\\\\\\\\0&\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"对角矩阵求逆就是对角元分别取倒数。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706024, 195587384367120384, '默认题集', 116, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}1&2\\\\\\\\3&4\\\\end{pmatrix}$ 的逆矩阵。\", \"title\": \"二阶矩阵求逆\", \"answer\": \"$A^{-1}=\\\\begin{pmatrix}-2&1\\\\\\\\ \\\\frac32&-\\\\frac12\\\\end{pmatrix}$\", \"options\": [], \"solution\": \"二阶矩阵逆公式：$A^{-1}=\\\\frac{1}{ad-bc}\\\\begin{pmatrix}d&-b\\\\\\\\-c&a\\\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
