INSERT INTO `import_item` VALUES (195587387617706039, 195587384367120384, '默认题集', 131, '{\"stem\": \"线性方程组 $\\\\begin{cases}x+y=2\\\\\\\\x-y=0\\\\end{cases}$ 的解为 $(x,y)=$ ____。\", \"title\": \"二元线性方程组\", \"answer\": \"$(1,1)$\", \"options\": [], \"solution\": \"两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.32, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706040, 195587384367120384, '默认题集', 132, '{\"stem\": \"求齐次线性方程组 $\\\\begin{cases}x+y+z=0\\\\\\\\x-y+z=0\\\\end{cases}$ 的基础解系。\", \"title\": \"基础解系\", \"answer\": \"基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"options\": [], \"solution\": \"由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706041, 195587384367120384, '默认题集', 133, '{\"stem\": \"齐次线性方程组 $Ax=0$ 一定有（  ）\", \"title\": \"齐次方程组\", \"answer\": \"C\", \"options\": [{\"key\": \"A\", \"content\": \"无解\"}, {\"key\": \"B\", \"content\": \"唯一解\"}, {\"key\": \"C\", \"content\": \"零解\"}, {\"key\": \"D\", \"content\": \"无穷多解\"}], \"solution\": \"齐次线性方程组至少有零解。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": [\"C\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706042, 195587384367120384, '默认题集', 134, '{\"stem\": \"下列关于线性方程组的说法正确的是哪些？（多选）\", \"title\": \"线性方程组理论\", \"answer\": \"ABCD\", \"options\": [{\"key\": \"A\", \"content\": \"齐次线性方程组一定有解\"}, {\"key\": \"B\", \"content\": \"非齐次线性方程组可能无解\"}, {\"key\": \"C\", \"content\": \"若系数矩阵满秩，则齐次方程组只有零解\"}, {\"key\": \"D\", \"content\": \"基础解系中的向量一定线性无关\"}, {\"key\": \"E\", \"content\": \"非齐次方程组有解时，其通解等于对应齐次方程组通解\"}], \"solution\": \"A、B、C、D 正确；E 错，非齐次通解=一个特解+对应齐次通解。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"D\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706043, 195587384367120384, '默认题集', 135, '{\"stem\": \"线性方程组 $\\\\begin{cases}x+y=2\\\\\\\\x-y=0\\\\end{cases}$ 的解为 $(x,y)=$ ____。\", \"title\": \"二元线性方程组\", \"answer\": \"$(1,1)$\", \"options\": [], \"solution\": \"两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.32, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706044, 195587384367120384, '默认题集', 136, '{\"stem\": \"求齐次线性方程组 $\\\\begin{cases}x+y+z=0\\\\\\\\x-y+z=0\\\\end{cases}$ 的基础解系。\", \"title\": \"基础解系\", \"answer\": \"基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"options\": [], \"solution\": \"由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
