INSERT INTO `import_item` VALUES (195587387617706047, 195587384367120384, '默认题集', 139, '{\"stem\": \"线性方程组 $\\\\begin{cases}x+y=2\\\\\\\\x-y=0\\\\end{cases}$ 的解为 $(x,y)=$ ____。\", \"title\": \"二元线性方程组\", \"answer\": \"$(1,1)$\", \"options\": [], \"solution\": \"两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.32, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706048, 195587384367120384, '默认题集', 140, '{\"stem\": \"求齐次线性方程组 $\\\\begin{cases}x+y+z=0\\\\\\\\x-y+z=0\\\\end{cases}$ 的基础解系。\", \"title\": \"基础解系\", \"answer\": \"基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"options\": [], \"solution\": \"由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\\\{(-1,0,1)^T\\\\}$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.52, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706049, 195587384367120384, '默认题集', 141, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}2&0\\\\\\\\0&3\\\\end{pmatrix}$ 的特征值为（  ）\", \"title\": \"特征值\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}], \"solution\": \"对角矩阵的特征值就是主对角线元素。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.34, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706050, 195587384367120384, '默认题集', 142, '{\"stem\": \"下列说法正确的是哪些？（多选）\", \"title\": \"特征值与对角化性质\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}], \"solution\": \"A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.6, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706051, 195587384367120384, '默认题集', 143, '{\"stem\": \"矩阵 $A=\\\\begin{pmatrix}1&0\\\\\\\\0&1\\\\end{pmatrix}$ 的唯一特征值为 ____。\", \"title\": \"单位矩阵特征值\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"单位矩阵满足 $Ax=x$，故唯一特征值为 1。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706052, 195587384367120384, '默认题集', 144, '{\"stem\": \"求矩阵 $A=\\\\begin{pmatrix}2&1\\\\\\\\0&2\\\\end{pmatrix}$ 的特征值与特征向量。\", \"title\": \"特征向量求解\", \"answer\": \"特征值只有 $\\\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\\\begin{pmatrix}1\\\\\\\\0\\\\end{pmatrix}$ 的任意非零倍。\", \"options\": [], \"solution\": \"特征多项式为 $(2-\\\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\\\begin{pmatrix}0&1\\\\\\\\0&0\\\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
