INSERT INTO `import_item` VALUES (195587387617706059, 195587384367120384, '默认题集', 151, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706060, 195587384367120384, '默认题集', 152, '{\"stem\": \"设事件 $A,B$ 满足 $P(B)=0.6,\\\\ P(A|B)=0.5,\\\\ P(A|\\\\bar B)=0.2$，求 $P(A)$。\", \"title\": \"全概率公式\", \"answer\": \"$0.38$\", \"options\": [], \"solution\": \"由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\\\bar B)P(\\\\bar B)=0.5\\\\times0.6+0.2\\\\times0.4=0.38$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706061, 195587384367120384, '默认题集', 153, '{\"stem\": \"设 $P(A)=0.4,\\\\ P(B)=0.5,\\\\ P(A\\\\cap B)=0.2$，则 $P(A\\\\cup B)=$（  ）\", \"title\": \"事件并概率\", \"answer\": \"A\", \"options\": [{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}], \"solution\": \"用加法公式：$P(A\\\\cup B)=P(A)+P(B)-P(A\\\\cap B)=0.7$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": [\"A\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706062, 195587384367120384, '默认题集', 154, '{\"stem\": \"下列关于概率论基础的说法正确的是哪些？（多选）\", \"title\": \"概率基础公式\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}], \"solution\": \"A、B、D、E 正确；C 错，互斥且概率都非零时不独立。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.55, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387617706063, 195587384367120384, '默认题集', 155, '{\"stem\": \"袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。\", \"title\": \"古典概型\", \"answer\": \"$\\\\dfrac{3}{5}$\", \"options\": [], \"solution\": \"古典概型，红球数比总球数：$\\\\frac35$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.28, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
