INSERT INTO `import_item` VALUES (195587387680620555, 195587384367120384, '默认题集', 179, '{\"stem\": \"设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。\", \"title\": \"方差计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620556, 195587384367120384, '默认题集', 180, '{\"stem\": \"设 $X$ 的分布列为 $P(X=1)=0.3,\\\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。\", \"title\": \"期望与方差综合\", \"answer\": \"$E(X)=1.7,\\\\quad Var(X)=0.21$\", \"options\": [], \"solution\": \"$E(X)=1\\\\times0.3+2\\\\times0.7=1.7$。$E(X^2)=1^2\\\\times0.3+2^2\\\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.5, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620557, 195587384367120384, '默认题集', 181, '{\"stem\": \"设随机变量 $X$ 的分布列为 $P(X=0)=0.5,\\\\ P(X=1)=0.5$，则 $E(X)=$（  ）\", \"title\": \"数学期望\", \"answer\": \"B\", \"options\": [{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$1$\"}, {\"key\": \"D\", \"content\": \"$2$\"}], \"solution\": \"$E(X)=0\\\\times0.5+1\\\\times0.5=0.5$。\", \"typeCode\": \"single-choice\", \"difficulty\": 0.3, \"judgeAnswer\": null, \"correctOptions\": [\"B\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620558, 195587384367120384, '默认题集', 182, '{\"stem\": \"下列关于期望、方差与协方差的说法正确的是哪些？（多选）\", \"title\": \"数字特征性质\", \"answer\": \"ABCE\", \"options\": [{\"key\": \"A\", \"content\": \"$E(aX+b)=aE(X)+b$\"}, {\"key\": \"B\", \"content\": \"$Var(X)=E(X^2)-[E(X)]^2$\"}, {\"key\": \"C\", \"content\": \"若 $X,Y$ 独立，则 $Cov(X,Y)=0$\"}, {\"key\": \"D\", \"content\": \"$Var(aX)=aVar(X)$\"}, {\"key\": \"E\", \"content\": \"方差衡量随机变量偏离均值的程度\"}], \"solution\": \"A、B、C、E 正确；D 错，应为 $Var(aX)=a^2Var(X)$。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.56, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"C\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620559, 195587384367120384, '默认题集', 183, '{\"stem\": \"设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。\", \"title\": \"方差计算\", \"answer\": \"$1$\", \"options\": [], \"solution\": \"$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.38, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
