INSERT INTO `import_item` VALUES (195587387680620570, 195587384367120384, '默认题集', 194, '{\"stem\": \"下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）\", \"title\": \"极限定理理解\", \"answer\": \"ABDE\", \"options\": [{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}], \"solution\": \"A、B、D、E 正确；C 错，两者关注点不同。\", \"typeCode\": \"multiple-choice\", \"difficulty\": 0.58, \"judgeAnswer\": null, \"correctOptions\": [\"A\", \"B\", \"D\", \"E\"]}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620571, 195587384367120384, '默认题集', 195, '{\"stem\": \"设总体均值为 $\\\\mu$，则依大数定律，样本均值 $\\\\bar X_n$ 当 $n\\\\to\\\\infty$ 时趋向于 ____。\", \"title\": \"样本均值极限\", \"answer\": \"$\\\\mu$\", \"options\": [], \"solution\": \"大数定律的核心结论就是样本均值趋于总体均值。\", \"typeCode\": \"fill-in\", \"difficulty\": 0.32, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
INSERT INTO `import_item` VALUES (195587387680620572, 195587384367120384, '默认题集', 196, '{\"stem\": \"用一句话说明中心极限定理在统计近似中的作用。\", \"title\": \"中心极限定理作用\", \"answer\": \"它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。\", \"options\": [], \"solution\": \"这是中心极限定理最常见的应用表述。\", \"typeCode\": \"short-answer\", \"difficulty\": 0.42, \"judgeAnswer\": null, \"correctOptions\": null}', 0, '[]', '2026-06-28 17:14:27');
