INSERT INTO `question_version` VALUES (160334896772939777, 160334896772939776, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939779, 160334896772939778, 1, 'short-answer', '基础解系', '求齐次线性方程组 $\\begin{cases}x+y+z=0\\\\x-y+z=0\\end{cases}$ 的基础解系。', '[]', '基础解系可取 $\\{(-1,0,1)^T\\}$。', '', '由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\{(-1,0,1)^T\\}$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939781, 160334896772939780, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939783, 160334896772939782, 1, 'multiple-choice', '特征值与对角化性质', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939785, 160334896772939784, 1, 'fill-in', '单位矩阵特征值', '矩阵 $A=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$ 的唯一特征值为 ____。', '[]', '$1$', '', '单位矩阵满足 $Ax=x$，故唯一特征值为 1。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939787, 160334896772939786, 1, 'short-answer', '特征向量求解', '求矩阵 $A=\\begin{pmatrix}2&1\\\\0&2\\end{pmatrix}$ 的特征值与特征向量。', '[]', '特征值只有 $\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\begin{pmatrix}1\\\\0\\end{pmatrix}$ 的任意非零倍。', '', '特征多项式为 $(2-\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\begin{pmatrix}0&1\\\\0&0\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939789, 160334896772939788, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896772939791, 160334896772939790, 1, 'multiple-choice', '特征值与对角化性质', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334896840048642, 160334896840048641, 1, 'fill-in', '单位矩阵特征值', '矩阵 $A=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$ 的唯一特征值为 ____。', '[]', '$1$', '', '单位矩阵满足 $Ax=x$，故唯一特征值为 1。', NULL, 160333690390446080, '2026-03-23 10:33:38');
