INSERT INTO `question_version` VALUES (160334897100095500, 160334897100095499, 1, 'short-answer', '正态分布对称性', '设 $X\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。', '[]', '$P(X>0)=\\dfrac12$', '', '标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\frac12$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897100095502, 160334897100095501, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204354, 160334897167204353, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204356, 160334897167204355, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204358, 160334897167204357, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204360, 160334897167204359, 1, 'single-choice', '数学期望', '设随机变量 $X$ 的分布列为 $P(X=0)=0.5,\\ P(X=1)=0.5$，则 $E(X)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$1$\"}, {\"key\": \"D\", \"content\": \"$2$\"}]', 'B', 'B', '$E(X)=0\\times0.5+1\\times0.5=0.5$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204362, 160334897167204361, 1, 'multiple-choice', '数字特征性质', '下列关于期望、方差与协方差的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$E(aX+b)=aE(X)+b$\"}, {\"key\": \"B\", \"content\": \"$Var(X)=E(X^2)-[E(X)]^2$\"}, {\"key\": \"C\", \"content\": \"若 $X,Y$ 独立，则 $Cov(X,Y)=0$\"}, {\"key\": \"D\", \"content\": \"$Var(aX)=aVar(X)$\"}, {\"key\": \"E\", \"content\": \"方差衡量随机变量偏离均值的程度\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，应为 $Var(aX)=a^2Var(X)$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204364, 160334897167204363, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897167204366, 160334897167204365, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
