INSERT INTO `question_version` VALUES (160334897230118917, 160334897230118916, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897230118919, 160334897230118918, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897230118921, 160334897230118920, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897230118923, 160334897230118922, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897230118925, 160334897230118924, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897293033474, 160334897293033473, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897293033476, 160334897293033475, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897293033478, 160334897293033477, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897293033480, 160334897293033479, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160334897293033482, 160334897293033481, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 160333690390446080, '2026-03-23 10:33:38');
INSERT INTO `question_version` VALUES (160466583834066945, 160466583834066944, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin x - x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}]', 'A', 'A', '用泰勒展开：$\\sin x = x-\\frac{x^3}{6}+o(x^3)$，代入得 $\\frac{\\sin x-x}{x^3}=\\frac{-x^3/6+o(x^3)}{x^3}\\to -\\frac{1}{6}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466583968284673, 160466583968284672, 1, 'single-choice', '泰勒展开系数', '函数 $e^x$ 在 $x=0$ 处的二阶泰勒展开中，$x^2$ 项系数为（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$\\\\frac{1}{2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$2$\"}]', 'B', 'B', '$e^x = 1+x+\\frac{x^2}{2}+o(x^2)$，所以 $x^2$ 项系数为 $\\frac{1}{2}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466583968284675, 160466583968284674, 1, 'multiple-choice', '级数收敛性判断', '下列级数中哪些收敛？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n}$\"}, {\"key\": \"B\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{(-1)^{n}}{n}$\"}, {\"key\": \"D\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{\\\\sqrt{n}}$\"}, {\"key\": \"E\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^{3/2}}$\"}]', 'BCE', 'BCE', 'A 为调和级数发散；B 为 $p=2$ 的 $p$ 级数收敛；C 为交错调和级数收敛；D 为 $p=\\frac12$ 的 $p$ 级数发散；E 为 $p=\\frac32$ 的 $p$ 级数收敛。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584035393538, 160466584035393537, 1, 'multiple-choice', '梯度与方向导数', '设 $f(x,y)=x^2y+y^3$。下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$f_x=2xy$\"}, {\"key\": \"B\", \"content\": \"$f_y=x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"在点处沿单位向量 $\\\\mathbf{u}$ 的方向导数 $D_{\\\\mathbf{u}}f=\\\\nabla f\\\\cdot \\\\mathbf{u}$\"}, {\"key\": \"D\", \"content\": \"点处方向导数的最大值为 $\\\\|\\\\nabla f\\\\|$\"}, {\"key\": \"E\", \"content\": \"$\\\\nabla f$ 与等值线在该点的切向量同向\"}]', 'ABCD', 'ABCD', 'A、B 为求偏导；C 为方向导数公式；D 为方向导数最大值性质；E 错：$\\nabla f$ 与等值线切向量垂直。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584035393540, 160466584035393539, 1, 'fill-in', '定积分计算', '计算定积分：$\\displaystyle \\int_{0}^{\\pi/2}\\sin x\\,dx=$ ____。', '[]', '$1$', '', '$\\int \\sin x\\,dx=-\\cos x$，代入 $0$ 到 $\\pi/2$：$-\\cos(\\pi/2)-(-\\cos 0)=0-(-1)=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584098308098, 160466584098308097, 1, 'fill-in', '二重积分（极坐标）', '计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 1}(x^2+y^2)\\,dA=$ ____。', '[]', '$\\frac{\\pi}{2}$', '', '用极坐标：$x^2+y^2=r^2,\\ dA=r\\,dr\\,d\\theta$。$\\int_{0}^{2\\pi}\\int_{0}^{1} r^2\\cdot r\\,dr\\,d\\theta=\\int_{0}^{2\\pi}\\left[\\frac{r^4}{4}\\right]_{0}^{1}d\\theta=2\\pi\\cdot\\frac14=\\frac{\\pi}{2}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584098308100, 160466584098308099, 1, 'true-false', '可微充分条件', '判断：若二元函数 $f$ 在 $(0,0)$ 的某邻域内一阶偏导 $f_x,f_y$ 存在且连续，则 $f$ 在 $(0,0)$ 可微。', '[]', 'T', 'T', '这是经典充分条件：$f_x,f_y$ 在邻域内连续（即 $f\\in C^1$）$\\Rightarrow$ 在该点可微。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584165416963, 160466584165416962, 1, 'true-false', '方向导数与可微', '判断：若二元函数 $f$ 在 $(0,0)$ 处沿任意方向的方向导数都存在，则 $f$ 在 $(0,0)$ 可微。', '[]', 'F', 'F', '方向导数全存在并不保证可微（例如 $f(x,y)=\\sqrt{|xy|}$ 在原点方向导数都存在但不可微）。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584232525826, 160466584232525825, 1, 'short-answer', '一阶线性微分方程', '求解初值问题：$y\'+y=e^x,\\ y(0)=1$。', '[]', '$y(x)=\\frac12 e^x+\\frac12 e^{-x}$', '', '用积分因子 $e^x$：$(ye^x)\'=e^{2x}$。积分得 $ye^x=\\frac12 e^{2x}+C$，故 $y=\\frac12 e^x+Ce^{-x}$。代入 $y(0)=1$ 得 $C=\\frac12$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584232525828, 160466584232525827, 1, 'short-answer', '切平面方程', '求曲面 $z=x^2+y^2$ 在点 $(1,2,5)$ 处的切平面方程。', '[]', '$z=2x+4y-5$', '', '设 $f(x,y)=x^2+y^2$，则 $f_x=2x,\\ f_y=2y$。在 $(1,2)$ 处 $f_x=2,\\ f_y=4$，$z_0=5$。切平面：$z=z_0+f_x(x-1)+f_y(y-2)=5+2(x-1)+4(y-2)=2x+4y-5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584232525830, 160466584232525829, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sinx-x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}]', 'A', 'A', '用展开 $\\sinx=x-\\frac{x^3}{6}+o(x^3)$，故极限为 $-\\frac{1}{6}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584291246083, 160466584291246082, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584291246085, 160466584291246084, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin(2x)-2x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{4}{3}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{4}{3}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{8}{3}$\"}]', 'A', 'A', '用展开 $\\sin(2x)=2x-\\frac{(2x)^3}{6}+o(x^3)$，故极限为 $-\\frac{4}{3}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584291246087, 160466584291246086, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584291246089, 160466584291246088, 1, 'fill-in', '指数函数极限', '填空：$\\displaystyle \\lim_{x\\to 0}\\frac{e^{x}-1-x}{x^2}=$ ____。', '[]', '$\\frac{1}{2}$', '', '由 $e^{x}=1+x+\\frac{x^2}{2}+o(x^2)$，极限为 $\\frac{1}{2}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584358354945, 160466584358354944, 1, 'short-answer', '连续条件求参', '设 $fx=\\begin{cases}\\dfrac{x^2-1}{x-1}, & x\\ne 1,\\\\ a, & x=1.\\end{cases}$\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。', '[]', '$a=2$', '', '因为当 $x\\ne1$ 时，$fx=x+1$。所以 $\\lim_{x\\to1}fx=2$。连续要求 $a=f(1)=2$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584358354947, 160466584358354946, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin(3x)-3x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{9}{2}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{9}{2}$\"}, {\"key\": \"D\", \"content\": \"$-9$\"}]', 'A', 'A', '用展开 $\\sin(3x)=3x-\\frac{(3x)^3}{6}+o(x^3)$，故极限为 $-\\frac{9}{2}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584358354949, 160466584358354948, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584358354951, 160466584358354950, 1, 'fill-in', '指数函数极限', '填空：$\\displaystyle \\lim_{x\\to 0}\\frac{e^{2x}-1-2x}{x^2}=$ ____。', '[]', '$2$', '', '由 $e^{2x}=1+2x+\\frac{(2x)^2}{2}+o(x^2)$，极限为 $2$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584421269505, 160466584421269504, 1, 'short-answer', '连续条件求参', '设 $fx=\\begin{cases}\\dfrac{x^2-1}{x-1}, & x\\ne 1,\\\\ a, & x=1.\\end{cases}$\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。', '[]', '$a=2$', '', '因为当 $x\\ne1$ 时，$fx=x+1$。所以 $\\lim_{x\\to1}fx=2$。连续要求 $a=f(1)=2$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584421269507, 160466584421269506, 1, 'single-choice', '复合函数求导', '求导：$y=\\sin(2x^2)$，则 $y\'$ 为（  ）', '[{\"key\": \"A\", \"content\": \"$4 x \\\\cos{\\\\left(2 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$2\\\\cos(2x^2)$\"}, {\"key\": \"C\", \"content\": \"$4x\\\\sin(2x^2)$\"}, {\"key\": \"D\", \"content\": \"$4x\\\\cos x$\"}]', 'A', 'A', '由链式法则，$y\'=4 x \\cos{\\left(2 x^{2} \\right)}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584421269509, 160466584421269508, 1, 'multiple-choice', '导数公式', '关于求导公式，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}]', 'ACD', 'ACD', 'A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584421269511, 160466584421269510, 1, 'fill-in', '隐函数求导', '设隐函数由 $x^2+y^2=4$ 确定，则 $\\dfrac{dy}{dx}=$ ____。', '[]', '$-\\dfrac{x}{y}$', '', '两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\dfrac{x}{y}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584484184065, 160466584484184064, 1, 'short-answer', '乘积法则求导', '求函数 $y=x^{2}e^x$ 的导数。', '[]', '$y\'=e^x\\left(x^2+2x^1\\right)$', '', '用乘积法则：$y\'=2x^1e^x+x^2e^x=e^x\\left(x^2+2x^1\\right)$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584484184067, 160466584484184066, 1, 'single-choice', '复合函数求导', '求导：$y=\\sin(3x^2)$，则 $y\'$ 为（  ）', '[{\"key\": \"A\", \"content\": \"$6 x \\\\cos{\\\\left(3 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$3\\\\cos(3x^2)$\"}, {\"key\": \"C\", \"content\": \"$6x\\\\sin(3x^2)$\"}, {\"key\": \"D\", \"content\": \"$6x\\\\cos x$\"}]', 'A', 'A', '由链式法则，$y\'=6 x \\cos{\\left(3 x^{2} \\right)}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584484184069, 160466584484184068, 1, 'multiple-choice', '导数公式', '关于求导公式，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}]', 'ACD', 'ACD', 'A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584484184071, 160466584484184070, 1, 'fill-in', '隐函数求导', '设隐函数由 $x^2+y^2=9$ 确定，则 $\\dfrac{dy}{dx}=$ ____。', '[]', '$-\\dfrac{x}{y}$', '', '两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\dfrac{x}{y}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584551292930, 160466584551292929, 1, 'short-answer', '乘积法则求导', '求函数 $y=x^{3}e^x$ 的导数。', '[]', '$y\'=e^x\\left(x^3+3x^2\\right)$', '', '用乘积法则：$y\'=3x^2e^x+x^3e^x=e^x\\left(x^3+3x^2\\right)$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584551292932, 160466584551292931, 1, 'single-choice', '极值点个数', '函数 $fx=x^3-3x$ 的极值点个数为（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}]', 'C', 'C', '$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\pm1$，且都发生极值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584551292934, 160466584551292933, 1, 'multiple-choice', '单调性与最值', '下列关于导数应用的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}]', 'ACE', 'ACE', 'A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584551292936, 160466584551292935, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584614207490, 160466584614207489, 1, 'short-answer', '单调区间与极值', '求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。', '[]', '递增区间：$(-\\infty,0)\\cup(2,+\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。', '', '$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\infty,0)$ 与 $(2,+\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584614207492, 160466584614207491, 1, 'single-choice', '极值点个数', '函数 $fx=x^3-3x$ 的极值点个数为（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}]', 'C', 'C', '$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\pm1$，且都发生极值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584614207494, 160466584614207493, 1, 'multiple-choice', '单调性与最值', '下列关于导数应用的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}]', 'ACE', 'ACE', 'A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584614207496, 160466584614207495, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584614207498, 160466584614207497, 1, 'short-answer', '单调区间与极值', '求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。', '[]', '递增区间：$(-\\infty,0)\\cup(2,+\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。', '', '$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\infty,0)$ 与 $(2,+\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584677122051, 160466584677122050, 1, 'single-choice', '极值点个数', '函数 $fx=x^3-3x$ 的极值点个数为（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}]', 'C', 'C', '$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\pm1$，且都发生极值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584677122053, 160466584677122052, 1, 'multiple-choice', '单调性与最值', '下列关于导数应用的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}]', 'ACE', 'ACE', 'A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584677122055, 160466584677122054, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584677122057, 160466584677122056, 1, 'short-answer', '单调区间与极值', '求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。', '[]', '递增区间：$(-\\infty,0)\\cup(2,+\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。', '', '$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\infty,0)$ 与 $(2,+\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584677122059, 160466584677122058, 1, 'single-choice', '幂函数积分', '不定积分 $\\displaystyle \\int x^2 \\, dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"B\", \"content\": \"$x^3+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^2}{2}+C$\"}, {\"key\": \"D\", \"content\": \"$(3)x^2+C$\"}]', 'A', 'A', '用幂函数积分公式，结果为 $\\dfrac{x^3}{3}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584744230915, 160466584744230914, 1, 'multiple-choice', '基本积分公式', '下列不定积分结果正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 不严谨，应为 $\\ln|x|+C$；E 错，应为 $\\arctan x+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584744230917, 160466584744230916, 1, 'fill-in', '换元积分', '填空：$\\displaystyle \\int 2x e^{x^2}\\,dx=$ ____。', '[]', '$e^{x^2}+C$', '', '令 $u=x^2$，则 $du=2x\\,dx$，原式变为 $\\int e^u du=e^u+C=e^{x^2}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584744230919, 160466584744230918, 1, 'short-answer', '分部积分', '求不定积分：$\\displaystyle \\int x\\ln x\\,dx$。', '[]', '$\\dfrac{x^2}{2}\\ln x-\\dfrac{x^2}{4}+C$', '', '分部积分，取 $u=\\ln x,\\ dv=x\\,dx$，则 $du=\\fracx dx,\\ v=\\frac{x^2}{2}$。故原式 $=\\frac{x^2}{2}\\ln x-\\int \\frac{x}{2}dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584744230921, 160466584744230920, 1, 'single-choice', '幂函数积分', '不定积分 $\\displaystyle \\int x^3 \\, dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^4}{4}+C$\"}, {\"key\": \"B\", \"content\": \"$x^4+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"D\", \"content\": \"$(4)x^3+C$\"}]', 'A', 'A', '用幂函数积分公式，结果为 $\\dfrac{x^4}{4}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584807145475, 160466584807145474, 1, 'multiple-choice', '基本积分公式', '下列不定积分结果正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 不严谨，应为 $\\ln|x|+C$；E 错，应为 $\\arctan x+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584807145477, 160466584807145476, 1, 'fill-in', '换元积分', '填空：$\\displaystyle \\int 2x e^{x^2}\\,dx=$ ____。', '[]', '$e^{x^2}+C$', '', '令 $u=x^2$，则 $du=2x\\,dx$，原式变为 $\\int e^u du=e^u+C=e^{x^2}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584807145479, 160466584807145478, 1, 'short-answer', '分部积分', '求不定积分：$\\displaystyle \\int x\\ln x\\,dx$。', '[]', '$\\dfrac{x^2}{2}\\ln x-\\dfrac{x^2}{4}+C$', '', '分部积分，取 $u=\\ln x,\\ dv=x\\,dx$，则 $du=\\fracx dx,\\ v=\\frac{x^2}{2}$。故原式 $=\\frac{x^2}{2}\\ln x-\\int \\frac{x}{2}dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584807145481, 160466584807145480, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584807145483, 160466584807145482, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584874254338, 160466584874254337, 1, 'fill-in', '定积分求值', '由定积分定义可得：$\\displaystyle \\int_0^2 (x+1)\\,dx=$ ____。', '[]', '$4$', '', '$\\int_0^2 (x+1)dx=\\left[\\frac{x^2}{2}+x\\right]_0^2=2+2=4$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584874254340, 160466584874254339, 1, 'short-answer', '平面图形面积', '求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。', '[]', '$\\dfrac{1}{6}$', '', '交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\int_0^1 (x-x^2)dx=\\left[\\frac{x^2}{2}-\\frac{x^3}{3}\\right]_0^1=\\frac16$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584874254342, 160466584874254341, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584874254344, 160466584874254343, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584941363201, 160466584941363200, 1, 'fill-in', '定积分求值', '由定积分定义可得：$\\displaystyle \\int_0^2 (x+1)\\,dx=$ ____。', '[]', '$4$', '', '$\\int_0^2 (x+1)dx=\\left[\\frac{x^2}{2}+x\\right]_0^2=2+2=4$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584941363203, 160466584941363202, 1, 'short-answer', '平面图形面积', '求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。', '[]', '$\\dfrac{1}{6}$', '', '交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\int_0^1 (x-x^2)dx=\\left[\\frac{x^2}{2}-\\frac{x^3}{3}\\right]_0^1=\\frac16$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584941363205, 160466584941363204, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584941363207, 160466584941363206, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466584941363209, 160466584941363208, 1, 'fill-in', '全微分计算', '设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。', '[]', '$3dx+3dy$', '', '$z_x=2xy+y^2,\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585004277762, 160466585004277761, 1, 'short-answer', '复合函数偏导', '设 $z=e^{xy}$，求 $\\dfrac{\\partial z}{\\partial x}$ 与 $\\dfrac{\\partial z}{\\partial y}$。', '[]', '$\\dfrac{\\partial z}{\\partial x}=ye^{xy},\\quad \\dfrac{\\partial z}{\\partial y}=xe^{xy}$', '', '对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\cdot y$；同理 $z_y=e^{xy}\\cdot x$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585004277764, 160466585004277763, 1, 'single-choice', '求偏导数', '设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）', '[{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}]', 'A', 'A', '把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585004277766, 160466585004277765, 1, 'multiple-choice', '偏导与全微分性质', '下列关于多元函数求导的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585004277768, 160466585004277767, 1, 'fill-in', '全微分计算', '设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。', '[]', '$3dx+3dy$', '', '$z_x=2xy+y^2,\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585004277770, 160466585004277769, 1, 'short-answer', '复合函数偏导', '设 $z=e^{xy}$，求 $\\dfrac{\\partial z}{\\partial x}$ 与 $\\dfrac{\\partial z}{\\partial y}$。', '[]', '$\\dfrac{\\partial z}{\\partial x}=ye^{xy},\\quad \\dfrac{\\partial z}{\\partial y}=xe^{xy}$', '', '对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\cdot y$；同理 $z_y=e^{xy}\\cdot x$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585075580929, 160466585075580928, 1, 'single-choice', '求偏导数', '设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）', '[{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}]', 'A', 'A', '把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585075580931, 160466585075580930, 1, 'multiple-choice', '偏导与全微分性质', '下列关于多元函数求导的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585075580933, 160466585075580932, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585075580935, 160466585075580934, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585075580937, 160466585075580936, 1, 'single-choice', '二元函数极值', '函数 $f(x,y)=x^2+y^2$ 在 $(0,0)$ 处取得（  ）', '[{\"key\": \"A\", \"content\": \"极大值\"}, {\"key\": \"B\", \"content\": \"极小值\"}, {\"key\": \"C\", \"content\": \"鞍点\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '$x^2+y^2\\ge0$，且仅在 $(0,0)$ 取到 $0$，故为极小值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585142689794, 160466585142689793, 1, 'multiple-choice', '多元极值理论', '下列关于多元函数极值的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"求条件极值常用拉格朗日乘数法\"}, {\"key\": \"B\", \"content\": \"驻点是偏导都为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"Hessian 判别法中 $D=f_{xx}f_{yy}-f_{xy}^2$，若 $D>0$ 且 $f_{xx}>0$，则为极小值\"}, {\"key\": \"D\", \"content\": \"条件极值与无条件极值的驻点条件完全相同\"}, {\"key\": \"E\", \"content\": \"鞍点既不是极大值点，也不是极小值点\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，条件极值还要结合约束方程。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585142689796, 160466585142689795, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585142689798, 160466585142689797, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585142689800, 160466585142689799, 1, 'single-choice', '二元函数极值', '函数 $f(x,y)=x^2+y^2$ 在 $(0,0)$ 处取得（  ）', '[{\"key\": \"A\", \"content\": \"极大值\"}, {\"key\": \"B\", \"content\": \"极小值\"}, {\"key\": \"C\", \"content\": \"鞍点\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '$x^2+y^2\\ge0$，且仅在 $(0,0)$ 取到 $0$，故为极小值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585209798658, 160466585209798657, 1, 'multiple-choice', '多元极值理论', '下列关于多元函数极值的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"求条件极值常用拉格朗日乘数法\"}, {\"key\": \"B\", \"content\": \"驻点是偏导都为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"Hessian 判别法中 $D=f_{xx}f_{yy}-f_{xy}^2$，若 $D>0$ 且 $f_{xx}>0$，则为极小值\"}, {\"key\": \"D\", \"content\": \"条件极值与无条件极值的驻点条件完全相同\"}, {\"key\": \"E\", \"content\": \"鞍点既不是极大值点，也不是极小值点\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，条件极值还要结合约束方程。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585209798660, 160466585209798659, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585209798662, 160466585209798661, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585209798664, 160466585209798663, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585209798666, 160466585209798665, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585272713218, 160466585272713217, 1, 'fill-in', '区域面积', '填空：$\\displaystyle \\iint_{x^2+y^2\\le 1}1\\,dA=$ ____。', '[]', '$\\pi$', '', '被积函数为 $1$，积分等于单位圆面积，所以为 $\\pi$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585272713220, 160466585272713219, 1, 'short-answer', '极坐标二重积分', '用极坐标计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 4}(x^2+y^2)\\,dA$。', '[]', '$8\\pi$', '', '极坐标下 $x^2+y^2=r^2,\\ dA=rdrd\\theta$。原式 $=\\int_0^{2\\pi}\\int_0^2 r^3drd\\theta=2\\pi\\cdot\\left[\\frac{r^4}{4}\\right]_0^2=8\\pi$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585272713222, 160466585272713221, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585272713224, 160466585272713223, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585339822083, 160466585339822082, 1, 'fill-in', '区域面积', '填空：$\\displaystyle \\iint_{x^2+y^2\\le 1}1\\,dA=$ ____。', '[]', '$\\pi$', '', '被积函数为 $1$，积分等于单位圆面积，所以为 $\\pi$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585339822085, 160466585339822084, 1, 'short-answer', '极坐标二重积分', '用极坐标计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 4}(x^2+y^2)\\,dA$。', '[]', '$8\\pi$', '', '极坐标下 $x^2+y^2=r^2,\\ dA=rdrd\\theta$。原式 $=\\int_0^{2\\pi}\\int_0^2 r^3drd\\theta=2\\pi\\cdot\\left[\\frac{r^4}{4}\\right]_0^2=8\\pi$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585402736643, 160466585402736642, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585402736645, 160466585402736644, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845507, 160466585469845506, 1, 'fill-in', '初值问题', '求初值问题 $y\'=3x^2,\\ y(0)=1$ 的解：$y=$ ____。', '[]', '$x^3+1$', '', '积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845509, 160466585469845508, 1, 'short-answer', '二阶常系数方程', '求解微分方程：$y\'\'-3y\'+2y=0$。', '[]', '$y=C_1e^x+C_2e^{2x}$', '', '特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845511, 160466585469845510, 1, 'single-choice', '通解求法', '微分方程 $y\'=2x$ 的通解为（  ）', '[{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}]', 'A', 'A', '两边积分得 $y=\\int 2x\\,dx=x^2+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845513, 160466585469845512, 1, 'multiple-choice', '微分方程基础', '下列关于常微分方程的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845515, 160466585469845514, 1, 'fill-in', '初值问题', '求初值问题 $y\'=3x^2,\\ y(0)=1$ 的解：$y=$ ____。', '[]', '$x^3+1$', '', '积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585469845517, 160466585469845516, 1, 'short-answer', '二阶常系数方程', '求解微分方程：$y\'\'-3y\'+2y=0$。', '[]', '$y=C_1e^x+C_2e^{2x}$', '', '特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585532760067, 160466585532760066, 1, 'single-choice', '通解求法', '微分方程 $y\'=2x$ 的通解为（  ）', '[{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}]', 'A', 'A', '两边积分得 $y=\\int 2x\\,dx=x^2+C$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585532760069, 160466585532760068, 1, 'multiple-choice', '微分方程基础', '下列关于常微分方程的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585532760071, 160466585532760070, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585532760073, 160466585532760072, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585532760075, 160466585532760074, 1, 'single-choice', '级数敛散性', '级数 $\\displaystyle \\sum_{n=1}^{\\infty}\\frac{1}{n^2}$ 的敛散性为（  ）', '[{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'C', 'C', '这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585595674625, 160466585595674624, 1, 'multiple-choice', '级数基本结论', '下列关于无穷级数的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，交错调和级数只是条件收敛。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585658589186, 160466585658589185, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585658589188, 160466585658589187, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585725698051, 160466585725698050, 1, 'single-choice', '级数敛散性', '级数 $\\displaystyle \\sum_{n=1}^{\\infty}\\frac{1}{n^2}$ 的敛散性为（  ）', '[{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'C', 'C', '这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585725698053, 160466585725698052, 1, 'multiple-choice', '级数基本结论', '下列关于无穷级数的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，交错调和级数只是条件收敛。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585725698055, 160466585725698054, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585788612610, 160466585788612609, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585788612612, 160466585788612611, 1, 'single-choice', '二阶行列式', '计算行列式 $\\begin{vmatrix}1&2\\\\3&4\\end{vmatrix}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}]', 'A', 'A', '$1\\cdot4-2\\cdot3=-2$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585788612614, 160466585788612613, 1, 'multiple-choice', '行列式性质', '下列关于行列式的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}]', 'ABE', 'ABE', 'A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585788612616, 160466585788612615, 1, 'fill-in', '三角行列式', '填空：$\\begin{vmatrix}2&0&0\\\\1&3&0\\\\4&5&6\\end{vmatrix}=$ ____。', '[]', '$36$', '', '下三角行列式等于主对角线元素之积，故为 $2\\cdot3\\cdot6=36$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585855721473, 160466585855721472, 1, 'short-answer', '三阶行列式计算', '计算行列式：$\\begin{vmatrix}1&1&1\\\\1&2&3\\\\1&3&6\\end{vmatrix}$。', '[]', '$1$', '', '可作行变换：$R_2\\leftarrow R_2-R_1,\\ R_3\\leftarrow R_3-R_1$，得 $\\begin{vmatrix}1&1&1\\\\0&1&2\\\\0&2&5\\end{vmatrix}$，再按第一列展开得 $\\begin{vmatrix}1&2\\\\2&5\\end{vmatrix}=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585855721475, 160466585855721474, 1, 'single-choice', '二阶行列式', '计算行列式 $\\begin{vmatrix}1&2\\\\3&4\\end{vmatrix}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}]', 'A', 'A', '$1\\cdot4-2\\cdot3=-2$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585855721477, 160466585855721476, 1, 'multiple-choice', '行列式性质', '下列关于行列式的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}]', 'ABE', 'ABE', 'A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585855721479, 160466585855721478, 1, 'fill-in', '三角行列式', '填空：$\\begin{vmatrix}2&0&0\\\\1&3&0\\\\4&5&6\\end{vmatrix}=$ ____。', '[]', '$36$', '', '下三角行列式等于主对角线元素之积，故为 $2\\cdot3\\cdot6=36$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585855721481, 160466585855721480, 1, 'short-answer', '三阶行列式计算', '计算行列式：$\\begin{vmatrix}1&1&1\\\\1&2&3\\\\1&3&6\\end{vmatrix}$。', '[]', '$1$', '', '可作行变换：$R_2\\leftarrow R_2-R_1,\\ R_3\\leftarrow R_3-R_1$，得 $\\begin{vmatrix}1&1&1\\\\0&1&2\\\\0&2&5\\end{vmatrix}$，再按第一列展开得 $\\begin{vmatrix}1&2\\\\2&5\\end{vmatrix}=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585918636035, 160466585918636034, 1, 'single-choice', '矩阵乘法', '设 $A=\\begin{pmatrix}1&2\\\\0&1\\end{pmatrix},\\ B=\\begin{pmatrix}2&0\\\\1&3\\end{pmatrix}$，则 $AB=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}]', 'A', 'A', '按矩阵乘法计算：$AB=\\begin{pmatrix}1\\cdot2+2\\cdot1 & 1\\cdot0+2\\cdot3\\\\ 0\\cdot2+1\\cdot1 & 0\\cdot0+1\\cdot3\\end{pmatrix}=\\begin{pmatrix}4&6\\\\1&3\\end{pmatrix}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585918636037, 160466585918636036, 1, 'multiple-choice', '矩阵与逆矩阵性质', '下列关于矩阵运算的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}]', 'ABC', 'ABC', 'A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585918636039, 160466585918636038, 1, 'fill-in', '逆矩阵', '设 $A=\\begin{pmatrix}1&0\\\\0&2\\end{pmatrix}$，则 $A^{-1}=$ ____。', '[]', '$\\begin{pmatrix}1&0\\\\0&\\frac12\\end{pmatrix}$', '', '对角矩阵求逆就是对角元分别取倒数。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585918636041, 160466585918636040, 1, 'short-answer', '二阶矩阵求逆', '求矩阵 $A=\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}$ 的逆矩阵。', '[]', '$A^{-1}=\\begin{pmatrix}-2&1\\\\ \\frac32&-\\frac12\\end{pmatrix}$', '', '二阶矩阵逆公式：$A^{-1}=\\frac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585981550594, 160466585981550593, 1, 'single-choice', '矩阵乘法', '设 $A=\\begin{pmatrix}1&2\\\\0&1\\end{pmatrix},\\ B=\\begin{pmatrix}2&0\\\\1&3\\end{pmatrix}$，则 $AB=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}]', 'A', 'A', '按矩阵乘法计算：$AB=\\begin{pmatrix}1\\cdot2+2\\cdot1 & 1\\cdot0+2\\cdot3\\\\ 0\\cdot2+1\\cdot1 & 0\\cdot0+1\\cdot3\\end{pmatrix}=\\begin{pmatrix}4&6\\\\1&3\\end{pmatrix}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585981550596, 160466585981550595, 1, 'multiple-choice', '矩阵与逆矩阵性质', '下列关于矩阵运算的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}]', 'ABC', 'ABC', 'A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466585981550598, 160466585981550597, 1, 'fill-in', '逆矩阵', '设 $A=\\begin{pmatrix}1&0\\\\0&2\\end{pmatrix}$，则 $A^{-1}=$ ____。', '[]', '$\\begin{pmatrix}1&0\\\\0&\\frac12\\end{pmatrix}$', '', '对角矩阵求逆就是对角元分别取倒数。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586044465153, 160466586044465152, 1, 'short-answer', '二阶矩阵求逆', '求矩阵 $A=\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}$ 的逆矩阵。', '[]', '$A^{-1}=\\begin{pmatrix}-2&1\\\\ \\frac32&-\\frac12\\end{pmatrix}$', '', '二阶矩阵逆公式：$A^{-1}=\\frac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586044465155, 160466586044465154, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586044465157, 160466586044465156, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586044465159, 160466586044465158, 1, 'fill-in', '矩阵秩', '矩阵 $A=\\begin{pmatrix}1&2\\\\2&4\\end{pmatrix}$ 的秩为 ____。', '[]', '$1$', '', '第二行是第一行的 2 倍，因此只有一行线性无关，秩为 1。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586111574017, 160466586111574016, 1, 'short-answer', '向量组线性无关', '判断向量组 $\\alpha_1=(1,1,0),\\ \\alpha_2=(1,0,1),\\ \\alpha_3=(0,1,1)$ 是否线性无关。', '[]', '线性无关。', '', '以这三个向量为列组成矩阵 $A=\\begin{pmatrix}1&1&0\\\\1&0&1\\\\0&1&1\\end{pmatrix}$，其行列式为 $-2\\ne0$，故三向量线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586111574019, 160466586111574018, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586111574021, 160466586111574020, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586174488579, 160466586174488578, 1, 'fill-in', '矩阵秩', '矩阵 $A=\\begin{pmatrix}1&2\\\\2&4\\end{pmatrix}$ 的秩为 ____。', '[]', '$1$', '', '第二行是第一行的 2 倍，因此只有一行线性无关，秩为 1。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586174488581, 160466586174488580, 1, 'short-answer', '向量组线性无关', '判断向量组 $\\alpha_1=(1,1,0),\\ \\alpha_2=(1,0,1),\\ \\alpha_3=(0,1,1)$ 是否线性无关。', '[]', '线性无关。', '', '以这三个向量为列组成矩阵 $A=\\begin{pmatrix}1&1&0\\\\1&0&1\\\\0&1&1\\end{pmatrix}$，其行列式为 $-2\\ne0$，故三向量线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586174488583, 160466586174488582, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586174488585, 160466586174488584, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586237403138, 160466586237403137, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586237403140, 160466586237403139, 1, 'short-answer', '基础解系', '求齐次线性方程组 $\\begin{cases}x+y+z=0\\\\x-y+z=0\\end{cases}$ 的基础解系。', '[]', '基础解系可取 $\\{(-1,0,1)^T\\}$。', '', '由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\{(-1,0,1)^T\\}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586237403142, 160466586237403141, 1, 'single-choice', '齐次方程组', '齐次线性方程组 $Ax=0$ 一定有（  ）', '[{\"key\": \"A\", \"content\": \"无解\"}, {\"key\": \"B\", \"content\": \"唯一解\"}, {\"key\": \"C\", \"content\": \"零解\"}, {\"key\": \"D\", \"content\": \"无穷多解\"}]', 'C', 'C', '齐次线性方程组至少有零解。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586300317698, 160466586300317697, 1, 'multiple-choice', '线性方程组理论', '下列关于线性方程组的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"齐次线性方程组一定有解\"}, {\"key\": \"B\", \"content\": \"非齐次线性方程组可能无解\"}, {\"key\": \"C\", \"content\": \"若系数矩阵满秩，则齐次方程组只有零解\"}, {\"key\": \"D\", \"content\": \"基础解系中的向量一定线性无关\"}, {\"key\": \"E\", \"content\": \"非齐次方程组有解时，其通解等于对应齐次方程组通解\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，非齐次通解=一个特解+对应齐次通解。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586300317700, 160466586300317699, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
