INSERT INTO `question_version` VALUES (160466586300317704, 160466586300317703, 1, 'single-choice', '齐次方程组', '齐次线性方程组 $Ax=0$ 一定有（  ）', '[{\"key\": \"A\", \"content\": \"无解\"}, {\"key\": \"B\", \"content\": \"唯一解\"}, {\"key\": \"C\", \"content\": \"零解\"}, {\"key\": \"D\", \"content\": \"无穷多解\"}]', 'C', 'C', '齐次线性方程组至少有零解。', NULL, 160333690390446080, '2026-03-23 19:16:55');
