INSERT INTO `question_version` VALUES (160466586497449989, 160466586497449988, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 160333690390446080, '2026-03-23 19:16:55');
