INSERT INTO `question_version` VALUES (160466586564558849, 160466586564558848, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586564558851, 160466586564558850, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586564558853, 160466586564558852, 1, 'single-choice', '事件并概率', '设 $P(A)=0.4,\\ P(B)=0.5,\\ P(A\\cap B)=0.2$，则 $P(A\\cup B)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}]', 'A', 'A', '用加法公式：$P(A\\cup B)=P(A)+P(B)-P(A\\cap B)=0.7$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586564558855, 160466586564558854, 1, 'multiple-choice', '概率基础公式', '下列关于概率论基础的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，互斥且概率都非零时不独立。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586564558857, 160466586564558856, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473410, 160466586627473409, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473412, 160466586627473411, 1, 'single-choice', '事件并概率', '设 $P(A)=0.4,\\ P(B)=0.5,\\ P(A\\cap B)=0.2$，则 $P(A\\cup B)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}]', 'A', 'A', '用加法公式：$P(A\\cup B)=P(A)+P(B)-P(A\\cap B)=0.7$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473414, 160466586627473413, 1, 'multiple-choice', '概率基础公式', '下列关于概率论基础的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，互斥且概率都非零时不独立。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473416, 160466586627473415, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473418, 160466586627473417, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586627473420, 160466586627473419, 1, 'single-choice', '分布列计算', '设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\le1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}]', 'C', 'C', '$P(X\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387969, 160466586690387968, 1, 'multiple-choice', '分布函数与密度', '下列关于随机变量分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387971, 160466586690387970, 1, 'fill-in', '密度函数求概率', '设连续型随机变量 $X$ 的密度 $fx=\\begin{cases}2x,&0<x<1\\\\0,&\\text{其他}\\end{cases}$，则 $P(X<\\tfrac12)=$ ____。', '[]', '$\\dfrac{1}{4}$', '', '$P(X<\\frac12)=\\int_0^{1/2}2x\\,dx=\\left[x^2\\right]_0^{1/2}=\\frac14$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387973, 160466586690387972, 1, 'short-answer', '分布函数求概率', '设随机变量 $X$ 的分布函数为 $Fx=\\begin{cases}0,&x<0\\\\x^2,&0\\le x<1\\\\1,&x\\ge1\\end{cases}$。求 $P(\\tfrac12<X\\le1)$。', '[]', '$\\dfrac{3}{4}$', '', '$P(\\frac12<X\\le1)=F(1)-F(\\frac12)=1-\\frac14=\\frac34$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387975, 160466586690387974, 1, 'single-choice', '分布列计算', '设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\le1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}]', 'C', 'C', '$P(X\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387977, 160466586690387976, 1, 'multiple-choice', '分布函数与密度', '下列关于随机变量分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586690387979, 160466586690387978, 1, 'fill-in', '密度函数求概率', '设连续型随机变量 $X$ 的密度 $fx=\\begin{cases}2x,&0<x<1\\\\0,&\\text{其他}\\end{cases}$，则 $P(X<\\tfrac12)=$ ____。', '[]', '$\\dfrac{1}{4}$', '', '$P(X<\\frac12)=\\int_0^{1/2}2x\\,dx=\\left[x^2\\right]_0^{1/2}=\\frac14$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496835, 160466586757496834, 1, 'short-answer', '分布函数求概率', '设随机变量 $X$ 的分布函数为 $Fx=\\begin{cases}0,&x<0\\\\x^2,&0\\le x<1\\\\1,&x\\ge1\\end{cases}$。求 $P(\\tfrac12<X\\le1)$。', '[]', '$\\dfrac{3}{4}$', '', '$P(\\frac12<X\\le1)=F(1)-F(\\frac12)=1-\\frac14=\\frac34$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496837, 160466586757496836, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496839, 160466586757496838, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496841, 160466586757496840, 1, 'fill-in', '泊松分布', '设 $X\\sim Poisson(\\lambda=2)$，则 $P(X=0)=$ ____。', '[]', '$e^{-2}$', '', '泊松分布概率公式：$P(X=k)=e^{-\\lambda}\\frac{\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496843, 160466586757496842, 1, 'short-answer', '正态分布对称性', '设 $X\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。', '[]', '$P(X>0)=\\dfrac12$', '', '标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\frac12$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496845, 160466586757496844, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586757496847, 160466586757496846, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 160333690390446080, '2026-03-23 19:16:55');
