INSERT INTO `question_version` VALUES (160466586887520268, 160466586887520267, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586887520270, 160466586887520269, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586954629121, 160466586954629120, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586954629123, 160466586954629122, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586954629125, 160466586954629124, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586954629127, 160466586954629126, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466586954629129, 160466586954629128, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466587017543683, 160466587017543682, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466587017543685, 160466587017543684, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (160466587017543687, 160466587017543686, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 160333690390446080, '2026-03-23 19:16:55');
INSERT INTO `question_version` VALUES (187185931646664706, 187185931646664705, 1, 'single-choice', '二重积分的几何意义', '设 D 是平面有界闭区域，函数 f(x,y) 在 D 上连续。若 f(x,y) >= 0，则二重积分 \\iint_D f(x,y) dA 的几何意义通常是什么？', '[{\"key\": \"A\", \"content\": \"曲顶柱体的体积\"}, {\"key\": \"B\", \"content\": \"平面区域 D 的周长\"}, {\"key\": \"C\", \"content\": \"函数 f(x,y) 的最大值\"}, {\"key\": \"D\", \"content\": \"区域 D 的边界曲线长度\"}]', 'A', 'A', '当 f(x,y) >= 0 时，二重积分 \\iint_D f(x,y) dA 表示以 D 为底、以 z=f(x,y) 为顶面的曲顶柱体体积。', NULL, 160333690390446080, '2026-06-05 12:50:04');
INSERT INTO `question_version` VALUES (187186037313765377, 187186037313765376, 1, 'short-answer', '极坐标下的二重积分计算', '计算二重积分 \\iint_D (x^2+y^2) dA，其中 D 是由 x^2+y^2 <= 1 围成的圆域。', NULL, '\\frac{\\pi}{2}', '', '将区域 D 转换为极坐标，x^2+y^2=r^2，dA=rdrd\\theta。积分变为 \\int_0^{2\\pi}\\int_0^1 r^2\\cdot r drd\\theta=2\\pi\\cdot\\frac{1}{4}=\\frac{\\pi}{2}。', NULL, 160333690390446080, '2026-06-05 12:50:29');
INSERT INTO `question_version` VALUES (195587907774316546, 195587907774316545, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin x - x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}]', 'A', 'A', '用泰勒展开：$\\sin x = x-\\frac{x^3}{6}+o(x^3)$，代入得 $\\frac{\\sin x-x}{x^3}=\\frac{-x^3/6+o(x^3)}{x^3}\\to -\\frac{1}{6}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587907975643137, 195587907975643136, 1, 'single-choice', '泰勒展开系数', '函数 $e^x$ 在 $x=0$ 处的二阶泰勒展开中，$x^2$ 项系数为（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$\\\\frac{1}{2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$2$\"}]', 'B', 'B', '$e^x = 1+x+\\frac{x^2}{2}+o(x^2)$，所以 $x^2$ 项系数为 $\\frac{1}{2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587907975643139, 195587907975643138, 1, 'multiple-choice', '级数收敛性判断', '下列级数中哪些收敛？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n}$\"}, {\"key\": \"B\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^2}$\"}, {\"key\": \"C\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{(-1)^{n}}{n}$\"}, {\"key\": \"D\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{\\\\sqrt{n}}$\"}, {\"key\": \"E\", \"content\": \"$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{n^{3/2}}$\"}]', 'BCE', 'BCE', 'A 为调和级数发散；B 为 $p=2$ 的 $p$ 级数收敛；C 为交错调和级数收敛；D 为 $p=\\frac12$ 的 $p$ 级数发散；E 为 $p=\\frac32$ 的 $p$ 级数收敛。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908030169089, 195587908030169088, 1, 'multiple-choice', '梯度与方向导数', '设 $f(x,y)=x^2y+y^3$。下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$f_x=2xy$\"}, {\"key\": \"B\", \"content\": \"$f_y=x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"在点处沿单位向量 $\\\\mathbf{u}$ 的方向导数 $D_{\\\\mathbf{u}}f=\\\\nabla f\\\\cdot \\\\mathbf{u}$\"}, {\"key\": \"D\", \"content\": \"点处方向导数的最大值为 $\\\\|\\\\nabla f\\\\|$\"}, {\"key\": \"E\", \"content\": \"$\\\\nabla f$ 与等值线在该点的切向量同向\"}]', 'ABCD', 'ABCD', 'A、B 为求偏导；C 为方向导数公式；D 为方向导数最大值性质；E 错：$\\nabla f$ 与等值线切向量垂直。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908030169091, 195587908030169090, 1, 'fill-in', '定积分计算', '计算定积分：$\\displaystyle \\int_{0}^{\\pi/2}\\sin x\\,dx=$ ____。', '[]', '$1$', '', '$\\int \\sin x\\,dx=-\\cos x$，代入 $0$ 到 $\\pi/2$：$-\\cos(\\pi/2)-(-\\cos 0)=0-(-1)=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908093083651, 195587908093083650, 1, 'fill-in', '二重积分（极坐标）', '计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 1}(x^2+y^2)\\,dA=$ ____。', '[]', '$\\frac{\\pi}{2}$', '', '用极坐标：$x^2+y^2=r^2,\\ dA=r\\,dr\\,d\\theta$。$\\int_{0}^{2\\pi}\\int_{0}^{1} r^2\\cdot r\\,dr\\,d\\theta=\\int_{0}^{2\\pi}\\left[\\frac{r^4}{4}\\right]_{0}^{1}d\\theta=2\\pi\\cdot\\frac14=\\frac{\\pi}{2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908160192513, 195587908160192512, 1, 'true-false', '可微充分条件', '判断：若二元函数 $f$ 在 $(0,0)$ 的某邻域内一阶偏导 $f_x,f_y$ 存在且连续，则 $f$ 在 $(0,0)$ 可微。', '[]', 'T', 'T', '这是经典充分条件：$f_x,f_y$ 在邻域内连续（即 $f\\in C^1$）$\\Rightarrow$ 在该点可微。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908160192515, 195587908160192514, 1, 'true-false', '方向导数与可微', '判断：若二元函数 $f$ 在 $(0,0)$ 处沿任意方向的方向导数都存在，则 $f$ 在 $(0,0)$ 可微。', '[]', 'F', 'F', '方向导数全存在并不保证可微（例如 $f(x,y)=\\sqrt{|xy|}$ 在原点方向导数都存在但不可微）。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908160192517, 195587908160192516, 1, 'short-answer', '一阶线性微分方程', '求解初值问题：$y\'+y=e^x,\\ y(0)=1$。', '[]', '$y(x)=\\frac12 e^x+\\frac12 e^{-x}$', '', '用积分因子 $e^x$：$(ye^x)\'=e^{2x}$。积分得 $ye^x=\\frac12 e^{2x}+C$，故 $y=\\frac12 e^x+Ce^{-x}$。代入 $y(0)=1$ 得 $C=\\frac12$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908227301378, 195587908227301377, 1, 'short-answer', '切平面方程', '求曲面 $z=x^2+y^2$ 在点 $(1,2,5)$ 处的切平面方程。', '[]', '$z=2x+4y-5$', '', '设 $f(x,y)=x^2+y^2$，则 $f_x=2x,\\ f_y=2y$。在 $(1,2)$ 处 $f_x=2,\\ f_y=4$，$z_0=5$。切平面：$z=z_0+f_x(x-1)+f_y(y-2)=5+2(x-1)+4(y-2)=2x+4y-5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908227301380, 195587908227301379, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sinx-x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{1}{6}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{1}{6}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{1}{3}$\"}]', 'A', 'A', '用展开 $\\sinx=x-\\frac{x^3}{6}+o(x^3)$，故极限为 $-\\frac{1}{6}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908290215937, 195587908290215936, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908290215939, 195587908290215938, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin(2x)-2x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{4}{3}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{4}{3}$\"}, {\"key\": \"D\", \"content\": \"$-\\\\frac{8}{3}$\"}]', 'A', 'A', '用展开 $\\sin(2x)=2x-\\frac{(2x)^3}{6}+o(x^3)$，故极限为 $-\\frac{4}{3}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908357324801, 195587908357324800, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908357324803, 195587908357324802, 1, 'fill-in', '指数函数极限', '填空：$\\displaystyle \\lim_{x\\to 0}\\frac{e^{x}-1-x}{x^2}=$ ____。', '[]', '$\\frac{1}{2}$', '', '由 $e^{x}=1+x+\\frac{x^2}{2}+o(x^2)$，极限为 $\\frac{1}{2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908420239363, 195587908420239362, 1, 'short-answer', '连续条件求参', '设 $fx=\\begin{cases}\\dfrac{x^2-1}{x-1}, & x\\ne 1,\\\\ a, & x=1.\\end{cases}$\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。', '[]', '$a=2$', '', '因为当 $x\\ne1$ 时，$fx=x+1$。所以 $\\lim_{x\\to1}fx=2$。连续要求 $a=f(1)=2$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908420239365, 195587908420239364, 1, 'single-choice', '极限计算', '计算极限：$\\displaystyle \\lim_{x\\to 0}\\frac{\\sin(3x)-3x}{x^3}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-\\\\frac{9}{2}$\"}, {\"key\": \"B\", \"content\": \"$0$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac{9}{2}$\"}, {\"key\": \"D\", \"content\": \"$-9$\"}]', 'A', 'A', '用展开 $\\sin(3x)=3x-\\frac{(3x)^3}{6}+o(x^3)$，故极限为 $-\\frac{9}{2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908487348225, 195587908487348224, 1, 'multiple-choice', '连续与间断', '关于函数连续与间断点，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若函数在点 $x_0$ 可导，则一定在 $x_0$ 连续\"}, {\"key\": \"B\", \"content\": \"若左右极限都存在但不相等，则函数在该点连续\"}, {\"key\": \"C\", \"content\": \"若 $\\\\lim_{x\\\\to x_0}fx$ 存在且等于 $f(x_0)$，则 $f$ 在 $x_0$ 连续\"}, {\"key\": \"D\", \"content\": \"第一类间断点一定极限不存在\"}, {\"key\": \"E\", \"content\": \"若函数在点 $x_0$ 连续，则左右极限都存在且都等于 $f(x_0)$\"}]', 'ACE', 'ACE', 'A 正确：可导必连续；B 错：左右极限不等时为跳跃间断；C 正确；D 错：可去间断点与跳跃间断点都属第一类间断点；E 正确。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908487348227, 195587908487348226, 1, 'fill-in', '指数函数极限', '填空：$\\displaystyle \\lim_{x\\to 0}\\frac{e^{2x}-1-2x}{x^2}=$ ____。', '[]', '$2$', '', '由 $e^{2x}=1+2x+\\frac{(2x)^2}{2}+o(x^2)$，极限为 $2$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908550262786, 195587908550262785, 1, 'short-answer', '连续条件求参', '设 $fx=\\begin{cases}\\dfrac{x^2-1}{x-1}, & x\\ne 1,\\\\ a, & x=1.\\end{cases}$\n求实数 $a$ 使得 $fx$ 在 $x=1$ 处连续。', '[]', '$a=2$', '', '因为当 $x\\ne1$ 时，$fx=x+1$。所以 $\\lim_{x\\to1}fx=2$。连续要求 $a=f(1)=2$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908550262788, 195587908550262787, 1, 'single-choice', '复合函数求导', '求导：$y=\\sin(2x^2)$，则 $y\'$ 为（  ）', '[{\"key\": \"A\", \"content\": \"$4 x \\\\cos{\\\\left(2 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$2\\\\cos(2x^2)$\"}, {\"key\": \"C\", \"content\": \"$4x\\\\sin(2x^2)$\"}, {\"key\": \"D\", \"content\": \"$4x\\\\cos x$\"}]', 'A', 'A', '由链式法则，$y\'=4 x \\cos{\\left(2 x^{2} \\right)}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908550262790, 195587908550262789, 1, 'multiple-choice', '导数公式', '关于求导公式，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}]', 'ACD', 'ACD', 'A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908613177345, 195587908613177344, 1, 'fill-in', '隐函数求导', '设隐函数由 $x^2+y^2=4$ 确定，则 $\\dfrac{dy}{dx}=$ ____。', '[]', '$-\\dfrac{x}{y}$', '', '两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\dfrac{x}{y}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908613177347, 195587908613177346, 1, 'short-answer', '乘积法则求导', '求函数 $y=x^{2}e^x$ 的导数。', '[]', '$y\'=e^x\\left(x^2+2x^1\\right)$', '', '用乘积法则：$y\'=2x^1e^x+x^2e^x=e^x\\left(x^2+2x^1\\right)$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908676091907, 195587908676091906, 1, 'single-choice', '复合函数求导', '求导：$y=\\sin(3x^2)$，则 $y\'$ 为（  ）', '[{\"key\": \"A\", \"content\": \"$6 x \\\\cos{\\\\left(3 x^{2} \\\\right)}$\"}, {\"key\": \"B\", \"content\": \"$3\\\\cos(3x^2)$\"}, {\"key\": \"C\", \"content\": \"$6x\\\\sin(3x^2)$\"}, {\"key\": \"D\", \"content\": \"$6x\\\\cos x$\"}]', 'A', 'A', '由链式法则，$y\'=6 x \\cos{\\left(3 x^{2} \\right)}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908676091909, 195587908676091908, 1, 'multiple-choice', '导数公式', '关于求导公式，下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\ln x)=\\\\dfracx\\\\ (x>0)$\"}, {\"key\": \"B\", \"content\": \"$\\\\dfrac{d}{dx}(e^{ax})=ae^x$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\arctan x)=\\\\dfrac{1}{1+x^2}$\"}, {\"key\": \"D\", \"content\": \"$\\\\dfrac{d}{dx}(\\\\sin x\\\\cos x)=\\\\cos^2x-\\\\sin^2x$\"}, {\"key\": \"E\", \"content\": \"$\\\\dfrac{d}{dx}(x^n)=nx^{n-1}$ 仅对正整数 $n$ 成立\"}]', 'ACD', 'ACD', 'A、C、D 正确；B 错，应为 $ae^{ax}$；E 错，该公式对任意实数幂在有定义处都可成立。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908743200770, 195587908743200769, 1, 'fill-in', '隐函数求导', '设隐函数由 $x^2+y^2=9$ 确定，则 $\\dfrac{dy}{dx}=$ ____。', '[]', '$-\\dfrac{x}{y}$', '', '两边对 $x$ 求导得 $2x+2yy\'=0$，故 $y\'=-\\dfrac{x}{y}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908743200772, 195587908743200771, 1, 'short-answer', '乘积法则求导', '求函数 $y=x^{3}e^x$ 的导数。', '[]', '$y\'=e^x\\left(x^3+3x^2\\right)$', '', '用乘积法则：$y\'=3x^2e^x+x^3e^x=e^x\\left(x^3+3x^2\\right)$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908743200774, 195587908743200773, 1, 'single-choice', '极值点个数', '函数 $fx=x^3-3x$ 的极值点个数为（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}]', 'C', 'C', '$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\pm1$，且都发生极值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908743200776, 195587908743200775, 1, 'multiple-choice', '单调性与最值', '下列关于导数应用的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}]', 'ACE', 'ACE', 'A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908822892546, 195587908822892545, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908822892548, 195587908822892547, 1, 'short-answer', '单调区间与极值', '求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。', '[]', '递增区间：$(-\\infty,0)\\cup(2,+\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。', '', '$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\infty,0)$ 与 $(2,+\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908822892550, 195587908822892549, 1, 'single-choice', '极值点个数', '函数 $fx=x^3-3x$ 的极值点个数为（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$3$\"}]', 'C', 'C', '$f\'x=3x^2-3=3(x-1)(x+1)$，驻点为 $x=\\pm1$，且都发生极值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908873224193, 195587908873224192, 1, 'multiple-choice', '单调性与最值', '下列关于导数应用的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $f\'x>0$，则 $f$ 在该区间单调递增\"}, {\"key\": \"B\", \"content\": \"极值点一定是导数为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"若 $f\'(x_0)=0$ 且 $f\'\'(x_0)>0$，则 $x_0$ 为极小值点\"}, {\"key\": \"D\", \"content\": \"最值一定在驻点处取得\"}, {\"key\": \"E\", \"content\": \"闭区间上求最值时要比较端点和驻点函数值\"}]', 'ACE', 'ACE', 'A、C、E 正确；B 错，极值点也可能不可导；D 错，最值也可能在端点取得。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908873224195, 195587908873224194, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 195585380265754624, '2026-06-28 17:16:31');
