INSERT INTO `question_version` VALUES (195587908940333062, 195587908940333061, 1, 'fill-in', '最小值计算', '求函数 $fx=x+\\dfrac{1}{x}\\ (x>0)$ 的最小值：____。', '[]', '$2$', '', '$f\'x=1-\\frac1{x^2}=0$ 得 $x=1$，此时最小值为 $2$。也可用均值不等式。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587908940333064, 195587908940333063, 1, 'short-answer', '单调区间与极值', '求函数 $fx=x^3-3x^2+1$ 的单调区间与极值。', '[]', '递增区间：$(-\\infty,0)\\cup(2,+\\infty)$；递减区间：$(0,2)$；极大值为 $1$，极小值为 $-3$。', '', '$f\'x=3x^2-6x=3x(x-2)$。作符号分析：在 $(-\\infty,0)$ 与 $(2,+\\infty)$ 上为正，在 $(0,2)$ 上为负。故 $x=0$ 处极大值 $f(0)=1$，$x=2$ 处极小值 $f(2)=-3$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909003247618, 195587909003247617, 1, 'single-choice', '幂函数积分', '不定积分 $\\displaystyle \\int x^2 \\, dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"B\", \"content\": \"$x^3+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^2}{2}+C$\"}, {\"key\": \"D\", \"content\": \"$(3)x^2+C$\"}]', 'A', 'A', '用幂函数积分公式，结果为 $\\dfrac{x^3}{3}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909003247620, 195587909003247619, 1, 'multiple-choice', '基本积分公式', '下列不定积分结果正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 不严谨，应为 $\\ln|x|+C$；E 错，应为 $\\arctan x+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909003247622, 195587909003247621, 1, 'fill-in', '换元积分', '填空：$\\displaystyle \\int 2x e^{x^2}\\,dx=$ ____。', '[]', '$e^{x^2}+C$', '', '令 $u=x^2$，则 $du=2x\\,dx$，原式变为 $\\int e^u du=e^u+C=e^{x^2}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909070356481, 195587909070356480, 1, 'short-answer', '分部积分', '求不定积分：$\\displaystyle \\int x\\ln x\\,dx$。', '[]', '$\\dfrac{x^2}{2}\\ln x-\\dfrac{x^2}{4}+C$', '', '分部积分，取 $u=\\ln x,\\ dv=x\\,dx$，则 $du=\\fracx dx,\\ v=\\frac{x^2}{2}$。故原式 $=\\frac{x^2}{2}\\ln x-\\int \\frac{x}{2}dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909070356483, 195587909070356482, 1, 'single-choice', '幂函数积分', '不定积分 $\\displaystyle \\int x^3 \\, dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\dfrac{x^4}{4}+C$\"}, {\"key\": \"B\", \"content\": \"$x^4+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\dfrac{x^3}{3}+C$\"}, {\"key\": \"D\", \"content\": \"$(4)x^3+C$\"}]', 'A', 'A', '用幂函数积分公式，结果为 $\\dfrac{x^4}{4}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909070356485, 195587909070356484, 1, 'multiple-choice', '基本积分公式', '下列不定积分结果正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\int \\\\cos x\\\\,dx=\\\\sin x+C$\"}, {\"key\": \"B\", \"content\": \"$\\\\int e^x\\\\,dx=e^x+C$\"}, {\"key\": \"C\", \"content\": \"$\\\\int \\\\dfrac{1}{x}\\\\,dx=\\\\ln x+C$\"}, {\"key\": \"D\", \"content\": \"$\\\\int \\\\sec^2x\\\\,dx=\\\\tan x+C$\"}, {\"key\": \"E\", \"content\": \"$\\\\int \\\\dfrac{1}{1+x^2}\\\\,dx=\\\\ln(1+x^2)+C$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 不严谨，应为 $\\ln|x|+C$；E 错，应为 $\\arctan x+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909133271041, 195587909133271040, 1, 'fill-in', '换元积分', '填空：$\\displaystyle \\int 2x e^{x^2}\\,dx=$ ____。', '[]', '$e^{x^2}+C$', '', '令 $u=x^2$，则 $du=2x\\,dx$，原式变为 $\\int e^u du=e^u+C=e^{x^2}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909133271043, 195587909133271042, 1, 'short-answer', '分部积分', '求不定积分：$\\displaystyle \\int x\\ln x\\,dx$。', '[]', '$\\dfrac{x^2}{2}\\ln x-\\dfrac{x^2}{4}+C$', '', '分部积分，取 $u=\\ln x,\\ dv=x\\,dx$，则 $du=\\fracx dx,\\ v=\\frac{x^2}{2}$。故原式 $=\\frac{x^2}{2}\\ln x-\\int \\frac{x}{2}dx=\\frac{x^2}{2}\\ln x-\\frac{x^2}{4}+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909133271045, 195587909133271044, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909196185603, 195587909196185602, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909196185605, 195587909196185604, 1, 'fill-in', '定积分求值', '由定积分定义可得：$\\displaystyle \\int_0^2 (x+1)\\,dx=$ ____。', '[]', '$4$', '', '$\\int_0^2 (x+1)dx=\\left[\\frac{x^2}{2}+x\\right]_0^2=2+2=4$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909196185607, 195587909196185606, 1, 'short-answer', '平面图形面积', '求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。', '[]', '$\\dfrac{1}{6}$', '', '交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\int_0^1 (x-x^2)dx=\\left[\\frac{x^2}{2}-\\frac{x^3}{3}\\right]_0^1=\\frac16$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909259100162, 195587909259100161, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909259100164, 195587909259100163, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909322014723, 195587909322014722, 1, 'fill-in', '定积分求值', '由定积分定义可得：$\\displaystyle \\int_0^2 (x+1)\\,dx=$ ____。', '[]', '$4$', '', '$\\int_0^2 (x+1)dx=\\left[\\frac{x^2}{2}+x\\right]_0^2=2+2=4$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909322014725, 195587909322014724, 1, 'short-answer', '平面图形面积', '求由曲线 $y=x$ 与 $y=x^2$ 围成的平面图形面积。', '[]', '$\\dfrac{1}{6}$', '', '交点满足 $x=x^2$，得 $x=0,1$。面积 $=\\int_0^1 (x-x^2)dx=\\left[\\frac{x^2}{2}-\\frac{x^3}{3}\\right]_0^1=\\frac16$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909322014727, 195587909322014726, 1, 'single-choice', '定积分计算', '计算定积分：$\\displaystyle \\int_0^1 2x\\,dx=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$1$\"}, {\"key\": \"C\", \"content\": \"$2$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac12$\"}]', 'B', 'B', '$\\int_0^1 2x\\,dx=[x^2]_0^1=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909384929283, 195587909384929282, 1, 'multiple-choice', '定积分性质', '下列关于定积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $fx\\\\ge0$，则 $\\\\int_a^b fxdx\\\\ge0$\"}, {\"key\": \"B\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_a^c fxdx+\\\\int_c^b fxdx$\"}, {\"key\": \"C\", \"content\": \"$\\\\int_a^b fxdx=\\\\int_b^a fxdx$\"}, {\"key\": \"D\", \"content\": \"若 $f$ 为奇函数，则 $\\\\int_{-a}^a fxdx=0$\"}, {\"key\": \"E\", \"content\": \"若 $f$ 为偶函数，则 $\\\\int_{-a}^a fxdx=\\\\int_0^a fxdx$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，应为相反数；E 错，应为 $2\\int_0^a fxdx$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909384929285, 195587909384929284, 1, 'fill-in', '全微分计算', '设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。', '[]', '$3dx+3dy$', '', '$z_x=2xy+y^2,\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909447843842, 195587909447843841, 1, 'short-answer', '复合函数偏导', '设 $z=e^{xy}$，求 $\\dfrac{\\partial z}{\\partial x}$ 与 $\\dfrac{\\partial z}{\\partial y}$。', '[]', '$\\dfrac{\\partial z}{\\partial x}=ye^{xy},\\quad \\dfrac{\\partial z}{\\partial y}=xe^{xy}$', '', '对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\cdot y$；同理 $z_y=e^{xy}\\cdot x$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909447843844, 195587909447843843, 1, 'single-choice', '求偏导数', '设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）', '[{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}]', 'A', 'A', '把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909447843846, 195587909447843845, 1, 'multiple-choice', '偏导与全微分性质', '下列关于多元函数求导的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909514952706, 195587909514952705, 1, 'fill-in', '全微分计算', '设 $z=x^2y+xy^2$，则在点 $(1,1)$ 处的全微分为 $dz=$ ____。', '[]', '$3dx+3dy$', '', '$z_x=2xy+y^2,\\ z_y=x^2+2xy$，在 $(1,1)$ 处都等于 $3$，故 $dz=3dx+3dy$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909514952708, 195587909514952707, 1, 'short-answer', '复合函数偏导', '设 $z=e^{xy}$，求 $\\dfrac{\\partial z}{\\partial x}$ 与 $\\dfrac{\\partial z}{\\partial y}$。', '[]', '$\\dfrac{\\partial z}{\\partial x}=ye^{xy},\\quad \\dfrac{\\partial z}{\\partial y}=xe^{xy}$', '', '对 $x$ 求偏导时把 $y$ 当常数，链式法则得 $z_x=e^{xy}\\cdot y$；同理 $z_y=e^{xy}\\cdot x$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909582061570, 195587909582061569, 1, 'single-choice', '求偏导数', '设 $f(x,y)=x^2y+y^3$，则 $f_x=$（  ）', '[{\"key\": \"A\", \"content\": \"$2xy$\"}, {\"key\": \"B\", \"content\": \"$x^2+3y^2$\"}, {\"key\": \"C\", \"content\": \"$2x+y$\"}, {\"key\": \"D\", \"content\": \"$x^2y^2$\"}]', 'A', 'A', '把 $y$ 视为常数，对 $x$ 求偏导得 $f_x=2xy$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909582061572, 195587909582061571, 1, 'multiple-choice', '偏导与全微分性质', '下列关于多元函数求导的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"全微分公式为 $dz=f_xdx+f_ydy$\"}, {\"key\": \"B\", \"content\": \"若 $z=f(x,y)$ 可微，则偏导一定存在\"}, {\"key\": \"C\", \"content\": \"混合偏导 $f_{xy}$ 与 $f_{yx}$ 总是相等，不需要任何条件\"}, {\"key\": \"D\", \"content\": \"方向导数属于偏导数的推广\"}, {\"key\": \"E\", \"content\": \"复合函数求偏导可用链式法则\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，通常需二阶偏导连续等条件。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909582061574, 195587909582061573, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909644976130, 195587909644976129, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909644976132, 195587909644976131, 1, 'single-choice', '二元函数极值', '函数 $f(x,y)=x^2+y^2$ 在 $(0,0)$ 处取得（  ）', '[{\"key\": \"A\", \"content\": \"极大值\"}, {\"key\": \"B\", \"content\": \"极小值\"}, {\"key\": \"C\", \"content\": \"鞍点\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '$x^2+y^2\\ge0$，且仅在 $(0,0)$ 取到 $0$，故为极小值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909644976134, 195587909644976133, 1, 'multiple-choice', '多元极值理论', '下列关于多元函数极值的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"求条件极值常用拉格朗日乘数法\"}, {\"key\": \"B\", \"content\": \"驻点是偏导都为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"Hessian 判别法中 $D=f_{xx}f_{yy}-f_{xy}^2$，若 $D>0$ 且 $f_{xx}>0$，则为极小值\"}, {\"key\": \"D\", \"content\": \"条件极值与无条件极值的驻点条件完全相同\"}, {\"key\": \"E\", \"content\": \"鞍点既不是极大值点，也不是极小值点\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，条件极值还要结合约束方程。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909644976136, 195587909644976135, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909712084994, 195587909712084993, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909712084996, 195587909712084995, 1, 'single-choice', '二元函数极值', '函数 $f(x,y)=x^2+y^2$ 在 $(0,0)$ 处取得（  ）', '[{\"key\": \"A\", \"content\": \"极大值\"}, {\"key\": \"B\", \"content\": \"极小值\"}, {\"key\": \"C\", \"content\": \"鞍点\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '$x^2+y^2\\ge0$，且仅在 $(0,0)$ 取到 $0$，故为极小值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909779193858, 195587909779193857, 1, 'multiple-choice', '多元极值理论', '下列关于多元函数极值的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"求条件极值常用拉格朗日乘数法\"}, {\"key\": \"B\", \"content\": \"驻点是偏导都为 $0$ 的点\"}, {\"key\": \"C\", \"content\": \"Hessian 判别法中 $D=f_{xx}f_{yy}-f_{xy}^2$，若 $D>0$ 且 $f_{xx}>0$，则为极小值\"}, {\"key\": \"D\", \"content\": \"条件极值与无条件极值的驻点条件完全相同\"}, {\"key\": \"E\", \"content\": \"鞍点既不是极大值点，也不是极小值点\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，条件极值还要结合约束方程。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909779193860, 195587909779193859, 1, 'fill-in', '极小值计算', '求函数 $f(x,y)=x^2+y^2-2x-4y$ 的极小值：____。', '[]', '$-5$', '', '配方得 $f=(x-1)^2+(y-2)^2-5$，故最小值为 $-5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909779193862, 195587909779193861, 1, 'short-answer', '拉格朗日乘数法', '用拉格朗日乘数法求函数 $f(x,y)=xy$ 在约束 $x+y=2$ 下的极值。', '[]', '在 $x=y=1$ 处取得最大值 $1$；无最小值（若限制为实数且只满足直线约束，则 $xy$ 可趋于 $-\\infty$）。', '', '设 $L=xy+\\lambda(x+y-2)$。由 $L_x=y+\\lambda=0,\\ L_y=x+\\lambda=0$ 得 $x=y$，再由约束得 $x=y=1$。此时 $xy=1$。沿直线 $y=2-x$，有 $f=x(2-x)=1-(x-1)^2$，最大值为 $1$，无最小值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909842108418, 195587909842108417, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909842108420, 195587909842108419, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909842108422, 195587909842108421, 1, 'fill-in', '区域面积', '填空：$\\displaystyle \\iint_{x^2+y^2\\le 1}1\\,dA=$ ____。', '[]', '$\\pi$', '', '被积函数为 $1$，积分等于单位圆面积，所以为 $\\pi$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909842108424, 195587909842108423, 1, 'short-answer', '极坐标二重积分', '用极坐标计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 4}(x^2+y^2)\\,dA$。', '[]', '$8\\pi$', '', '极坐标下 $x^2+y^2=r^2,\\ dA=rdrd\\theta$。原式 $=\\int_0^{2\\pi}\\int_0^2 r^3drd\\theta=2\\pi\\cdot\\left[\\frac{r^4}{4}\\right]_0^2=8\\pi$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909905022978, 195587909905022977, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909905022980, 195587909905022979, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909905022982, 195587909905022981, 1, 'fill-in', '区域面积', '填空：$\\displaystyle \\iint_{x^2+y^2\\le 1}1\\,dA=$ ____。', '[]', '$\\pi$', '', '被积函数为 $1$，积分等于单位圆面积，所以为 $\\pi$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909905022984, 195587909905022983, 1, 'short-answer', '极坐标二重积分', '用极坐标计算二重积分：$\\displaystyle \\iint_{x^2+y^2\\le 4}(x^2+y^2)\\,dA$。', '[]', '$8\\pi$', '', '极坐标下 $x^2+y^2=r^2,\\ dA=rdrd\\theta$。原式 $=\\int_0^{2\\pi}\\int_0^2 r^3drd\\theta=2\\pi\\cdot\\left[\\frac{r^4}{4}\\right]_0^2=8\\pi$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909972131843, 195587909972131842, 1, 'single-choice', '矩形区域二重积分', '计算二重积分：$\\displaystyle \\iint_{[0,1]\\times[0,1]}(x+y)\\,dA=$（  ）', '[{\"key\": \"A\", \"content\": \"$1$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$\\\\frac12$\"}, {\"key\": \"D\", \"content\": \"$\\\\frac32$\"}]', 'A', 'A', '$\\int_0^1\\int_0^1 (x+y)dxdy=\\int_0^1(\\frac12+y)dy=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909972131845, 195587909972131844, 1, 'multiple-choice', '二重积分性质', '下列关于二重积分的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二重积分可看作对区域上函数值的累加\"}, {\"key\": \"B\", \"content\": \"在极坐标下 $dA=rdrd\\\\theta$\"}, {\"key\": \"C\", \"content\": \"交换积分次序时被积函数必须改变\"}, {\"key\": \"D\", \"content\": \"若被积函数恒为 $1$，则二重积分等于区域面积\"}, {\"key\": \"E\", \"content\": \"对称区域上奇函数的二重积分一定为 $0$\"}]', 'ABD', 'ABD', 'A、B、D 正确；C 错，主要变化的是积分限；E 不一定，要看关于哪种对称及函数奇性。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587909972131847, 195587909972131846, 1, 'fill-in', '初值问题', '求初值问题 $y\'=3x^2,\\ y(0)=1$ 的解：$y=$ ____。', '[]', '$x^3+1$', '', '积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910035046403, 195587910035046402, 1, 'short-answer', '二阶常系数方程', '求解微分方程：$y\'\'-3y\'+2y=0$。', '[]', '$y=C_1e^x+C_2e^{2x}$', '', '特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910035046405, 195587910035046404, 1, 'single-choice', '通解求法', '微分方程 $y\'=2x$ 的通解为（  ）', '[{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}]', 'A', 'A', '两边积分得 $y=\\int 2x\\,dx=x^2+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910035046407, 195587910035046406, 1, 'multiple-choice', '微分方程基础', '下列关于常微分方程的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910106349570, 195587910106349569, 1, 'fill-in', '初值问题', '求初值问题 $y\'=3x^2,\\ y(0)=1$ 的解：$y=$ ____。', '[]', '$x^3+1$', '', '积分得 $y=x^3+C$，代入 $y(0)=1$ 得 $C=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910160875523, 195587910160875522, 1, 'short-answer', '二阶常系数方程', '求解微分方程：$y\'\'-3y\'+2y=0$。', '[]', '$y=C_1e^x+C_2e^{2x}$', '', '特征方程 $r^2-3r+2=0$，解得 $r=1,2$，故通解为 $y=C_1e^x+C_2e^{2x}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910160875525, 195587910160875524, 1, 'single-choice', '通解求法', '微分方程 $y\'=2x$ 的通解为（  ）', '[{\"key\": \"A\", \"content\": \"$y=x^2+C$\"}, {\"key\": \"B\", \"content\": \"$y=2x+C$\"}, {\"key\": \"C\", \"content\": \"$y=x+C$\"}, {\"key\": \"D\", \"content\": \"$y=x^2$\"}]', 'A', 'A', '两边积分得 $y=\\int 2x\\,dx=x^2+C$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910290898947, 195587910290898946, 1, 'multiple-choice', '微分方程基础', '下列关于常微分方程的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"可分离变量方程可写成 $g(y)dy=fxdx$ 的形式\"}, {\"key\": \"B\", \"content\": \"一阶线性方程标准形为 $y\'+Pxy=Qx$\"}, {\"key\": \"C\", \"content\": \"二阶常系数齐次方程的解只与特征方程有关\"}, {\"key\": \"D\", \"content\": \"所有微分方程都能求出初等函数形式通解\"}, {\"key\": \"E\", \"content\": \"满足初值条件的特解一般通过确定积分常数得到\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，很多方程无法写成初等函数通解。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910290898949, 195587910290898948, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910290898951, 195587910290898950, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910362202114, 195587910362202113, 1, 'single-choice', '级数敛散性', '级数 $\\displaystyle \\sum_{n=1}^{\\infty}\\frac{1}{n^2}$ 的敛散性为（  ）', '[{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'C', 'C', '这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910362202116, 195587910362202115, 1, 'multiple-choice', '级数基本结论', '下列关于无穷级数的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，交错调和级数只是条件收敛。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910425116673, 195587910425116672, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910425116675, 195587910425116674, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910425116677, 195587910425116676, 1, 'single-choice', '级数敛散性', '级数 $\\displaystyle \\sum_{n=1}^{\\infty}\\frac{1}{n^2}$ 的敛散性为（  ）', '[{\"key\": \"A\", \"content\": \"发散\"}, {\"key\": \"B\", \"content\": \"条件收敛\"}, {\"key\": \"C\", \"content\": \"绝对收敛\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'C', 'C', '这是 $p=2>1$ 的正项 $p$ 级数，收敛，且为绝对收敛。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910488031234, 195587910488031233, 1, 'multiple-choice', '级数基本结论', '下列关于无穷级数的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$\\\\sum \\\\frac1n$ 发散\"}, {\"key\": \"B\", \"content\": \"$\\\\sum \\\\frac1{n^2}$ 收敛\"}, {\"key\": \"C\", \"content\": \"$\\\\sum (-1)^{n-1}\\\\frac1n$ 绝对收敛\"}, {\"key\": \"D\", \"content\": \"幂级数的收敛区间一定关于展开点对称\"}, {\"key\": \"E\", \"content\": \"几何级数 $\\\\sum q^n$ 在 $|q|<1$ 时收敛\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，交错调和级数只是条件收敛。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910488031236, 195587910488031235, 1, 'fill-in', '几何级数求和', '填空：$\\displaystyle \\sum_{n=0}^{\\infty}x^n$ 在 $|x|<1$ 时的和为 ____。', '[]', '$\\dfrac{1}{1-x}$', '', '这是公比为 $x$ 的几何级数，和公式为 $\\frac{1}{1-x}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910488031238, 195587910488031237, 1, 'short-answer', '幂级数展开', '写出函数 $\\ln(1+x)$ 在 $x=0$ 附近的幂级数展开，并指出收敛区间。', '[]', '$\\ln(1+x)=x-\\dfrac{x^2}{2}+\\dfrac{x^3}{3}-\\cdots=\\sum_{n=1}^{\\infty}(-1)^{n-1}\\dfrac{x^n}{n}$，收敛区间为 $(-1,1]$。', '', '这是常见麦克劳林展开。端点 $x=1$ 时为交错调和级数收敛，$x=-1$ 时为 $-\\sum \\frac1n$ 发散。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910555140099, 195587910555140098, 1, 'single-choice', '二阶行列式', '计算行列式 $\\begin{vmatrix}1&2\\\\3&4\\end{vmatrix}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}]', 'A', 'A', '$1\\cdot4-2\\cdot3=-2$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910555140101, 195587910555140100, 1, 'multiple-choice', '行列式性质', '下列关于行列式的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}]', 'ABE', 'ABE', 'A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910555140103, 195587910555140102, 1, 'fill-in', '三角行列式', '填空：$\\begin{vmatrix}2&0&0\\\\1&3&0\\\\4&5&6\\end{vmatrix}=$ ____。', '[]', '$36$', '', '下三角行列式等于主对角线元素之积，故为 $2\\cdot3\\cdot6=36$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910555140105, 195587910555140104, 1, 'short-answer', '三阶行列式计算', '计算行列式：$\\begin{vmatrix}1&1&1\\\\1&2&3\\\\1&3&6\\end{vmatrix}$。', '[]', '$1$', '', '可作行变换：$R_2\\leftarrow R_2-R_1,\\ R_3\\leftarrow R_3-R_1$，得 $\\begin{vmatrix}1&1&1\\\\0&1&2\\\\0&2&5\\end{vmatrix}$，再按第一列展开得 $\\begin{vmatrix}1&2\\\\2&5\\end{vmatrix}=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910622248962, 195587910622248961, 1, 'single-choice', '二阶行列式', '计算行列式 $\\begin{vmatrix}1&2\\\\3&4\\end{vmatrix}=$（  ）', '[{\"key\": \"A\", \"content\": \"$-2$\"}, {\"key\": \"B\", \"content\": \"$2$\"}, {\"key\": \"C\", \"content\": \"$10$\"}, {\"key\": \"D\", \"content\": \"$-10$\"}]', 'A', 'A', '$1\\cdot4-2\\cdot3=-2$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910622248964, 195587910622248963, 1, 'multiple-choice', '行列式性质', '下列关于行列式的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"交换行列式的两行，行列式变号\"}, {\"key\": \"B\", \"content\": \"某一行乘以 $k$，行列式也乘以 $k$\"}, {\"key\": \"C\", \"content\": \"若两行成比例，则行列式非零\"}, {\"key\": \"D\", \"content\": \"上三角行列式等于主对角线元素之和\"}, {\"key\": \"E\", \"content\": \"按任意一行展开都可以求行列式\"}]', 'ABE', 'ABE', 'A、B、E 正确；C 错，两行成比例则为 0；D 错，应为主对角线元素之积。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910622248966, 195587910622248965, 1, 'fill-in', '三角行列式', '填空：$\\begin{vmatrix}2&0&0\\\\1&3&0\\\\4&5&6\\end{vmatrix}=$ ____。', '[]', '$36$', '', '下三角行列式等于主对角线元素之积，故为 $2\\cdot3\\cdot6=36$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910622248968, 195587910622248967, 1, 'short-answer', '三阶行列式计算', '计算行列式：$\\begin{vmatrix}1&1&1\\\\1&2&3\\\\1&3&6\\end{vmatrix}$。', '[]', '$1$', '', '可作行变换：$R_2\\leftarrow R_2-R_1,\\ R_3\\leftarrow R_3-R_1$，得 $\\begin{vmatrix}1&1&1\\\\0&1&2\\\\0&2&5\\end{vmatrix}$，再按第一列展开得 $\\begin{vmatrix}1&2\\\\2&5\\end{vmatrix}=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910685163521, 195587910685163520, 1, 'single-choice', '矩阵乘法', '设 $A=\\begin{pmatrix}1&2\\\\0&1\\end{pmatrix},\\ B=\\begin{pmatrix}2&0\\\\1&3\\end{pmatrix}$，则 $AB=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}]', 'A', 'A', '按矩阵乘法计算：$AB=\\begin{pmatrix}1\\cdot2+2\\cdot1 & 1\\cdot0+2\\cdot3\\\\ 0\\cdot2+1\\cdot1 & 0\\cdot0+1\\cdot3\\end{pmatrix}=\\begin{pmatrix}4&6\\\\1&3\\end{pmatrix}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910685163523, 195587910685163522, 1, 'multiple-choice', '矩阵与逆矩阵性质', '下列关于矩阵运算的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}]', 'ABC', 'ABC', 'A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910685163525, 195587910685163524, 1, 'fill-in', '逆矩阵', '设 $A=\\begin{pmatrix}1&0\\\\0&2\\end{pmatrix}$，则 $A^{-1}=$ ____。', '[]', '$\\begin{pmatrix}1&0\\\\0&\\frac12\\end{pmatrix}$', '', '对角矩阵求逆就是对角元分别取倒数。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910748078082, 195587910748078081, 1, 'short-answer', '二阶矩阵求逆', '求矩阵 $A=\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}$ 的逆矩阵。', '[]', '$A^{-1}=\\begin{pmatrix}-2&1\\\\ \\frac32&-\\frac12\\end{pmatrix}$', '', '二阶矩阵逆公式：$A^{-1}=\\frac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910748078084, 195587910748078083, 1, 'single-choice', '矩阵乘法', '设 $A=\\begin{pmatrix}1&2\\\\0&1\\end{pmatrix},\\ B=\\begin{pmatrix}2&0\\\\1&3\\end{pmatrix}$，则 $AB=$（  ）', '[{\"key\": \"A\", \"content\": \"$\\\\begin{pmatrix}4&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"B\", \"content\": \"$\\\\begin{pmatrix}2&6\\\\\\\\1&3\\\\end{pmatrix}$\"}, {\"key\": \"C\", \"content\": \"$\\\\begin{pmatrix}3&2\\\\\\\\1&4\\\\end{pmatrix}$\"}, {\"key\": \"D\", \"content\": \"$\\\\begin{pmatrix}2&0\\\\\\\\1&3\\\\end{pmatrix}$\"}]', 'A', 'A', '按矩阵乘法计算：$AB=\\begin{pmatrix}1\\cdot2+2\\cdot1 & 1\\cdot0+2\\cdot3\\\\ 0\\cdot2+1\\cdot1 & 0\\cdot0+1\\cdot3\\end{pmatrix}=\\begin{pmatrix}4&6\\\\1&3\\end{pmatrix}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910748078086, 195587910748078085, 1, 'multiple-choice', '矩阵与逆矩阵性质', '下列关于矩阵运算的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"一般而言 $AB\\\\ne BA$\"}, {\"key\": \"B\", \"content\": \"若 $A$ 可逆，则 $AA^{-1}=E$\"}, {\"key\": \"C\", \"content\": \"矩阵可逆当且仅当其行列式不为 0\"}, {\"key\": \"D\", \"content\": \"只有对角矩阵才可逆\"}, {\"key\": \"E\", \"content\": \"$(AB)^{-1}=A^{-1}B^{-1}$\"}]', 'ABC', 'ABC', 'A、B、C 正确；D 错，很多非对角矩阵也可逆；E 错，应为 $(AB)^{-1}=B^{-1}A^{-1}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910748078088, 195587910748078087, 1, 'fill-in', '逆矩阵', '设 $A=\\begin{pmatrix}1&0\\\\0&2\\end{pmatrix}$，则 $A^{-1}=$ ____。', '[]', '$\\begin{pmatrix}1&0\\\\0&\\frac12\\end{pmatrix}$', '', '对角矩阵求逆就是对角元分别取倒数。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910815186947, 195587910815186946, 1, 'short-answer', '二阶矩阵求逆', '求矩阵 $A=\\begin{pmatrix}1&2\\\\3&4\\end{pmatrix}$ 的逆矩阵。', '[]', '$A^{-1}=\\begin{pmatrix}-2&1\\\\ \\frac32&-\\frac12\\end{pmatrix}$', '', '二阶矩阵逆公式：$A^{-1}=\\frac{1}{ad-bc}\\begin{pmatrix}d&-b\\\\-c&a\\end{pmatrix}$。这里 $ad-bc=-2$，代入可得结果。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910815186949, 195587910815186948, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910878101507, 195587910878101506, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910878101509, 195587910878101508, 1, 'fill-in', '矩阵秩', '矩阵 $A=\\begin{pmatrix}1&2\\\\2&4\\end{pmatrix}$ 的秩为 ____。', '[]', '$1$', '', '第二行是第一行的 2 倍，因此只有一行线性无关，秩为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910945210371, 195587910945210370, 1, 'short-answer', '向量组线性无关', '判断向量组 $\\alpha_1=(1,1,0),\\ \\alpha_2=(1,0,1),\\ \\alpha_3=(0,1,1)$ 是否线性无关。', '[]', '线性无关。', '', '以这三个向量为列组成矩阵 $A=\\begin{pmatrix}1&1&0\\\\1&0&1\\\\0&1&1\\end{pmatrix}$，其行列式为 $-2\\ne0$，故三向量线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587910945210373, 195587910945210372, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911008124930, 195587911008124929, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911008124932, 195587911008124931, 1, 'fill-in', '矩阵秩', '矩阵 $A=\\begin{pmatrix}1&2\\\\2&4\\end{pmatrix}$ 的秩为 ____。', '[]', '$1$', '', '第二行是第一行的 2 倍，因此只有一行线性无关，秩为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911075233795, 195587911075233794, 1, 'short-answer', '向量组线性无关', '判断向量组 $\\alpha_1=(1,1,0),\\ \\alpha_2=(1,0,1),\\ \\alpha_3=(0,1,1)$ 是否线性无关。', '[]', '线性无关。', '', '以这三个向量为列组成矩阵 $A=\\begin{pmatrix}1&1&0\\\\1&0&1\\\\0&1&1\\end{pmatrix}$，其行列式为 $-2\\ne0$，故三向量线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911142342659, 195587911142342658, 1, 'single-choice', '线性相关判断', '向量组 $\\alpha_1=(1,0),\\ \\alpha_2=(0,1)$ 在 $\\mathbb{R}^2$ 中（  ）', '[{\"key\": \"A\", \"content\": \"线性相关\"}, {\"key\": \"B\", \"content\": \"线性无关\"}, {\"key\": \"C\", \"content\": \"秩为 1\"}, {\"key\": \"D\", \"content\": \"无法判断\"}]', 'B', 'B', '这两个向量是标准基，互不成比例，线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911142342661, 195587911142342660, 1, 'multiple-choice', '线性相关与秩', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"向量组线性相关时，至少有一个向量可由其余向量线性表示\"}, {\"key\": \"B\", \"content\": \"矩阵的秩等于其最大非零子式的阶数\"}, {\"key\": \"C\", \"content\": \"若 $n$ 维向量组含有多于 $n$ 个向量，则一定线性相关\"}, {\"key\": \"D\", \"content\": \"任意两个不平行的二维向量线性相关\"}, {\"key\": \"E\", \"content\": \"满秩方阵一定可逆\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，不平行反而线性无关。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911209451523, 195587911209451522, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911209451525, 195587911209451524, 1, 'short-answer', '基础解系', '求齐次线性方程组 $\\begin{cases}x+y+z=0\\\\x-y+z=0\\end{cases}$ 的基础解系。', '[]', '基础解系可取 $\\{(-1,0,1)^T\\}$。', '', '由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\{(-1,0,1)^T\\}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911209451527, 195587911209451526, 1, 'single-choice', '齐次方程组', '齐次线性方程组 $Ax=0$ 一定有（  ）', '[{\"key\": \"A\", \"content\": \"无解\"}, {\"key\": \"B\", \"content\": \"唯一解\"}, {\"key\": \"C\", \"content\": \"零解\"}, {\"key\": \"D\", \"content\": \"无穷多解\"}]', 'C', 'C', '齐次线性方程组至少有零解。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911276560385, 195587911276560384, 1, 'multiple-choice', '线性方程组理论', '下列关于线性方程组的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"齐次线性方程组一定有解\"}, {\"key\": \"B\", \"content\": \"非齐次线性方程组可能无解\"}, {\"key\": \"C\", \"content\": \"若系数矩阵满秩，则齐次方程组只有零解\"}, {\"key\": \"D\", \"content\": \"基础解系中的向量一定线性无关\"}, {\"key\": \"E\", \"content\": \"非齐次方程组有解时，其通解等于对应齐次方程组通解\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，非齐次通解=一个特解+对应齐次通解。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911276560387, 195587911276560386, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911339474946, 195587911339474945, 1, 'short-answer', '基础解系', '求齐次线性方程组 $\\begin{cases}x+y+z=0\\\\x-y+z=0\\end{cases}$ 的基础解系。', '[]', '基础解系可取 $\\{(-1,0,1)^T\\}$。', '', '由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\{(-1,0,1)^T\\}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
