INSERT INTO `question_version` VALUES (195587911339474950, 195587911339474949, 1, 'multiple-choice', '线性方程组理论', '下列关于线性方程组的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"齐次线性方程组一定有解\"}, {\"key\": \"B\", \"content\": \"非齐次线性方程组可能无解\"}, {\"key\": \"C\", \"content\": \"若系数矩阵满秩，则齐次方程组只有零解\"}, {\"key\": \"D\", \"content\": \"基础解系中的向量一定线性无关\"}, {\"key\": \"E\", \"content\": \"非齐次方程组有解时，其通解等于对应齐次方程组通解\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，非齐次通解=一个特解+对应齐次通解。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911410778114, 195587911410778113, 1, 'fill-in', '二元线性方程组', '线性方程组 $\\begin{cases}x+y=2\\\\x-y=0\\end{cases}$ 的解为 $(x,y)=$ ____。', '[]', '$(1,1)$', '', '两式相加得 $2x=2$，所以 $x=1$，再得 $y=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911410778116, 195587911410778115, 1, 'short-answer', '基础解系', '求齐次线性方程组 $\\begin{cases}x+y+z=0\\\\x-y+z=0\\end{cases}$ 的基础解系。', '[]', '基础解系可取 $\\{(-1,0,1)^T\\}$。', '', '由两式相减得 $2y=0$，所以 $y=0$。再由第一式得 $x+z=0$，令 $z=t$，则 $(x,y,z)=t(-1,0,1)$。故基础解系可取 $\\{(-1,0,1)^T\\}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911410778118, 195587911410778117, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911410778120, 195587911410778119, 1, 'multiple-choice', '特征值与对角化性质', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911473692673, 195587911473692672, 1, 'fill-in', '单位矩阵特征值', '矩阵 $A=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$ 的唯一特征值为 ____。', '[]', '$1$', '', '单位矩阵满足 $Ax=x$，故唯一特征值为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911473692675, 195587911473692674, 1, 'short-answer', '特征向量求解', '求矩阵 $A=\\begin{pmatrix}2&1\\\\0&2\\end{pmatrix}$ 的特征值与特征向量。', '[]', '特征值只有 $\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\begin{pmatrix}1\\\\0\\end{pmatrix}$ 的任意非零倍。', '', '特征多项式为 $(2-\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\begin{pmatrix}0&1\\\\0&0\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911473692677, 195587911473692676, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911473692679, 195587911473692678, 1, 'multiple-choice', '特征值与对角化性质', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911540801539, 195587911540801538, 1, 'fill-in', '单位矩阵特征值', '矩阵 $A=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$ 的唯一特征值为 ____。', '[]', '$1$', '', '单位矩阵满足 $Ax=x$，故唯一特征值为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911540801541, 195587911540801540, 1, 'short-answer', '特征向量求解', '求矩阵 $A=\\begin{pmatrix}2&1\\\\0&2\\end{pmatrix}$ 的特征值与特征向量。', '[]', '特征值只有 $\\lambda=2$；对应特征向量满足 $(A-2E)x=0$，可取 $\\begin{pmatrix}1\\\\0\\end{pmatrix}$ 的任意非零倍。', '', '特征多项式为 $(2-\\lambda)^2$，故特征值为 2。解 $(A-2E)x=\\begin{pmatrix}0&1\\\\0&0\\end{pmatrix}x=0$，得 $x_2=0$，$x_1$ 任意非零。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911540801543, 195587911540801542, 1, 'single-choice', '特征值', '矩阵 $A=\\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}$ 的特征值为（  ）', '[{\"key\": \"A\", \"content\": \"$2,3$\"}, {\"key\": \"B\", \"content\": \"$1,5$\"}, {\"key\": \"C\", \"content\": \"$6$\"}, {\"key\": \"D\", \"content\": \"$-2,-3$\"}]', 'A', 'A', '对角矩阵的特征值就是主对角线元素。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911540801545, 195587911540801544, 1, 'multiple-choice', '特征值与对角化性质', '下列说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"不同特征值对应的特征向量线性无关\"}, {\"key\": \"B\", \"content\": \"可对角化矩阵一定有足够多线性无关特征向量\"}, {\"key\": \"C\", \"content\": \"任意方阵都能相似对角化\"}, {\"key\": \"D\", \"content\": \"矩阵的迹等于全部特征值之和\"}, {\"key\": \"E\", \"content\": \"矩阵的行列式等于全部特征值之积\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，缺少足够特征向量时不能对角化。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911603716098, 195587911603716097, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911603716100, 195587911603716099, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911603716102, 195587911603716101, 1, 'single-choice', '事件并概率', '设 $P(A)=0.4,\\ P(B)=0.5,\\ P(A\\cap B)=0.2$，则 $P(A\\cup B)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}]', 'A', 'A', '用加法公式：$P(A\\cup B)=P(A)+P(B)-P(A\\cap B)=0.7$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911603716104, 195587911603716103, 1, 'multiple-choice', '概率基础公式', '下列关于概率论基础的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，互斥且概率都非零时不独立。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911603716106, 195587911603716105, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911670824963, 195587911670824962, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911670824965, 195587911670824964, 1, 'single-choice', '事件并概率', '设 $P(A)=0.4,\\ P(B)=0.5,\\ P(A\\cap B)=0.2$，则 $P(A\\cup B)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.7$\"}, {\"key\": \"B\", \"content\": \"$0.9$\"}, {\"key\": \"C\", \"content\": \"$0.2$\"}, {\"key\": \"D\", \"content\": \"$0.1$\"}]', 'A', 'A', '用加法公式：$P(A\\cup B)=P(A)+P(B)-P(A\\cap B)=0.7$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911670824967, 195587911670824966, 1, 'multiple-choice', '概率基础公式', '下列关于概率论基础的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"若 $A,B$ 独立，则 $P(A\\\\cap B)=P(A)P(B)$\"}, {\"key\": \"B\", \"content\": \"条件概率公式为 $P(A|B)=\\\\dfrac{P(A\\\\cap B)}{P(B)}\\\\ (P(B)>0)$\"}, {\"key\": \"C\", \"content\": \"互斥事件一定独立\"}, {\"key\": \"D\", \"content\": \"全概率公式适用于样本空间的一个完备事件组\"}, {\"key\": \"E\", \"content\": \"贝叶斯公式用于已知结果反推原因概率\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，互斥且概率都非零时不独立。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911670824969, 195587911670824968, 1, 'fill-in', '古典概型', '袋中有 3 个红球、2 个白球，任取 1 球，取到红球的概率为 ____。', '[]', '$\\dfrac{3}{5}$', '', '古典概型，红球数比总球数：$\\frac35$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911733739522, 195587911733739521, 1, 'short-answer', '全概率公式', '设事件 $A,B$ 满足 $P(B)=0.6,\\ P(A|B)=0.5,\\ P(A|\\bar B)=0.2$，求 $P(A)$。', '[]', '$0.38$', '', '由全概率公式：$P(A)=P(A|B)P(B)+P(A|\\bar B)P(\\bar B)=0.5\\times0.6+0.2\\times0.4=0.38$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911733739524, 195587911733739523, 1, 'single-choice', '分布列计算', '设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\le1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}]', 'C', 'C', '$P(X\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911733739526, 195587911733739525, 1, 'multiple-choice', '分布函数与密度', '下列关于随机变量分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911733739528, 195587911733739527, 1, 'fill-in', '密度函数求概率', '设连续型随机变量 $X$ 的密度 $fx=\\begin{cases}2x,&0<x<1\\\\0,&\\text{其他}\\end{cases}$，则 $P(X<\\tfrac12)=$ ____。', '[]', '$\\dfrac{1}{4}$', '', '$P(X<\\frac12)=\\int_0^{1/2}2x\\,dx=\\left[x^2\\right]_0^{1/2}=\\frac14$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911733739530, 195587911733739529, 1, 'short-answer', '分布函数求概率', '设随机变量 $X$ 的分布函数为 $Fx=\\begin{cases}0,&x<0\\\\x^2,&0\\le x<1\\\\1,&x\\ge1\\end{cases}$。求 $P(\\tfrac12<X\\le1)$。', '[]', '$\\dfrac{3}{4}$', '', '$P(\\frac12<X\\le1)=F(1)-F(\\frac12)=1-\\frac14=\\frac34$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911796654082, 195587911796654081, 1, 'single-choice', '分布列计算', '设离散型随机变量 $X$ 取值 $0,1,2$，概率分别为 $0.2,0.5,0.3$，则 $P(X\\le1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.2$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.7$\"}, {\"key\": \"D\", \"content\": \"$0.8$\"}]', 'C', 'C', '$P(X\\le1)=P(X=0)+P(X=1)=0.2+0.5=0.7$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911796654084, 195587911796654083, 1, 'multiple-choice', '分布函数与密度', '下列关于随机变量分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"分布函数 $Fx=P(X\\\\le x)$\"}, {\"key\": \"B\", \"content\": \"连续型随机变量在单点处概率为 0\"}, {\"key\": \"C\", \"content\": \"概率密度函数一定处处小于等于 1\"}, {\"key\": \"D\", \"content\": \"离散型随机变量可以用分布列描述\"}, {\"key\": \"E\", \"content\": \"分布函数单调不减\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，密度可以大于 1，只要积分为 1。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911796654086, 195587911796654085, 1, 'fill-in', '密度函数求概率', '设连续型随机变量 $X$ 的密度 $fx=\\begin{cases}2x,&0<x<1\\\\0,&\\text{其他}\\end{cases}$，则 $P(X<\\tfrac12)=$ ____。', '[]', '$\\dfrac{1}{4}$', '', '$P(X<\\frac12)=\\int_0^{1/2}2x\\,dx=\\left[x^2\\right]_0^{1/2}=\\frac14$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911796654088, 195587911796654087, 1, 'short-answer', '分布函数求概率', '设随机变量 $X$ 的分布函数为 $Fx=\\begin{cases}0,&x<0\\\\x^2,&0\\le x<1\\\\1,&x\\ge1\\end{cases}$。求 $P(\\tfrac12<X\\le1)$。', '[]', '$\\dfrac{3}{4}$', '', '$P(\\frac12<X\\le1)=F(1)-F(\\frac12)=1-\\frac14=\\frac34$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911863762945, 195587911863762944, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911863762947, 195587911863762946, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911863762949, 195587911863762948, 1, 'fill-in', '泊松分布', '设 $X\\sim Poisson(\\lambda=2)$，则 $P(X=0)=$ ____。', '[]', '$e^{-2}$', '', '泊松分布概率公式：$P(X=k)=e^{-\\lambda}\\frac{\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911863762951, 195587911863762950, 1, 'short-answer', '正态分布对称性', '设 $X\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。', '[]', '$P(X>0)=\\dfrac12$', '', '标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\frac12$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911926677507, 195587911926677506, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911926677509, 195587911926677508, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911926677511, 195587911926677510, 1, 'fill-in', '泊松分布', '设 $X\\sim Poisson(\\lambda=2)$，则 $P(X=0)=$ ____。', '[]', '$e^{-2}$', '', '泊松分布概率公式：$P(X=k)=e^{-\\lambda}\\frac{\\lambda^k}{k!}$，取 $k=0$ 得 $e^{-2}$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911926677513, 195587911926677512, 1, 'short-answer', '正态分布对称性', '设 $X\\sim N(0,1)$，利用标准正态分布的对称性说明 $P(X>0)$。', '[]', '$P(X>0)=\\dfrac12$', '', '标准正态分布关于 0 对称，且总概率为 1，因此左右两侧各占一半，所以 $P(X>0)=\\frac12$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911993786371, 195587911993786370, 1, 'single-choice', '二项分布', '若 $X\\sim B(2,0.5)$，则 $P(X=1)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0.25$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$0.75$\"}, {\"key\": \"D\", \"content\": \"$1$\"}]', 'B', 'B', '$P(X=1)=\\binom21(0.5)^1(0.5)^1=0.5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911993786373, 195587911993786372, 1, 'multiple-choice', '常见分布性质', '下列关于常见分布的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"二项分布描述固定次数独立重复试验成功次数\"}, {\"key\": \"B\", \"content\": \"泊松分布常用于稀有事件计数\"}, {\"key\": \"C\", \"content\": \"正态分布关于均值对称\"}, {\"key\": \"D\", \"content\": \"指数分布具有无记忆性\"}, {\"key\": \"E\", \"content\": \"均匀分布一定是离散分布\"}]', 'ABCD', 'ABCD', 'A、B、C、D 正确；E 错，常见连续均匀分布不是离散分布。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587911993786375, 195587911993786374, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912060895233, 195587912060895232, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912060895235, 195587912060895234, 1, 'single-choice', '数学期望', '设随机变量 $X$ 的分布列为 $P(X=0)=0.5,\\ P(X=1)=0.5$，则 $E(X)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$1$\"}, {\"key\": \"D\", \"content\": \"$2$\"}]', 'B', 'B', '$E(X)=0\\times0.5+1\\times0.5=0.5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912060895237, 195587912060895236, 1, 'multiple-choice', '数字特征性质', '下列关于期望、方差与协方差的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$E(aX+b)=aE(X)+b$\"}, {\"key\": \"B\", \"content\": \"$Var(X)=E(X^2)-[E(X)]^2$\"}, {\"key\": \"C\", \"content\": \"若 $X,Y$ 独立，则 $Cov(X,Y)=0$\"}, {\"key\": \"D\", \"content\": \"$Var(aX)=aVar(X)$\"}, {\"key\": \"E\", \"content\": \"方差衡量随机变量偏离均值的程度\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，应为 $Var(aX)=a^2Var(X)$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912060895239, 195587912060895238, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912128004098, 195587912128004097, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912128004100, 195587912128004099, 1, 'single-choice', '数学期望', '设随机变量 $X$ 的分布列为 $P(X=0)=0.5,\\ P(X=1)=0.5$，则 $E(X)=$（  ）', '[{\"key\": \"A\", \"content\": \"$0$\"}, {\"key\": \"B\", \"content\": \"$0.5$\"}, {\"key\": \"C\", \"content\": \"$1$\"}, {\"key\": \"D\", \"content\": \"$2$\"}]', 'B', 'B', '$E(X)=0\\times0.5+1\\times0.5=0.5$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912128004102, 195587912128004101, 1, 'multiple-choice', '数字特征性质', '下列关于期望、方差与协方差的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"$E(aX+b)=aE(X)+b$\"}, {\"key\": \"B\", \"content\": \"$Var(X)=E(X^2)-[E(X)]^2$\"}, {\"key\": \"C\", \"content\": \"若 $X,Y$ 独立，则 $Cov(X,Y)=0$\"}, {\"key\": \"D\", \"content\": \"$Var(aX)=aVar(X)$\"}, {\"key\": \"E\", \"content\": \"方差衡量随机变量偏离均值的程度\"}]', 'ABCE', 'ABCE', 'A、B、C、E 正确；D 错，应为 $Var(aX)=a^2Var(X)$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912128004104, 195587912128004103, 1, 'fill-in', '方差计算', '设 $X$ 只取 $-1,1$，且各以概率 $0.5$ 取到，则 $Var(X)=$ ____。', '[]', '$1$', '', '$E(X)=0$，$E(X^2)=1$，所以 $Var(X)=1-0=1$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912190918658, 195587912190918657, 1, 'short-answer', '期望与方差综合', '设 $X$ 的分布列为 $P(X=1)=0.3,\\ P(X=2)=0.7$，求 $E(X)$ 与 $Var(X)$。', '[]', '$E(X)=1.7,\\quad Var(X)=0.21$', '', '$E(X)=1\\times0.3+2\\times0.7=1.7$。$E(X^2)=1^2\\times0.3+2^2\\times0.7=3.1$，所以 $Var(X)=3.1-1.7^2=0.21$。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912190918660, 195587912190918659, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912190918662, 195587912190918661, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912190918664, 195587912190918663, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912253833219, 195587912253833218, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912253833221, 195587912253833220, 1, 'single-choice', '大数定律', '大数定律刻画的是样本均值在样本量增大时趋向于（  ）', '[{\"key\": \"A\", \"content\": \"总体方差\"}, {\"key\": \"B\", \"content\": \"总体期望\"}, {\"key\": \"C\", \"content\": \"总体中位数\"}, {\"key\": \"D\", \"content\": \"0\"}]', 'B', 'B', '大数定律说明样本均值依概率收敛到总体期望。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912253833223, 195587912253833222, 1, 'multiple-choice', '极限定理理解', '下列关于大数定律与中心极限定理的说法正确的是哪些？（多选）', '[{\"key\": \"A\", \"content\": \"中心极限定理说明标准化后的和或均值近似服从正态分布\"}, {\"key\": \"B\", \"content\": \"样本量足够大时，二项分布可用正态分布近似\"}, {\"key\": \"C\", \"content\": \"大数定律与中心极限定理讨论的是同一个结论\"}, {\"key\": \"D\", \"content\": \"中心极限定理通常需要独立同分布或相近条件\"}, {\"key\": \"E\", \"content\": \"大数定律主要回答“会趋向哪里”，中心极限定理主要回答“怎样波动”\"}]', 'ABDE', 'ABDE', 'A、B、D、E 正确；C 错，两者关注点不同。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912253833225, 195587912253833224, 1, 'fill-in', '样本均值极限', '设总体均值为 $\\mu$，则依大数定律，样本均值 $\\bar X_n$ 当 $n\\to\\infty$ 时趋向于 ____。', '[]', '$\\mu$', '', '大数定律的核心结论就是样本均值趋于总体均值。', NULL, 195585380265754624, '2026-06-28 17:16:31');
INSERT INTO `question_version` VALUES (195587912316747777, 195587912316747776, 1, 'short-answer', '中心极限定理作用', '用一句话说明中心极限定理在统计近似中的作用。', '[]', '它说明在样本量足够大时，独立同分布随机变量的和或均值经过标准化后可近似看成正态分布，因此很多概率可转化为正态分布概率来估计。', '', '这是中心极限定理最常见的应用表述。', NULL, 195585380265754624, '2026-06-28 17:16:31');
