  `question_id` bigint UNSIGNED NOT NULL,
  `question_version_id` bigint UNSIGNED NOT NULL,
  PRIMARY KEY (`collection_id`, `ordinal`) USING BTREE,
  UNIQUE INDEX `uk_ci_no_dup`(`collection_id` ASC, `question_version_id` ASC) USING BTREE,
  INDEX `idx_ci_qid`(`question_id` ASC) USING BTREE,
  INDEX `idx_ci_qvid`(`question_version_id` ASC) USING BTREE
