-- ----------------------------
-- Table structure for infra_file_metadata
-- ----------------------------
DROP TABLE IF EXISTS `infra_file_metadata`;
CREATE TABLE `infra_file_metadata`  (
  `fm_id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件唯一ID (自增生成)',
  `fm_storage_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件在物理存储中的相对路径',
  `fm_owner_identifier` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件所有者的唯一标识',
  `fm_access_level` smallint NOT NULL DEFAULT 1 COMMENT '访问级别代码 (0: PRIVATE, 1: PUBLIC)',
  `fm_original_filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始文件名',
  `fm_file_size` bigint NOT NULL COMMENT '文件大小（字节）',
  `fm_mime_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'MIME类型',
  `fm_provider` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '存储提供商（例如：local, oss）',
  `fm_created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `fm_grantees` json NULL COMMENT '被授权访问该文件的用户标识列表',
  PRIMARY KEY (`fm_id`) USING BTREE,
  INDEX `idx_infra_file_metadata_owner`(`fm_owner_identifier` ASC) USING BTREE,
  INDEX `idx_infra_file_metadata_access_level`(`fm_access_level` ASC) USING BTREE,
  INDEX `idx_infra_file_metadata_provider`(`fm_provider` ASC) USING BTREE,
  INDEX `idx_infra_file_metadata_created_at`(`fm_created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文件元数据表' ROW_FORMAT = Dynamic;

