  `question_id` bigint UNSIGNED NOT NULL,
  `question_version_id` bigint UNSIGNED NOT NULL,
  `score` decimal(6, 2) NOT NULL DEFAULT 0.00 COMMENT '本题分值',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`paper_id`, `seq`) USING BTREE,
  UNIQUE INDEX `uk_pi_no_dup`(`paper_id` ASC, `question_version_id` ASC) USING BTREE,
  INDEX `idx_pi_qid`(`question_id` ASC) USING BTREE,
  INDEX `idx_pi_qvid`(`question_version_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '试卷题目明细（绑定题目版本）' ROW_FORMAT = Dynamic;

