-- ----------------------------
-- Table structure for question
-- ----------------------------
DROP TABLE IF EXISTS `question`;
CREATE TABLE `question`  (
  `id` bigint UNSIGNED NOT NULL COMMENT 'PK',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=draft,1=active,2=archived',
  `current_version_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '当前发布版本ID（无FK，自管一致性）',
  `owner_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '创建者',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_q_status`(`status` ASC) USING BTREE,
  INDEX `idx_q_current_ver`(`current_version_id` ASC) USING BTREE,
  INDEX `idx_q_updated`(`updated_at` ASC) USING BTREE,
  INDEX `idx_q_owner_status_updated`(`owner_id` ASC, `status` ASC, `updated_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

