-- ----------------------------
-- Table structure for question_collection
-- ----------------------------
DROP TABLE IF EXISTS `question_collection`;
CREATE TABLE `question_collection`  (
  `id` bigint UNSIGNED NOT NULL COMMENT 'PK',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `owner_id` bigint UNSIGNED NOT NULL,
  `source` tinyint NOT NULL COMMENT '0=用户自建，1=系统默认',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_qc_owner_name`(`owner_id` ASC, `name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of question_collection
-- ----------------------------

-- ----------------------------
-- Table structure for question_stats
-- ----------------------------
DROP TABLE IF EXISTS `question_stats`;
CREATE TABLE `question_stats`  (
  `question_id` bigint UNSIGNED NOT NULL COMMENT '题目ID',
  `version_id` bigint UNSIGNED NOT NULL COMMENT '当前版本ID（用于join当前版本）',
  `attempts` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '作答次数',
  `correct_cnt` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '正确作答次数',
  `correct_rate` decimal(6, 4) NULL DEFAULT NULL COMMENT '正确率(0~1)，可由异步任务回填',
  `difficulty` decimal(3, 2) NULL DEFAULT NULL COMMENT '难度系数(0~1)，人工/算法标注',
  `exposure_factor` decimal(3, 2) NOT NULL DEFAULT 1.00 COMMENT '曝光强度基准值(0~1)，在 last_exposed_at 时刻的值',
  `last_exposed_at` datetime NULL DEFAULT NULL COMMENT '上次被组卷/下发时间（用于时间衰减）',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`) USING BTREE,
  INDEX `idx_qs_ver`(`version_id` ASC) USING BTREE,
  INDEX `idx_qs_exposure`(`exposure_factor` ASC) USING BTREE,
  INDEX `idx_qs_last_exposed`(`last_exposed_at` ASC) USING BTREE,
  INDEX `idx_qs_updated`(`updated_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '题目统计与曝光读模型' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of question_stats
-- ----------------------------

-- ----------------------------
-- Table structure for question_version
-- ----------------------------
DROP TABLE IF EXISTS `question_version`;
CREATE TABLE `question_version`  (
  `id` bigint UNSIGNED NOT NULL COMMENT 'PK',
  `question_id` bigint UNSIGNED NOT NULL COMMENT 'question.id（无FK）',
  `version_no` int NOT NULL COMMENT '从1递增',
  `type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '题型编码（应用层枚举 single-choice/multiple-choice 等）',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '题目标题/摘要',
  `stem` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '题干内容（可含 LaTeX 公式，但不含外层结构命令）',
  `options` json NULL COMMENT '选择题各选项',
  `answer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '参考答案（可空）',
  `answer_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '选择、填空和判断题机器判分用答案（如 A、ACD、T 等）',
  `solution` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '解析内容（可含 LaTeX 公式，不含外层结构命令）',
  `assets` json NULL COMMENT '图片/附件',
  `created_by` bigint UNSIGNED NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_qv_qid_no`(`question_id` ASC, `version_no` ASC) USING BTREE,
  INDEX `idx_qv_qid`(`question_id` ASC) USING BTREE,
  INDEX `idx_qv_type`(`type_code` ASC) USING BTREE,
  INDEX `idx_qv_created`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of question_version
-- ----------------------------

